INSERT INTO questions VALUES('96d4d16c-b53d-494a-ba7b-60534ace478a','dabf1dcb-e913-4b1a-8f87-f48b7fc46f93',replace('Match the following: (Minerals - District)\n1. Diamond  - A. Balaghat\n2. Copper   - B. Panna\n3. Manganese- C. Singrauli\n4. Coal     - D. Balaghat','\n',char(10)),'["1-B, 2-A, 3-A, 4-C","1-B, 2-A, 3-D, 4-C","1-A, 2-B, 3-C, 4-D","1-C, 2-D, 3-A, 4-B"]','0','Diamond: Panna; Copper: Malanjkhand (Balaghat); Manganese: Bharveli (Balaghat); Coal: Singrauli.',3,1,15,'MP Geography',NULL,NULL,60,'standard',NULL,NULL);
