INSERT INTO questions VALUES('a323ed44-1885-4d5d-876e-b2815320b1b1','e7db84eb-1a7c-48d9-9268-91407f647a0b','The Tropic of Cancer passes through how many districts of Madhya Pradesh?','["12","14","10","16"]','1','The Tropic of Cancer passes through 14 districts of Madhya Pradesh.',3,1,2,'MP Geography',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('66fe4df1-5349-45a2-9ffe-5e6945891868','e7db84eb-1a7c-48d9-9268-91407f647a0b','According to Census 2011, which district of MP has the highest population?','["Bhopal","Jabalpur","Indore","Sagar"]','2','Indore is the most populous district of Madhya Pradesh with a population of over 32 Lakhs (Census 2011).',3,1,3,'MP Demography',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('6c734cd5-5668-472e-b732-37dcd90a8cc5','e7db84eb-1a7c-48d9-9268-91407f647a0b','Which district of MP has the highest sex ratio as per Census 2011?','["Alirajpur","Mandla","Dindori","Balaghat"]','3','Balaghat has the highest sex ratio in MP with 1021 females per 1000 males.',3,1,4,'MP Demography',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('89c88911-e1f3-4738-bceb-fb08b6dee529','e7db84eb-1a7c-48d9-9268-91407f647a0b','Where is the new ''Veerangana Durgavati Tiger Reserve'' located?','["Sagar-Damoh-Narsinghpur","Panna-Chhatarpur","Seoni-Balaghat","Betul-Hoshangabad"]','0','The 7th Tiger Reserve of MP, Veerangana Durgavati, is spread across Sagar, Damoh, and Narsinghpur districts.',3,1,5,'MP Environment',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('acca9c67-26ca-4ace-a721-76c94ae834f2','e7db84eb-1a7c-48d9-9268-91407f647a0b','Madhya Pradesh government has announced which year to be observed as the ''Year of Agriculture''?','["2024","2025","2026","2027"]','2','The MP Government has decided to observe the year 2026 as the ''Year of Agriculture''.',3,1,6,'MP Current Affairs',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('7040bd91-7425-472b-b307-706ff6faa334','e7db84eb-1a7c-48d9-9268-91407f647a0b','Where was the ''Global Investors Summit 2025'' held in Madhya Pradesh?','["Indore","Bhopal","Gwalior","Ujjain"]','1','The Global Investors Summit 2025 was held in Bhopal on Feb 24-25, 2025.',3,1,7,'MP Current Affairs',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('19978c0a-a743-4c21-9316-5d4a3cb4d959','e7db84eb-1a7c-48d9-9268-91407f647a0b','Which city is known as the ''Energy Capital'' of Madhya Pradesh?','["Singrauli","Bhopal","Indore","Jabalpur"]','0','Singrauli is known as the Energy Capital of MP due to its large coal reserves and thermal power plants.',3,1,8,'MP Energy',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('463c2483-4b2d-4f2e-94b3-e7255e3852e5','e7db84eb-1a7c-48d9-9268-91407f647a0b','The ''Laadli Behna Yojana'' provides how much monthly financial assistance currently (Approx 2025)?','["1000","1250","1500","2000"]','1','Under the Mukhyamantri Laadli Behna Yojana, eligible women receive ₹1250 per month.',3,1,9,'MP Schemes',NULL,NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('bd2064b7-c6b1-43ae-a5ad-e3287901dec6','e7db84eb-1a7c-48d9-9268-91407f647a0b','The river Narmada originates from?','["Multai","Amarkantak","Jana-Paw","Kakri-Bardi"]','1','The Narmada River originates from the Amarkantak Plateau in Anuppur district of Madhya Pradesh.',3,1,10,'MP Geography',NULL,NULL,60,'standard',NULL,NULL);
