INSERT INTO questions VALUES('VOLtgxJVyEGZUJA78UoSZ','drcNxyFKGMfTnD-GGZ89b','''उज्ज्वल'' का सही संधि विच्छेद:','"[\"उत + ज्वल\",\"उज् + ज्वल\",\"उद + ज्वल\",\"उत + जवल\"]"','0.0','उत् + ज्वल (व्यंजन संधि)।',2,0,86,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('E37zIQNGZrVBI44-ZT6QD','drcNxyFKGMfTnD-GGZ89b','''नीलकमल'' में समास है:','"[\"कर्मधारय\",\"तत्पुरुष\",\"द्विगु\",\"द्वंद्व\"]"','0.0','नीला है जो कमल (विशेषण-विशेष्य)।',2,0,87,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('Tb_2eUAz0iUK09oRkmUe6','drcNxyFKGMfTnD-GGZ89b','''कर्पूर'' का तद्भव रूप है:','"[\"कपूर\",\"कपड़ा\",\"करकट\",\"कपाट\"]"','0.0','कपूर।',2,0,88,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('F_aNMnf10W6Gndpj0S2nK','drcNxyFKGMfTnD-GGZ89b','शुद्ध वाक्य चुनें:','"[\"मैं गाने की कसरत कर रहा हूँ।\",\"मैं गाने का अभ्यास कर रहा हूँ।\",\"मैं गाने का शौक कर रहा हूँ।\",\"मैं गाना कर रहा हूँ।\"]"','1.0','गाने का ''अभ्यास'' (Riyaaz) होता है।',2,0,89,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ger5oyEBRlPKKmsLr4iBh','drcNxyFKGMfTnD-GGZ89b','''अमृत'' का विलोम शब्द है:','"[\"विष\",\"सुधा\",\"पियूष\",\"जल\"]"','0.0','विष।',2,0,90,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ZoOZ64E5WUCPHRBMaQDpA','drcNxyFKGMfTnD-GGZ89b','''गागर में सागर भरना'' का अर्थ:','"[\"थोड़े में बहुत कहना\",\"मटका भरना\",\"पानी लाना\",\"अधिक बोलना\"]"','0.0','संक्षेप में बड़ी बात कहना।',2,0,91,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('DpL1193zw9bYJLaY7JizV','drcNxyFKGMfTnD-GGZ89b','वीर रस का स्थायी भाव है:','"[\"भय\",\"क्रोध\",\"उत्साह\",\"जुगुप्सा\"]"','2.0','उत्साह।',2,0,92,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('epJW9ET5RUy9qzAmai1W0','drcNxyFKGMfTnD-GGZ89b','''कनक कनक ते सौ गुनी'' में कौन सा अलंकार है?','"[\"यमक\",\"श्लेष\",\"अनुप्रास\",\"रूपक\"]"','0.0','कनक शब्द दो बार आया, अर्थ अलग (सोना, धतूरा) -> यमक।',2,0,93,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('NzQ8NQZxAZHks_Xg_nlb2','drcNxyFKGMfTnD-GGZ89b','''नाच न जाने आँगन टेढ़ा'' का अर्थ:','"[\"नाचना नहीं आना\",\"अपनी कमी छिपाने के लिए दूसरों को दोष देना\",\"आँगन खराब होना\",\"टेढ़ा चलना\"]"','1.0','अपनी अयोग्यता छिपाना।',2,0,94,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('1WODU57nY6VT6fCKIrfv_','drcNxyFKGMfTnD-GGZ89b','''स्वागत'' में कौन सी संधि है?','"[\"यण\",\"दीर्घ\",\"गुण\",\"वृद्धि\"]"','0.0','सु + आगत (उ + आ = वा) -> यण।',2,0,95,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('3UhJ21BmRju7KMv2U0Vdi','drcNxyFKGMfTnD-GGZ89b','हंसपद (^) चिह्न का प्रयोग कब होता है?','"[\"वाक्य पूरा होने पर\",\"लिखने में कुछ छूट जाने पर\",\"प्रश्न पूछने पर\",\"खुशी जाहिर करने पर\"]"','1.0','त्रुटि सुधार/छूटे शब्द के लिए।',2,0,96,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('QinbOPfblBhkLaVnSt0ak','drcNxyFKGMfTnD-GGZ89b','''कान भरना'' मुहावरे का अर्थ:','"[\"चुगली करना\",\"दवा डालना\",\"सुनाई न देना\",\"साफ करना\"]"','0.0','शिकायत/चुगली करना।',2,0,97,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('a7Mn9CqsaxEx5QtQu_qws','drcNxyFKGMfTnD-GGZ89b','कौन सा शब्द पुल्लिंग है?','"[\"नदी\",\"भाषा\",\"राष्ट्र\",\"किताब\"]"','2.0','राष्ट्र (Nation) पुल्लिंग है। नदी बहती है, भाषा बोली जाती है, किताब पढ़ी जाती है (स्त्रीलिंग)।',2,0,98,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('5UI7pHm4n-RqbcVzNmIKr','drcNxyFKGMfTnD-GGZ89b','''चरण कमल बन्दौ हरि राई'' में अलंकार:','"[\"रूपक\",\"उपमा\",\"उत्प्रेक्षा\",\"यमक\"]"','0.0','चरणों को कमल का रूप दिया गया है (रूपक)।',2,0,99,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('qaFBZhjLTLo8N8E7o7d-J','drcNxyFKGMfTnD-GGZ89b','हिन्दी वर्णमाला में स्वरों की संख्या कितनी मानी जाती है?','"[\"11\",\"13\",\"10\",\"12\"]"','0.0','मानक हिंदी में 11 स्वर हैं।',2,0,100,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('2c490f4d-d7ba-4f5c-adde-aab62c34fea2','873f7e4d-586b-4656-8a5d-638565cd40a0','ऋग्वेद के किस मंडल को ''वंश मंडल'' (Family Books) कहा जाता है, जो सबसे प्राचीन माने जाते हैं?','[{"id":"A","text":"मंडल 1 से 10 (Mandalas 1 to 10)","text_en":"मंडल 1 से 10 (Mandalas 1 to 10)"},{"id":"B","text":"मंडल 2 से 7 (Mandalas 2 to 7)","text_en":"मंडल 2 से 7 (Mandalas 2 to 7)"},{"id":"C","text":"मंडल 1 और 10 (Mandalas 1 and 10)","text_en":"मंडल 1 और 10 (Mandalas 1 and 10)"},{"id":"D","text":"मंडल 8 और 9 (Mandalas 8 and 9)","text_en":"मंडल 8 और 9 (Mandalas 8 and 9)"}]','1',replace('**✅ Correct Logic:** ऋग्वेद के मंडल 2 से 7 सबसे पुराने हैं और इन्हें विशिष्ट ऋषि परिवारों (गुत्समद, विश्वामित्र, वामदेव, अत्रि, भारद्वाज, वशिष्ठ) द्वारा रचा गया है। इन्हें ''हृदय'' (Heart) भी कहा जाता है।\n\n**💡 Exam Fact:** मंडल 1 और 10 सबसे अंत में जोड़े गए (नवीनतम) हैं। पुरुष सूक्त 10वें मंडल में है।\n\n**🧠 Memory Tip:** **2** to **7** = **T**rue **S**ages (Oldest Core).\n\n**🚫 Scam Alert:** अक्सर छात्र 1 से शुरू होने वाले विकल्प को ''पुराना'' मान लेते हैं, लेकिन यहाँ 1 और 10 ''प्रक्षेपक'' (बाद में जोड़े गए) हैं।','\n',char(10)),2,0,1,NULL,'Which Mandalas of the Rigveda are called ''Vamsha Mandalas'' (Family Books) and are considered the oldest?',replace('**✅ Correct Logic:** Mandalas 2 to 7 of the Rigveda are the oldest and were composed by specific sage families (Gritsamada, Vishvamitra, Vamadeva, Atri, Bharadwaja, Vashistha). They are also called the ''Heart''.\n\n**💡 Exam Fact:** Mandalas 1 and 10 were added last (Newest). Purusha Sukta is in the 10th Mandala.\n\n**🧠 Memory Tip:** **2** to **7** = **T**rue **S**ages (Oldest Core).\n\n**🚫 Scam Alert:** Students often assume the option starting with 1 is ''oldest'', but here 1 and 10 are later additions.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('158387d1-4146-45c7-b453-6e1e077431b9','873f7e4d-586b-4656-8a5d-638565cd40a0','निम्नलिखित में से कौन सा वेद ''गद्य और पद्य'' (Prose and Verse) दोनों में लिखा गया है?','[{"id":"A","text":"ऋग्वेद (Rigveda)","text_en":"ऋग्वेद (Rigveda)"},{"id":"B","text":"सामवेद (Samaveda)","text_en":"सामवेद (Samaveda)"},{"id":"C","text":"यजुर्वेद (Yajurveda)","text_en":"यजुर्वेद (Yajurveda)"},{"id":"D","text":"अथर्ववेद (Atharvaveda)","text_en":"अथर्ववेद (Atharvaveda)"}]','2',replace('**✅ Correct Logic:** यजुर्वेद एकमात्र ऐसा वेद है जो गद्य (Prose) और पद्य (Verse) दोनों में है। यह कर्मकांडीय वेद है। ऋग्वेद और सामवेद पूर्णतः पद्य में हैं।\n\n**💡 Exam Fact:** यजुर्वेद की दो शाखाएँ हैं: शुक्ल यजुर्वेद (केवल पद्य) और कृष्ण यजुर्वेद (गद्य और पद्य दोनों)।\n\n**🧠 Memory Tip:** **Y**ajurveda = **Y**ugma (Pair/Both prose & verse).\n\n**🚫 Scam Alert:** अथर्ववेद में भी कुछ गद्य है, लेकिन ''गद्य-पद्य'' की प्राथमिक विशेषता (Primary Feature) यजुर्वेद की मानी जाती है और आयोग इसी को सही मानता है।','\n',char(10)),2,0,2,NULL,'Which of the following Vedas is written in both ''Prose and Verse''?',replace('**✅ Correct Logic:** Yajurveda is the only Veda written in both Prose and Verse. It is a ritualistic Veda. Rigveda and Samaveda are entirely in verse.\n\n**💡 Exam Fact:** Yajurveda has two branches: Shukla (Verse only) and Krishna (Both Prose and Verse).\n\n**🧠 Memory Tip:** **Y**ajurveda = **Y**ugma (Pair/Both prose & verse).\n\n**🚫 Scam Alert:** Atharvaveda also has some prose, but the ''Prose-Verse'' distinction is the primary trademark of Yajurveda.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('d9124a73-f9de-4055-bad9-acb7825abddf','873f7e4d-586b-4656-8a5d-638565cd40a0','किस वेद को ''ब्रह्मवेद'' (Brahmaveda) या ''श्रेष्ठ वेद'' भी कहा जाता है?','[{"id":"A","text":"ऋग्वेद (Rigveda)","text_en":"ऋग्वेद (Rigveda)"},{"id":"B","text":"यजुर्वेद (Yajurveda)","text_en":"यजुर्वेद (Yajurveda)"},{"id":"C","text":"सामवेद (Samaveda)","text_en":"सामवेद (Samaveda)"},{"id":"D","text":"अथर्ववेद (Atharvaveda)","text_en":"अथर्ववेद (Atharvaveda)"}]','3',replace('**✅ Correct Logic:** अथर्ववेद के मुख्य पुरोहित को ''ब्रह्मा'' कहा जाता है जो यज्ञ का निरीक्षण करता है। इसलिए इसे ''ब्रह्मवेद'' कहते हैं। इसमें ज्ञान, धर्म, समाज और औषधि का विस्तृत वर्णन है।\n\n**💡 Exam Fact:** इसे ''अथर्वांगिरस वेद'' (Atharvangirasa Veda) भी कहा जाता है क्योंकि इसकी रचना अथर्वा और अंगिरस ऋषियों ने की।\n\n**🧠 Memory Tip:** **A**tharvaveda = **A**ll-rounder (Medicine to Magic) = Supervised by **B**rahma.\n\n**🚫 Scam Alert:** ''ब्रह्म'' शब्द सुनकर लोग ऋग्वेद (सबसे पवित्र) सोच सकते हैं, लेकिन तकनीकी नाम अथर्ववेद का है।','\n',char(10)),2,0,3,NULL,'Which Veda is also known as ''Brahmaveda'' or ''Best Veda''?',replace('**✅ Correct Logic:** The chief priest of Atharvaveda is called ''Brahma'', who supervises the sacrifice. Hence it is called ''Brahmaveda''. It details knowledge, religion, society, and medicine.\n\n**💡 Exam Fact:** It is also called ''Atharvangirasa Veda'' as it was composed by sages Atharva and Angirasa.\n\n**🧠 Memory Tip:** **A**tharvaveda = **A**ll-rounder (Medicine to Magic) = Supervised by **B**rahma.\n\n**🚫 Scam Alert:** Hearing ''Brahma'', people might guess Rigveda (holiest), but technically this title belongs to Atharvaveda.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('5ac60313-ce9e-449a-bf2b-f09d174ca8e8','873f7e4d-586b-4656-8a5d-638565cd40a0','ऋग्वेद के 7वें मंडल में वर्णित प्रसिद्ध ''दाशराज्ञ युद्ध'' (Battle of Ten Kings) किस नदी के तट पर लड़ा गया था?','[{"id":"A","text":"वितस्ता (Vitasta / Jhelum)","text_en":"वितस्ता (Vitasta / Jhelum)"},{"id":"B","text":"असिकनी (Asikni / Chenab)","text_en":"असिकनी (Asikni / Chenab)"},{"id":"C","text":"परुष्णी (Parushni / Ravi)","text_en":"परुष्णी (Parushni / Ravi)"},{"id":"D","text":"विपाशा (Vipasha / Beas)","text_en":"विपाशा (Vipasha / Beas)"}]','2',replace('**✅ Correct Logic:** यह युद्ध ''परुष्णी'' (वर्तमान रावी) नदी के तट पर भरत वंश के राजा सुदास और 10 राजाओं के संघ के बीच हुआ था। सुदास की विजय हुई थी।\n\n**💡 Exam Fact:** इस युद्ध में सुदास के पुरोहित ''वशिष्ठ'' थे, जबकि विरोधी खेमे के पुरोहित ''विश्वामित्र'' थे।\n\n**🧠 Memory Tip:** **R**avi = **R**oyal Battle (Kings). Parushni sounds like ''Punish'' (Su-das punished 10 kings).\n\n**🚫 Scam Alert:** ''वितस्ता'' (झेलम) सिकंदर-पोरस (हाइडेस्पीज) युद्ध के लिए प्रसिद्ध है, दाशराज्ञ के लिए नहीं।','\n',char(10)),2,0,4,NULL,'The famous ''Battle of Ten Kings'' (Dasharajna War) mentioned in the 7th Mandala of Rigveda was fought on the banks of which river?',replace('**✅ Correct Logic:** This war was fought on the banks of ''Parushni'' (modern Ravi) between King Sudas of Bharat clan and a confederacy of 10 kings. Sudas emerged victorious.\n\n**💡 Exam Fact:** In this war, Sudas''s priest was ''Vashistha'', while the opponent''s priest was ''Vishvamitra''.\n\n**🧠 Memory Tip:** **R**avi = **R**oyal Battle (Kings). Parushni sounds like ''Punish'' (Su-das punished 10 kings).\n\n**🚫 Scam Alert:** ''Vitasta'' (Jhelum) is famous for Alexander-Porus (Hydaspes) war, not Dasharajna.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('bb543c65-fae1-452e-a5e3-39d8ffbed767','873f7e4d-586b-4656-8a5d-638565cd40a0','वेदों को उनके ''ऋत्विक'' (प्रधान पुरोहित) से सुमेलित करें (Match the Vedas with their ''Ritvik'' / Chief Priest):','[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]','0',replace('**✅ Correct Logic:**\n* **ऋग्वेद (Hotri):** जो ऋचाओं (मंत्रों) का आह्वान करता है।\n* **यजुर्वेद (Adhvaryu):** जो यज्ञ के कर्मकांड/हवन करता है।\n* **सामवेद (Udgatri):** जो मंत्रों का गायन (Music) करता है।\n* **अथर्ववेद (Brahma):** जो यज्ञ का निरीक्षण (Supervision) करता है और त्रुटियों को सुधारता है।\n\n**💡 Exam Fact:** ''उद्गाता'' का संबंध ''उद्-गान'' (ऊंचा गाना) से है, इसलिए सामवेद (संगीत)।\n\n**🧠 Memory Tip:** **S**ama = **S**ong = **U**dgatri (Singer). **Y**aju = **Y**ajna = **A**dhvaryu (Action).\n\n**🚫 Scam Alert:** ''ब्रह्मा'' सृष्टि के रचयिता देवता अलग हैं, यहाँ ''ब्रह्मा'' एक पुरोहित का पद (Designation) है।','\n',char(10)),2,0,5,NULL,'Match the Vedas with their ''Ritvik'' / Chief Priest:',replace('**✅ Correct Logic:**\n* **Rigveda (Hotri):** Invoker of mantras.\n* **Yajurveda (Adhvaryu):** Performer of rituals/action.\n* **Samaveda (Udgatri):** Singer of hymns (Music).\n* **Atharvaveda (Brahma):** Supervisor of the sacrifice.\n\n**💡 Exam Fact:** ''Udgatri'' relates to ''Ud-gana'' (Singing high), hence Samaveda.\n\n**🧠 Memory Tip:** **S**ama = **S**ong = **U**dgatri (Singer). **Y**aju = **Y**ajna = **A**dhvaryu (Action).\n\n**🚫 Scam Alert:** ''Brahma'' the creator God is different; here ''Brahma'' is a designation of a priest.','\n',char(10)),60,'matching','[{"id":"(1)","label":"ऋग्वेद (Rigveda)","match":"होता/होतृ (Hota/Hotri)","matchId":"(b)"},{"id":"(2)","label":"यजुर्वेद (Yajurveda)","match":"अध्वर्यु (Adhvaryu)","matchId":"(a)"},{"id":"(3)","label":"सामवेद (Samaveda)","match":"उद्गाता (Udgatri)","matchId":"(d)"},{"id":"(4)","label":"अथर्ववेद (Atharvaveda)","match":"ब्रह्मा (Brahma)","matchId":"(c)"}]',NULL);
INSERT INTO questions VALUES('f76d33e5-de1a-40f8-9142-f2b89a9a7290','873f7e4d-586b-4656-8a5d-638565cd40a0','ऋग्वेद के 10वें मंडल के ''पुरुष सूक्त'' (Purusha Sukta) में पहली बार किसका उल्लेख मिलता है?','[{"id":"A","text":"गायत्री मंत्र (Gayatri Mantra)","text_en":"गायत्री मंत्र (Gayatri Mantra)"},{"id":"B","text":"चारों वर्ण (Four Varnas - Shudra included)","text_en":"चारों वर्ण (Four Varnas - Shudra included)"},{"id":"C","text":"सोम रस (Soma Rasa)","text_en":"सोम रस (Soma Rasa)"},{"id":"D","text":"सती प्रथा (Sati System)","text_en":"सती प्रथा (Sati System)"}]','1',replace('**✅ Correct Logic:** पुरुष सूक्त में पहली बार ''शूद्र'' शब्द का उल्लेख मिलता है, जहाँ विराट पुरुष के अंगों से चार वर्णों की उत्पत्ति बताई गई है (मुख से ब्राह्मण, बाहु से क्षत्रिय, जंघा से वैश्य, पैरों से शूद्र)।\n\n**💡 Exam Fact:** गायत्री मंत्र तीसरे मंडल (विश्वामित्र) में है, 10वें में नहीं।\n\n**🧠 Memory Tip:** Purusha Sukta = Body parts = Social Body (Caste System).\n\n**🚫 Scam Alert:** सती प्रथा का उल्लेख ऋग्वेद में नहीं है (कुछ विवादित श्लोक हैं, लेकिन स्पष्ट उल्लेख एरण अभिलेख, 510 ई. में मिलता है)।','\n',char(10)),2,0,6,NULL,'What is mentioned for the first time in the ''Purusha Sukta'' of the 10th Mandala of Rigveda?',replace('**✅ Correct Logic:** The ''Shudra'' word is mentioned for the first time in Purusha Sukta, describing the origin of four varnas from the Cosmic Man (Brahmin-Mouth, Kshatriya-Arms, Vaishya-Thighs, Shudra-Feet).\n\n**💡 Exam Fact:** Gayatri Mantra is in the 3rd Mandala (Vishvamitra), not the 10th.\n\n**🧠 Memory Tip:** Purusha Sukta = Body parts = Social Body (Caste System).\n\n**🚫 Scam Alert:** Sati system is not mentioned in Rigveda (clear archaeological evidence is Eran Inscription, 510 AD).','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('64815a9a-6a12-4d9e-8472-bc1afcd320bf','873f7e4d-586b-4656-8a5d-638565cd40a0','एशिया माइनर (तुर्की) के ''बोगज़-कोई'' (Boghaz-Koi) अभिलेख (1400 ई.पू.) में किन चार वैदिक देवताओं का उल्लेख मिलता है?','[{"id":"A","text":"इन्द्र, मित्र, वरुण, नासत्य (Indra, Mitra, Varuna, Nasatya)","text_en":"इन्द्र, मित्र, वरुण, नासत्य (Indra, Mitra, Varuna, Nasatya)"},{"id":"B","text":"इन्द्र, अग्नि, सोम, वरुण (Indra, Agni, Soma, Varuna)","text_en":"इन्द्र, अग्नि, सोम, वरुण (Indra, Agni, Soma, Varuna)"},{"id":"C","text":"मित्र, वरुण, यम, पूषण (Mitra, Varuna, Yama, Pushan)","text_en":"मित्र, वरुण, यम, पूषण (Mitra, Varuna, Yama, Pushan)"},{"id":"D","text":"अग्नि, सूर्य, रुद्र, विष्णु (Agni, Surya, Rudra, Vishnu)","text_en":"अग्नि, सूर्य, रुद्र, विष्णु (Agni, Surya, Rudra, Vishnu)"}]','0',replace('**✅ Correct Logic:** बोगज़-कोई अभिलेख (हित्ती और मितान्नी राजाओं के बीच संधि) में इन्द्र, मित्र, वरुण और नासत्य (अश्विनी कुमार) का साक्षी के रूप में उल्लेख है। यह वेदों की प्राचीनता और आर्यों के प्रसार का पुरातात्विक प्रमाण है।\n\n**💡 Exam Fact:** ''अग्नि'' का उल्लेख इसमें नहीं है, जबकि वेदों में अग्नि दूसरा सबसे महत्वपूर्ण देवता है। यही प्रश्न का ''ट्रिक'' पॉइंट है।\n\n**🧠 Memory Tip:** **I-M-V-N** (I Am Very Nice) = **I**ndra **M**itra **V**aruna **N**asatya.\n\n**🚫 Scam Alert:** अग्नि (Agni) विकल्प में हमेशा दिया जाता है क्योंकि वह कॉमन है, लेकिन वह बोगज़-कोई में नहीं है।','\n',char(10)),2,0,7,NULL,'Which four Vedic deities are mentioned in the ''Boghaz-Koi'' inscription (1400 BC) of Asia Minor (Turkey)?',replace('**✅ Correct Logic:** Boghaz-Koi inscription (treaty between Hittite and Mitanni kings) mentions Indra, Mitra, Varuna, and Nasatya (Ashvini Kumars) as witnesses. This is archaeological proof of Vedic antiquity.\n\n**💡 Exam Fact:** ''Agni'' is NOT mentioned, despite being the 2nd most important Vedic deity. This is the trick point.\n\n**🧠 Memory Tip:** **I-M-V-N** (I Am Very Nice) = **I**ndra **M**itra **V**aruna **N**asatya.\n\n**🚫 Scam Alert:** Agni is always in distractor options, but he is absent in Boghaz-Koi.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('9bdedc06-0a91-4dfd-beeb-53222a138023','873f7e4d-586b-4656-8a5d-638565cd40a0',replace('कथन (A): ''वाजसनेयी संहिता'' (Vajasaneyi Samhita) केवल शुक्ल यजुर्वेद से संबंधित है।\nकारण (R): याज्ञवल्क्य ने इसे सूर्य से प्राप्त किया था।\nसही विकल्प चुनें:','\n',char(10)),'[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]','1',replace('**✅ Correct Logic:** याज्ञवल्क्य ने अपने गुरु वैशम्पायन से विवाद के बाद ''शुक्ल'' (श्वेत/शुद्ध) यजुर्वेद की रचना की, जो उन्हें सूर्य ने ''वाजी'' (घोड़े) के रूप में प्रकट होकर सिखाई। इसलिए इसे ''वाजसनेयी संहिता'' कहते हैं।\n\n**💡 Exam Fact:** शुक्ल यजुर्वेद की दो शाखाएँ हैं: काण्व और माध्यन्दिन।\n\n**🧠 Memory Tip:** Vaji = Horse = Sun''s Chariot = **Vajasaneyi**.\n\n**🚫 Scam Alert:** कृष्ण यजुर्वेद को ''तैत्तिरीय'' आदि कहा जाता है। वाजसनेयी केवल शुक्ल है।','\n',char(10)),2,0,8,NULL,replace('Assertion (A): ''Vajasaneyi Samhita'' is related only to Shukla Yajurveda.\nReason (R): Yajnavalkya received it from the Sun (Surya).\nSelect the correct option:','\n',char(10)),replace('**✅ Correct Logic:** After a dispute with his Guru Vaishampayana, Yajnavalkya composed ''Shukla'' (White/Pure) Yajurveda, which was taught to him by the Sun in the form of a ''Vaji'' (Horse). Hence it is called ''Vajasaneyi Samhita''.\n\n**💡 Exam Fact:** Shukla Yajurveda has two branches: Kanva and Madhyandina.\n\n**🧠 Memory Tip:** Vaji = Horse = Sun''s Chariot = **Vajasaneyi**.\n\n**🚫 Scam Alert:** Krishna Yajurveda is called Taittiriya etc. Vajasaneyi is exclusively Shukla.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('e68be350-846c-41da-93ee-1c43ddd5b522','873f7e4d-586b-4656-8a5d-638565cd40a0','''त्रयी'' (Trayi) में अथर्ववेद को शामिल न करने का मुख्य कारण क्या था?','[{"id":"A","text":"यह सबसे बाद में लिखा गया (It was written last)","text_en":"यह सबसे बाद में लिखा गया (It was written last)"},{"id":"B","text":"इसकी भाषा अलग थी (Its language was different)","text_en":"इसकी भाषा अलग थी (Its language was different)"},{"id":"C","text":"इसकी विषय-वस्तु यज्ञ से भिन्न लौकिक/जादू-टोना थी (Its subject matter was worldly/magical charms, unlike sacrifices)","text_en":"इसकी विषय-वस्तु यज्ञ से भिन्न लौकिक/जादू-टोना थी (Its subject matter was worldly/magical charms, unlike sacrifices)"},{"id":"D","text":"यह आर्यों द्वारा नहीं लिखा गया (It was not written by Aryans)","text_en":"यह आर्यों द्वारा नहीं लिखा गया (It was not written by Aryans)"}]','2',replace('**✅ Correct Logic:** वेदत्रयी (ऋक, यजु, साम) का मुख्य उद्देश्य ''यज्ञ'' (Sacrifice) था। अथर्ववेद में शांति-पुष्टि, अभिचार, रोग-निवारण (Magic/Medicine) जैसे लौकिक विषय थे, इसलिए इसे आरंभ में ''त्रयी'' में नहीं गिना गया।\n\n**💡 Exam Fact:** गोपथ ब्राह्मण अथर्ववेद का एकमात्र ब्राह्मण ग्रंथ है।\n\n**🧠 Memory Tip:** Trayi = Triangle of Worship. Atharva = Outside the box (Real world issues).\n\n**🚫 Scam Alert:** कालक्रम (Chronology) एक कारक है, लेकिन ''मुख्य कारण'' विषय-वस्तु (Content) की भिन्नता थी।','\n',char(10)),2,0,9,NULL,'What was the main reason for not including Atharvaveda in ''Trayi''?',replace('**✅ Correct Logic:** The main purpose of Vedatrayi (Rik, Yaju, Sama) was ''Yajna''. Atharvaveda dealt with worldly topics like charms, medicine, and magic, hence it was initially excluded.\n\n**💡 Exam Fact:** Gopatha Brahmana is the only Brahmana text of Atharvaveda.\n\n**🧠 Memory Tip:** Trayi = Triangle of Worship. Atharva = Outside the box (Real world issues).\n\n**🚫 Scam Alert:** Chronology is a factor, but the ''Primary Reason'' was the difference in Content.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('fc0f4750-5926-4461-a888-174f51e4e20f','873f7e4d-586b-4656-8a5d-638565cd40a0','ऋग्वेद में ''अघन्या'' (Aghanya) शब्द का प्रयोग किसके लिए किया गया है?','[{"id":"A","text":"ब्राह्मण (Brahmin)","text_en":"ब्राह्मण (Brahmin)"},{"id":"B","text":"गाय (Cow)","text_en":"गाय (Cow)"},{"id":"C","text":"स्त्री (Woman)","text_en":"स्त्री (Woman)"},{"id":"D","text":"राजा (King)","text_en":"राजा (King)"}]','1',replace('**✅ Correct Logic:** ''अघन्या'' का अर्थ है ''न मारे जाने योग्य'' (Not to be killed)। ऋग्वेद में गाय का आर्थिक और धार्मिक महत्व सर्वाधिक था, इसलिए उसे अघन्या कहा गया।\n\n**💡 Exam Fact:** ''गविष्ठि'' (Gavishti) शब्द का प्रयोग ''युद्ध'' के लिए होता था, जिसका शाब्दिक अर्थ है ''गायों की खोज''।\n\n**🧠 Memory Tip:** A-ghanya = **A**-**G**au (Not to kill Gau).\n\n**🚫 Scam Alert:** वैदिक काल में बलि दी जाती थी, लेकिन दुधारू गाय को ''अघन्या'' माना जाता था।','\n',char(10)),2,0,10,NULL,'In Rigveda, the term ''Aghanya'' is used for:',replace('**✅ Correct Logic:** ''Aghanya'' means ''Not to be killed''. The cow had immense economic and religious value in Rigveda, hence called Aghanya.\n\n**💡 Exam Fact:** The word ''Gavishti'' was used for ''War'', literally meaning ''Search for Cows''.\n\n**🧠 Memory Tip:** A-ghanya = **A**-**G**au (Not to kill Gau).\n\n**🚫 Scam Alert:** Sacrifices existed, but the milch cow was considered Aghanya.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('6fb73f95-6a6e-428b-8e44-e8abe41dfe07','bd237dd0-b66d-482f-b8cf-cad3808532cb','प्राचीनतम और सर्वाधिक प्रामाणिक स्मृति कौन सी मानी जाती है?','[{"id":"A","text":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)","text_en":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)"},{"id":"B","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"C","text":"नारद स्मृति (Narada Smriti)","text_en":"नारद स्मृति (Narada Smriti)"},{"id":"D","text":"पराशर स्मृति (Parashara Smriti)","text_en":"पराशर स्मृति (Parashara Smriti)"}]','1',replace('**✅ Correct Logic:** ''मनुस्मृति'' को सबसे प्राचीन (शुंग काल, लगभग 200 ई.पू.) और भारतीय धर्मशास्त्र का आधार स्तंभ माना जाता है।\n\n**💡 Exam Fact:** विलियम जोन्स ने 1776 में इसका अंग्रेजी अनुवाद ''A Code of Gentoo Laws'' के नाम से किया था।\n\n**🧠 Memory Tip:** Manu = First Man = First Smriti.\n\n**🚫 Scam Alert:** वेद (श्रुति) प्राचीनतम हैं, लेकिन ''स्मृतियों'' में मनुस्मृति प्रथम है।','\n',char(10)),2,0,1,NULL,'Which is considered the oldest and most authoritative Smriti?',replace('**✅ Correct Logic:** ''Manusmriti'' is considered the oldest (Shunga period, approx 200 BC) and the cornerstone of Indian Dharmashastra.\n\n**💡 Exam Fact:** William Jones translated it into English as ''A Code of Gentoo Laws'' in 1776.\n\n**🧠 Memory Tip:** Manu = First Man = First Smriti.\n\n**🚫 Scam Alert:** Vedas (Shruti) are oldest, but among ''Smritis'', Manusmriti is the first.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('b4bc53d1-1856-41e4-877f-b13a832ab3f0','bd237dd0-b66d-482f-b8cf-cad3808532cb','''मिताक्षरा'' (Mitakshara) टीका, जो हिंदू उत्तराधिकार कानून का आधार है, किस स्मृति पर लिखी गई है?','[{"id":"A","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"B","text":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)","text_en":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)"},{"id":"C","text":"नारद स्मृति (Narada Smriti)","text_en":"नारद स्मृति (Narada Smriti)"},{"id":"D","text":"बृहस्पति स्मृति (Brihaspati Smriti)","text_en":"बृहस्पति स्मृति (Brihaspati Smriti)"}]','1',replace('**✅ Correct Logic:** ''मिताक्षरा'' विज्ञानेश्वर द्वारा लिखी गई ''याज्ञवल्क्य स्मृति'' की टीका है। यह जन्मना अधिकार (Right by birth) के सिद्धांत को मानती है।\n\n**💡 Exam Fact:** ''दायभाग'' (जीमूतवाहन) बंगाल में प्रचलित थी, जबकि ''मिताक्षरा'' शेष भारत में।\n\n**🧠 Memory Tip:** **Y**ajnavalkya = **Y**our property (Inheritance law).\n\n**🚫 Scam Alert:** मनुस्मृति पर ''मन्वर्थमुक्तावली'' (कुल्लूक भट्ट) टीका है, मिताक्षरा याज्ञवल्क्य पर है।','\n',char(10)),2,0,2,NULL,'The ''Mitakshara'' commentary, which is the basis of Hindu Succession Law, is written on which Smriti?',replace('**✅ Correct Logic:** ''Mitakshara'' is a commentary on ''Yajnavalkya Smriti'' written by Vijnaneshwara. It upholds the principle of Right by Birth.\n\n**💡 Exam Fact:** ''Dayabhaga'' (Jimutavahana) was prevalent in Bengal, while ''Mitakshara'' in the rest of India.\n\n**🧠 Memory Tip:** **Y**ajnavalkya = **Y**our property (Inheritance law).\n\n**🚫 Scam Alert:** Manusmriti has ''Manvarthamuktavali'' (Kulluka Bhatta) commentary; Mitakshara is on Yajnavalkya.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ef4fb416-d4ce-4ec0-bf52-f329acc6640b','bd237dd0-b66d-482f-b8cf-cad3808532cb','गुप्त काल में लिखी गई वह स्मृति कौन सी है जो दासों की मुक्ति (Emancipation of Slaves) के विस्तृत नियम बताती है?','[{"id":"A","text":"कात्यायन स्मृति (Katyayana Smriti)","text_en":"कात्यायन स्मृति (Katyayana Smriti)"},{"id":"B","text":"नारद स्मृति (Narada Smriti)","text_en":"नारद स्मृति (Narada Smriti)"},{"id":"C","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"D","text":"देवल स्मृति (Devala Smriti)","text_en":"देवल स्मृति (Devala Smriti)"}]','1',replace('**✅ Correct Logic:** ''नारद स्मृति'' (गुप्त काल) दासों के प्रकार और उनकी मुक्ति के अनुष्ठान का विस्तृत वर्णन करती है। यह व्यवहार (Law) प्रधान स्मृति है।\n\n**💡 Exam Fact:** इसमें ''नियोग प्रथा'' और ''स्त्रियों के पुनर्विवाह'' की अनुमति दी गई है।\n\n**🧠 Memory Tip:** **N**arada = **N**ew Freedom (Slaves).\n\n**🚫 Scam Alert:** मनुस्मृति दासों के प्रति कठोर थी, नारद स्मृति उदार थी।','\n',char(10)),2,0,3,NULL,'Which Smriti written in the Gupta period provides detailed rules for the ''Emancipation of Slaves''?',replace('**✅ Correct Logic:** ''Narada Smriti'' (Gupta Period) details the types of slaves and rituals for their emancipation. It is a Law-centric Smriti.\n\n**💡 Exam Fact:** It permits ''Niyoga'' and ''Remarriage of women''.\n\n**🧠 Memory Tip:** **N**arada = **N**ew Freedom (Slaves).\n\n**🚫 Scam Alert:** Manusmriti was harsh on slaves; Narada Smriti was liberal.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ed3dde75-b256-4545-8fcd-99f94b0ed789','bd237dd0-b66d-482f-b8cf-cad3808532cb',replace('कथन (A): स्मृतियों को ''धर्मशास्त्र'' भी कहा जाता है।\nकारण (R): स्मृतियाँ वेदों (श्रुति) पर आधारित नहीं हैं, बल्कि स्वतंत्र ग्रंथ हैं।\nसही विकल्प चुनें:','\n',char(10)),'[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]','2',replace('**✅ Correct Logic:** स्मृतियाँ धर्मशास्त्र कहलाती हैं (A सही है)। लेकिन, स्मृतियों की प्रमाणिकता वेदों (श्रुति) पर ही आधारित है। जहाँ श्रुति और स्मृति में विरोध हो, वहां श्रुति मान्य होती है (R गलत है)। वे स्वतंत्र नहीं हैं।\n\n**💡 Exam Fact:** ''श्रुतिस्तु वेदो विज्ञेयो धर्मशास्त्रं तु वै स्मृतिः'' (मनुस्मृति 2.10)।\n\n**🧠 Memory Tip:** Smriti is the **Memory** of Shruti. It depends on Shruti.\n\n**🚫 Scam Alert:** स्मृतियाँ वेदों का व्यावहारिक रूप हैं, उनसे अलग नहीं।','\n',char(10)),2,0,4,NULL,replace('Assertion (A): Smritis are also called ''Dharmashastra''.\nReason (R): Smritis are not based on Vedas (Shruti) but are independent texts.\nSelect the correct option:','\n',char(10)),replace('**✅ Correct Logic:** Smritis are called Dharmashastra (A is true). However, the authority of Smritis rests on the Vedas (Shruti). Where Shruti and Smriti conflict, Shruti prevails (R is false). They are not independent.\n\n**💡 Exam Fact:** ''Shrutistu Vedo Vijneyo Dharmashastram Tu Vai Smritih'' (Manusmriti 2.10).\n\n**🧠 Memory Tip:** Smriti is the **Memory** of Shruti. It depends on Shruti.\n\n**🚫 Scam Alert:** Smritis are practical applications of Vedas, not separate from them.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('0a5cb6dd-25bc-4c71-b2b0-30f77fb17b5c','bd237dd0-b66d-482f-b8cf-cad3808532cb','प्रमुख स्मृतियों और उनके टीकाकारों (Commentators) को सुमेलित करें (Match the major Smritis with their Commentators):','[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]','0',replace('**✅ Correct Logic:**\n* **मनुस्मृति:** मेधातिथि, कुल्लूक भट्ट, गोविंदराज।\n* **याज्ञवल्क्य:** विज्ञानेश्वर (मिताक्षरा), अपरार्क, विश्वरूप।\n* **नारद:** असहाय (Asahaya)।\n* **पराशर:** माधवाचार्य (कालनिर्णय)।\n\n**💡 Exam Fact:** मेधातिथि ने सती प्रथा का विरोध किया था।\n\n**🧠 Memory Tip:** **M**anu = **M**edhatithi. **Y**ajnavalkya = **V**ijnaneshwara (Scientific Law).\n\n**🚫 Scam Alert:** जीमूतवाहन ने ''दायभाग'' लिखी जो एक स्वतंत्र निबंध है, किसी स्मृति की सीधी टीका नहीं, लेकिन अक्सर याज्ञवल्क्य से जुड़ी मानी जाती है।','\n',char(10)),2,0,5,NULL,'Match the major Smritis with their Commentators:',replace('**✅ Correct Logic:**\n* **Manusmriti:** Medhatithi, Kulluka Bhatta, Govindaraja.\n* **Yajnavalkya:** Vijnaneshwara (Mitakshara), Apararka, Vishvarupa.\n* **Narada:** Asahaya.\n* **Parashara:** Madhavacharya.\n\n**💡 Exam Fact:** Medhatithi opposed the Sati system.\n\n**🧠 Memory Tip:** **M**anu = **M**edhatithi. **Y**ajnavalkya = **V**ijnaneshwara (Scientific Law).\n\n**🚫 Scam Alert:** Jimutavahana wrote ''Dayabhaga'', which is a digest, not a direct commentary, but often linked to Yajnavalkya traditions.','\n',char(10)),60,'matching','[{"id":"(1)","label":"मनुस्मृति (Manusmriti)","match":"मेधातिथि (Medhatithi)","matchId":"(c)"},{"id":"(2)","label":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)","match":"विज्ञानेश्वर (Vijnaneshwara)","matchId":"(a)"},{"id":"(3)","label":"नारद स्मृति (Narada Smriti)","match":"असहाय (Asahaya)","matchId":"(d)"},{"id":"(4)","label":"पराशर स्मृति (Parashara Smriti)","match":"माधवाचार्य (Madhavacharya)","matchId":"(b)"}]',NULL);
INSERT INTO questions VALUES('06922e1d-d368-49b9-adf1-21e113e1e5b0','bd237dd0-b66d-482f-b8cf-cad3808532cb','पूर्व-मध्यकाल (Pre-Medieval) में विदेश यात्रा से लौटकर आए लोगों की ''शुद्धि'' के लिए किस स्मृति में विधान मिलते हैं?','[{"id":"A","text":"देवल स्मृति (Devala Smriti)","text_en":"देवल स्मृति (Devala Smriti)"},{"id":"B","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"C","text":"विष्णु स्मृति (Vishnu Smriti)","text_en":"विष्णु स्मृति (Vishnu Smriti)"},{"id":"D","text":"हारीत स्मृति (Harita Smriti)","text_en":"हारीत स्मृति (Harita Smriti)"}]','0',replace('**✅ Correct Logic:** ''देवल स्मृति'' (सिंध में अरब आक्रमण के बाद) में उन हिंदुओं को वापस धर्म में लेने के नियम बनाए गए जिन्हें जबरन धर्म परिवर्तन कराया गया था या जो म्लेच्छ संपर्क में आए थे।\n\n**💡 Exam Fact:** यह धर्म की लचीली व्यवस्था का प्रमाण है।\n\n**🧠 Memory Tip:** **D**evala = **D**efense against conversion.\n\n**🚫 Scam Alert:** मनुस्मृति पुरानी है, देवल स्मृति मध्यकाल के आरंभ की है जो इस समस्या (धर्मांतरण) को संबोधित करती है।','\n',char(10)),2,0,6,NULL,'Which Smriti provides rules for the ''Shuddhi'' (Purification) of people returning from foreign travel in the Pre-Medieval period?',replace('**✅ Correct Logic:** ''Devala Smriti'' (post-Arab invasion in Sindh) laid down rules to reconvert Hindus who were forcibly converted or came in contact with Mlechhas.\n\n**💡 Exam Fact:** This proves the flexibility of Dharma.\n\n**🧠 Memory Tip:** **D**evala = **D**efense against conversion.\n\n**🚫 Scam Alert:** Manusmriti is older; Devala Smriti belongs to early medieval times addressing this specific issue (conversion).','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('da17065a-eb18-4f45-b789-3edef7bb6220','bd237dd0-b66d-482f-b8cf-cad3808532cb','किस स्मृति में ''कलिवर्ज्य'' (Kali-Varjya) का सिद्धांत मिलता है, जिसके तहत कलियुग में कुछ प्राचीन प्रथाओं (जैसे नियोग, गोमेध) को वर्जित किया गया?','[{"id":"A","text":"पाराशर स्मृति (Parashara Smriti)","text_en":"पाराशर स्मृति (Parashara Smriti)"},{"id":"B","text":"बृहस्पति स्मृति (Brihaspati Smriti)","text_en":"बृहस्पति स्मृति (Brihaspati Smriti)"},{"id":"C","text":"नारद स्मृति (Narada Smriti)","text_en":"नारद स्मृति (Narada Smriti)"},{"id":"D","text":"गौतम स्मृति (Gautama Smriti)","text_en":"गौतम स्मृति (Gautama Smriti)"}]','2',replace('**✅ Correct Logic:** वैसे तो कई पुराणों और स्मृतियों में इसका जिक्र है, लेकिन ''नारद'' और ''बृहस्पति'' स्मृतियाँ कलियुग के लिए बदले हुए नियमों की बात करती हैं। हालाँकि, ''पराशर स्मृति'' विशेष रूप से कलियुग के लिए ही लिखी गई मानी जाती है ("कलौ पाराशरः स्मृतः")। (Note: If asking specifically about banning practices, texts like Aditya Purana are cited, but among options, Parashara defines Kaliyuga duties most distinctly). *आयोग ''पराशर'' को कलियुग की स्मृति मानता है।*\n\n**💡 Exam Fact:** पराशर स्मृति कहती है: सत्ययुग में मनु, त्रेता में गौतम, द्वापर में शंख-लिखित और कलियुग में पराशर मान्य हैं।\n\n**🧠 Memory Tip:** **P**arashara = **P**resent era (Kaliyuga).\n\n**🚫 Scam Alert:** ''कलिवर्ज्य'' एक सिद्धांत है जो बाद के निबंधों में विस्तृत हुआ, लेकिन पराशर स्मृति कलियुग की अथॉरिटी है।','\n',char(10)),2,0,7,NULL,'Which Smriti mentions the principle of ''Kali-Varjya'', under which certain ancient practices (like Niyoga, Gomedha) were forbidden in Kaliyuga?',replace('**✅ Correct Logic:** While many texts mention this, ''Parashara Smriti'' is specifically considered authoritative for Kaliyuga ("Kalau Parasharah Smritah"). It defines duties relevant to the age.\n\n**💡 Exam Fact:** Parashara Smriti states: Manu for Satya, Gautama for Treta, Shankha-Likhita for Dwapara, and Parashara for Kaliyuga.\n\n**🧠 Memory Tip:** **P**arashara = **P**resent era (Kaliyuga).\n\n**🚫 Scam Alert:** ''Kali-Varjya'' is a principle detailed in later digests, but Parashara is the authority for Kaliyuga.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('e88e1c55-a7fe-4a48-ba9e-1b8edd0fbec9','bd237dd0-b66d-482f-b8cf-cad3808532cb','मनुस्मृति में विवाह के कितने प्रकारों (Forms of Marriage) का उल्लेख है?','[{"id":"A","text":"4","text_en":"4"},{"id":"B","text":"6","text_en":"6"},{"id":"C","text":"8","text_en":"8"},{"id":"D","text":"10","text_en":"10"}]','2',replace('**✅ Correct Logic:** मनुस्मृति में 8 प्रकार के विवाह बताए गए हैं।\n* **प्रशस्त (Valid):** ब्रह्म, दैव, आर्ष, प्रजापत्य।\n* **अप्रशस्त (Invalid/Sinful):** आसुर, गंधर्व, राक्षस, पैशाच।\n\n**💡 Exam Fact:** ''पैशाच'' विवाह को सबसे निकृष्ट (Worst) माना गया है (सोती हुई कन्या से जबरदस्ती)।\n\n**🧠 Memory Tip:** 4 Good + 4 Bad = **8** Marriages.\n\n**🚫 Scam Alert:** गंधर्व विवाह (Love marriage) को निंदनीय श्रेणी में रखा गया था, भले ही दुष्यंत-शकुंतला ने किया था।','\n',char(10)),2,0,8,NULL,'How many forms of Marriage are mentioned in Manusmriti?',replace('**✅ Correct Logic:** Manusmriti mentions 8 forms of marriage.\n* **Prashasta (Valid):** Brahma, Daiva, Arsha, Prajapatya.\n* **Aprashasta (Invalid):** Asura, Gandharva, Rakshasa, Paishacha.\n\n**💡 Exam Fact:** ''Paishacha'' is considered the worst (forcing a sleeping girl).\n\n**🧠 Memory Tip:** 4 Good + 4 Bad = **8** Marriages.\n\n**🚫 Scam Alert:** Gandharva (Love marriage) was in the condemned category, even though Dushyanta-Shakuntala did it.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('cbd8b8aa-2f12-4712-a951-02e125e7114b','bd237dd0-b66d-482f-b8cf-cad3808532cb','गद्य (Prose) में लिखी गई स्मृति कौन सी है?','[{"id":"A","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"B","text":"विष्णु स्मृति (Vishnu Smriti)","text_en":"विष्णु स्मृति (Vishnu Smriti)"},{"id":"C","text":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)","text_en":"याज्ञवल्क्य स्मृति (Yajnavalkya Smriti)"},{"id":"D","text":"नारद स्मृति (Narada Smriti)","text_en":"नारद स्मृति (Narada Smriti)"}]','1',replace('**✅ Correct Logic:** अधिकांश स्मृतियाँ पद्य (Shlokas) में हैं, लेकिन ''विष्णु स्मृति'' मुख्य रूप से गद्य (Prose) में है। यह सूत्र शैली के करीब है।\n\n**💡 Exam Fact:** इसमें मुद्राओं (Coins) का उल्लेख मिलता है।\n\n**🧠 Memory Tip:** Vishnu = Different avatar = Different style (**Prose**).\n\n**🚫 Scam Alert:** यह एक तथ्यात्मक अपवाद है, इसे रटना होगा।','\n',char(10)),2,0,9,NULL,'Which Smriti is written in Prose?',replace('**✅ Correct Logic:** Most Smritis are in Verse (Shlokas), but ''Vishnu Smriti'' is primarily in Prose. It is close to the Sutra style.\n\n**💡 Exam Fact:** It mentions coins.\n\n**🧠 Memory Tip:** Vishnu = Different avatar = Different style (**Prose**).\n\n**🚫 Scam Alert:** This is a factual exception, memorize it.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('929a0dfa-4920-43f5-9fdb-8b01c885d1fe','bd237dd0-b66d-482f-b8cf-cad3808532cb','1882 में ''नारद स्मृति'' का अंग्रेजी अनुवाद किसने किया था?','[{"id":"A","text":"मैक्स मूलर (Max Muller)","text_en":"मैक्स मूलर (Max Muller)"},{"id":"B","text":"जूलियस जॉली (Julius Jolly)","text_en":"जूलियस जॉली (Julius Jolly)"},{"id":"C","text":"विलियम जोन्स (William Jones)","text_en":"विलियम जोन्स (William Jones)"},{"id":"D","text":"एच.एच. विल्सन (H.H. Wilson)","text_en":"एच.एच. विल्सन (H.H. Wilson)"}]','1',replace('**✅ Correct Logic:** जर्मन विद्वान जूलियस जॉली (Julius Jolly) ने नारद स्मृति का अनुवाद किया। उन्होंने इसे ''Minor Law Books'' की श्रेणी में रखा।\n\n**💡 Exam Fact:** विलियम जोन्स ने मनुस्मृति का अनुवाद किया था।\n\n**🧠 Memory Tip:** Narada is jolly (happy) sage → Translated by **Jolly**.\n\n**🚫 Scam Alert:** मैक्स मूलर ने वेदों पर काम किया, लेकिन नारद स्मृति के लिए जॉली प्रसिद्ध हैं।','\n',char(10)),2,0,10,NULL,'Who translated ''Narada Smriti'' into English in 1882?',replace('**✅ Correct Logic:** German scholar Julius Jolly translated Narada Smriti. He categorized it under ''Minor Law Books''.\n\n**💡 Exam Fact:** William Jones translated Manusmriti.\n\n**🧠 Memory Tip:** Narada is jolly (happy) sage → Translated by **Jolly**.\n\n**🚫 Scam Alert:** Max Muller worked on Vedas, but Jolly is famous for Narada Smriti.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('289e2345-e927-4ce4-be28-a715812d4903','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','ऋग्वेद में ''ऋत'' (Ṛta) का मूल अर्थ क्या है?','[{"id":"A","text":"देवताओं का भोजन (Food of Gods)","text_en":"देवताओं का भोजन (Food of Gods)"},{"id":"B","text":"प्राकृतिक और नैतिक व्यवस्था (Natural and Moral Order)","text_en":"प्राकृतिक और नैतिक व्यवस्था (Natural and Moral Order)"},{"id":"C","text":"यज्ञ की विधि (Method of Sacrifice)","text_en":"यज्ञ की विधि (Method of Sacrifice)"},{"id":"D","text":"युद्ध का नियम (Rule of War)","text_en":"युद्ध का नियम (Rule of War)"}]','1',replace('**✅ Correct Logic:** ऋत का अर्थ है ''ब्रह्मांडीय व्यवस्था'' (Cosmic Order)। यह वह नियम है जिससे सूर्य उगता है, ऋतुएँ बदलती हैं, और मनुष्य नैतिकता का पालन करता है। यह सत्य (Satya) से भी ऊपर है।\n\n**💡 Exam Fact:** ईरानी ग्रंथ ''अवेस्ता'' में इसे ''अशा'' (Asha) कहा गया है।\n\n**🧠 Memory Tip:** Rit = **Rit**ual of Universe (Order).\n\n**🚫 Scam Alert:** ''यज्ञ'' ऋत को बनाए रखने का साधन है, ऋत स्वयं यज्ञ नहीं है।','\n',char(10)),2,0,1,NULL,'What is the basic meaning of ''Ṛta'' in Rigveda?',replace('**✅ Correct Logic:** Ṛta means ''Cosmic Order''. It is the law by which the sun rises, seasons change, and humans follow morality. It is even higher than Truth (Satya).\n\n**💡 Exam Fact:** In the Iranian text ''Avesta'', it is called ''Asha''.\n\n**🧠 Memory Tip:** Rit = **Rit**ual of Universe (Order).\n\n**🚫 Scam Alert:** ''Yajna'' is a tool to maintain Ṛta, Ṛta itself is not Yajna.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('d383306c-5abe-4973-bdcd-0eb1250f73d2','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','किस वैदिक देवता को ''ऋतस्य गोपा'' (Guardian of Ṛta) कहा जाता है?','[{"id":"A","text":"इन्द्र (Indra)","text_en":"इन्द्र (Indra)"},{"id":"B","text":"अग्नि (Agni)","text_en":"अग्नि (Agni)"},{"id":"C","text":"वरुण (Varuna)","text_en":"वरुण (Varuna)"},{"id":"D","text":"मित्र (Mitra)","text_en":"मित्र (Mitra)"}]','2',replace('**✅ Correct Logic:** वरुण देवता को ऋत (नैतिक व्यवस्था) का संरक्षक माना जाता है। वे पापियों को अपने ''पाश'' (Noose) में बांधकर दंड देते हैं और व्यवस्था बनाए रखते हैं।\n\n**💡 Exam Fact:** वरुण को ''असुर'' (Ahura) की उपाधि भी दी गई है।\n\n**🧠 Memory Tip:** **V**aruna = **V**igilance officer of Order.\n\n**🚫 Scam Alert:** मित्र भी वरुण के साथ होते हैं, लेकिन ''गोपा'' (रक्षक) की उपाधि मुख्य रूप से वरुण की है।','\n',char(10)),2,0,2,NULL,'Which Vedic deity is called ''Ritasya Gopa'' (Guardian of Ṛta)?',replace('**✅ Correct Logic:** Varuna is considered the protector of Ṛta (Moral Order). He binds sinners with his ''Pasha'' (Noose) and maintains order.\n\n**💡 Exam Fact:** Varuna is also given the title ''Asura'' (Ahura).\n\n**🧠 Memory Tip:** **V**aruna = **V**igilance officer of Order.\n\n**🚫 Scam Alert:** Mitra accompanies Varuna, but the title ''Gopa'' primarily belongs to Varuna.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('9a302adb-1427-46f5-aa5a-9c74ad96ed5b','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e',replace('कथन (A): ''ऋत'' और ''सत्य'' एक ही सिक्के के दो पहलू माने जाते हैं।\nकारण (R): ऋग्वेद के ''अघमर्षण सूक्त'' में कहा गया है कि तप से ऋत और सत्य दोनों की उत्पत्ति हुई।\nसही विकल्प चुनें:','\n',char(10)),'[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]','0',replace('**✅ Correct Logic:** ऋत ''मानसिक'' सत्य (Concept) है और सत्य ''वाचिक'' (Spoken) अभिव्यक्ति है। दोनों की उत्पत्ति ''तप'' से मानी गई है (ऋग्वेद 10.190)। यह संबंध दिखाता है कि वे अविभाज्य हैं।\n\n**💡 Exam Fact:** ऋत सृष्टि के आरंभ में ही उत्पन्न हुआ था।\n\n**🧠 Memory Tip:** Rit + Satya = Twin brothers from Tapas.\n\n**🚫 Scam Alert:** दोनों कथन सही हैं और R, A की पुष्टि करता है।','\n',char(10)),2,0,3,NULL,replace('Assertion (A): ''Ṛta'' and ''Satya'' are considered two sides of the same coin.\nReason (R): The ''Aghamarshana Sukta'' of Rigveda states that both Ṛta and Satya were born from Tapas (Heat/Austerity).\nSelect the correct option:','\n',char(10)),replace('**✅ Correct Logic:** Ṛta is ''mental'' truth (Concept) and Satya is ''spoken'' expression. Both originated from ''Tapas'' (Rigveda 10.190). This relationship shows they are inseparable.\n\n**💡 Exam Fact:** Ṛta originated at the very beginning of creation.\n\n**🧠 Memory Tip:** Rit + Satya = Twin brothers from Tapas.\n\n**🚫 Scam Alert:** Both statements are true and R supports A.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('5f11e1e7-dce0-44e7-9717-57e856b7576d','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','''ऋत'' के विभिन्न आयामों को सुमेलित करें (Match the different dimensions of ''Ṛta''):','[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]','0',replace('**✅ Correct Logic:** ऋत एक व्यापक अवधारणा है:\n* नेचर में: ग्रहों की गति।\n* मोरल में: ईमानदारी।\n* धर्म में: यज्ञ।\n\n**💡 Exam Fact:** जब ऋत का उल्लंघन होता है तो उसे ''अनृत'' (Anrita) या पाप कहते हैं, जिससे वरुण कुपित होते हैं।\n\n**🧠 Memory Tip:** Rit covers everything from Sky (Sun) to Heart (Truth).\n\n**🚫 Scam Alert:** यह एक बहुआयामी अवधारणा है, केवल ''प्रकृति'' तक सीमित नहीं है।','\n',char(10)),2,0,5,NULL,'Match the different dimensions of ''Ṛta'':',replace('**✅ Correct Logic:** Ṛta is a comprehensive concept:\n* In Nature: Planetary motion.\n* In Morality: Honesty.\n* In Religion: Sacrifice.\n\n**💡 Exam Fact:** Violation of Ṛta is called ''Anrita'' or Sin, which angers Varuna.\n\n**🧠 Memory Tip:** Rit covers everything from Sky (Sun) to Heart (Truth).\n\n**🚫 Scam Alert:** It is multidimensional, not limited to just ''Nature''.','\n',char(10)),60,'matching','[{"id":"(1)","label":"प्राकृतिक स्तर पर (Natural Level)","match":"सूर्य-चंद्र की गति, ऋतु परिवर्तन (Movement of Sun/Moon, Seasons)","matchId":"(b)"},{"id":"(2)","label":"नैतिक स्तर पर (Moral Level)","match":"पाप-पुण्य, सत्य-असत्य का भेद (Sin-Virtue, Truth-Falsehood)","matchId":"(a)"},{"id":"(3)","label":"धार्मिक स्तर पर (Religious Level)","match":"यज्ञ और कर्मकांड का सही विधि से पालन (Proper performance of Rituals)","matchId":"(d)"},{"id":"(4)","label":"सामाजिक स्तर पर (Social Level)","match":"समाज में नियमों का पालन (Following rules in society)","matchId":"(c)"}]',NULL);
INSERT INTO questions VALUES('dd1eda90-b138-4279-99cf-4bf3126fbde1','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','ऋत के पतन और ''धर्म'' (Dharma) के उदय का कारण क्या माना जाता है?','[{"id":"A","text":"वरुण देवता का महत्व कम होना (Decline in importance of Varuna)","text_en":"वरुण देवता का महत्व कम होना (Decline in importance of Varuna)"},{"id":"B","text":"समाज की जटिलता और नियमों की आवश्यकता (Complexity of society and need for rules)","text_en":"समाज की जटिलता और नियमों की आवश्यकता (Complexity of society and need for rules)"},{"id":"C","text":"उत्तर वैदिक काल में कर्मकांडों की वृद्धि (Rise of rituals in Later Vedic period)","text_en":"उत्तर वैदिक काल में कर्मकांडों की वृद्धि (Rise of rituals in Later Vedic period)"},{"id":"D","text":"उपर्युक्त सभी (All of the above)","text_en":"उपर्युक्त सभी (All of the above)"}]','3',replace('**✅ Correct Logic:** ऋग्वेद में ''ऋत'' प्रधान था (स्वचालित व्यवस्था)। उत्तर वैदिक काल में वरुण का स्थान प्रजापति ने लिया, कर्मकांड बढ़े और ''धर्म'' (नियम/कर्तव्य) ने ऋत का स्थान ले लिया।\n\n**💡 Exam Fact:** धर्म का मूल ''धृ'' धातु से है (धारण करना), जो ऋत (cosmic law) का व्यावहारिक सामाजिक रूप बन गया।\n\n**🧠 Memory Tip:** Varuna down, Prajapati up → Rit down, Dharma up.\n\n**🚫 Scam Alert:** ''सभी'' (All) सही है क्योंकि यह एक क्रमिक ऐतिहासिक प्रक्रिया थी।','\n',char(10)),2,0,4,NULL,'What is considered the reason for the decline of Ṛta and the rise of ''Dharma''?',replace('**✅ Correct Logic:** In Rigveda, ''Ṛta'' was dominant (Self-regulated order). In Later Vedic period, Prajapati replaced Varuna, rituals increased, and ''Dharma'' (Rules/Duty) took the place of Ṛta.\n\n**💡 Exam Fact:** Dharma comes from root ''Dhri'' (to sustain), becoming the practical social form of Ṛta.\n\n**🧠 Memory Tip:** Varuna down, Prajapati up → Rit down, Dharma up.\n\n**🚫 Scam Alert:** ''All'' is correct as it was a gradual historical process.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('17abe141-c214-4bdf-95d4-72b062da98c9','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','''ऋत'' शब्द का विलोम (Antonym) ऋग्वेद में क्या प्रयोग हुआ है?','[{"id":"A","text":"असत्य (Asatya)","text_en":"असत्य (Asatya)"},{"id":"B","text":"अनृत (Anrita)","text_en":"अनृत (Anrita)"},{"id":"C","text":"अधर्म (Adharma)","text_en":"अधर्म (Adharma)"},{"id":"D","text":"तमस (Tamas)","text_en":"तमस (Tamas)"}]','1',replace('**✅ Correct Logic:** ऋत का विलोम ''अनृत'' (Anrita) है, जिसका अर्थ है अव्यवस्था या झूठ। ''सत्य'' का विलोम ''असत्य'' है।\n\n**💡 Exam Fact:** ''न हि प्रवेद सुकृतस्य पन्थामिति ऋतेन'' (ऋग्वेद) - बिना ऋत के सुकृत का मार्ग नहीं मिलता।\n\n**🧠 Memory Tip:** Rit vs An-rit (Like A-satya).\n\n**🚫 Scam Alert:** ''अधर्म'' बाद का शब्द है। वैदिक संदर्भ में ''अनृत'' सही तकनीकी शब्द है।','\n',char(10)),2,0,6,NULL,'What antonym for the word ''Ṛta'' is used in the Rigveda?',replace('**✅ Correct Logic:** The antonym of Ṛta is ''Anrita'', meaning chaos or falsehood. The antonym of Satya is Asatya.\n\n**💡 Exam Fact:** Without Ṛta, one cannot find the path of virtue.\n\n**🧠 Memory Tip:** Rit vs An-rit (Like A-satya).\n\n**🚫 Scam Alert:** ''Adharma'' is a later term. In Vedic context, ''Anrita'' is the correct technical term.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('98d946bd-d41b-4c91-9cd1-78c0cdc809f0','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','किस विद्वान ने ऋत को ''Moral Order'' (नैतिक व्यवस्था) कहा है?','[{"id":"A","text":"मैक्स मूलर (Max Muller)","text_en":"मैक्स मूलर (Max Muller)"},{"id":"B","text":"पी.वी. काणे (P.V. Kane)","text_en":"पी.वी. काणे (P.V. Kane)"},{"id":"C","text":"ए.बी. कीथ (A.B. Keith)","text_en":"ए.बी. कीथ (A.B. Keith)"},{"id":"D","text":"राधाकृष्णन (Radhakrishnan)","text_en":"राधाकृष्णन (Radhakrishnan)"}]','0',replace('**✅ Correct Logic:** मैक्स मूलर ने ऋत की व्याख्या करते हुए इसे भौतिक नियमों से परे ''नैतिक व्यवस्था'' (Moral Law) कहा जो देवताओं और मनुष्यों दोनों पर लागू होती है।\n\n**💡 Exam Fact:** कीथ ने इसे ''Cosmic Order'' पर जोर दिया।\n\n**🧠 Memory Tip:** **M**ax Muller = **M**oral Order.\n\n**🚫 Scam Alert:** भारतीय दर्शन के आधुनिक व्याख्याकार राधाकृष्णन भी इसे मानते हैं, लेकिन पाश्चात्य विद्वानों में मैक्स मूलर का नाम आता है।','\n',char(10)),2,0,7,NULL,'Which scholar has termed Ṛta as ''Moral Order''?',replace('**✅ Correct Logic:** Max Muller interpreted Ṛta as ''Moral Law'' beyond physical laws, applicable to both gods and humans.\n\n**💡 Exam Fact:** Keith emphasized ''Cosmic Order''.\n\n**🧠 Memory Tip:** **M**ax Muller = **M**oral Order.\n\n**🚫 Scam Alert:** Radhakrishnan also agrees, but among western scholars, Max Muller is cited.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('4c23980b-6b6e-4b3c-a7fb-f025b2903ef6','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','ऋग्वेद में सूर्य को किसका ''चक्षु'' (Eye) माना गया है जो ऋत का निरीक्षण करता है?','[{"id":"A","text":"इन्द्र (Indra)","text_en":"इन्द्र (Indra)"},{"id":"B","text":"वरुण और मित्र (Varuna and Mitra)","text_en":"वरुण और मित्र (Varuna and Mitra)"},{"id":"C","text":"अग्नि (Agni)","text_en":"अग्नि (Agni)"},{"id":"D","text":"सोम (Soma)","text_en":"सोम (Soma)"}]','1',replace('**✅ Correct Logic:** सूर्य को ''मित्र और वरुण का नेत्र'' (चक्षुः मित्रस्य वरुणस्य) कहा गया है। सूर्य आकाश से सब कुछ देखता है और वरुण को रिपोर्ट करता है कि कौन ऋत का पालन कर रहा है।\n\n**💡 Exam Fact:** वरुण को ''हजार आंखों वाला'' (Thousand-eyed) भी कहा जाता है।\n\n**🧠 Memory Tip:** Sun is the CCTV camera of Police Chief (Varuna).\n\n**🚫 Scam Alert:** सूर्य स्वयं देवता है, लेकिन पदानुक्रम में यहाँ वह वरुण के एजेंट/नेत्र के रूप में कार्य करता है।','\n',char(10)),2,0,8,NULL,'In Rigveda, the Sun is considered the ''Eye'' of whom, inspecting the Ṛta?',replace('**✅ Correct Logic:** The Sun is called the ''Eye of Mitra and Varuna'' (Chakshuh Mitrasya Varunasya). The Sun sees everything from the sky and reports to Varuna who is following Ṛta.\n\n**💡 Exam Fact:** Varuna is also called ''Thousand-eyed''.\n\n**🧠 Memory Tip:** Sun is the CCTV camera of Police Chief (Varuna).\n\n**🚫 Scam Alert:** Sun is a deity himself, but in this hierarchy, he acts as the eye/agent of Varuna.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ab0e84f2-dbe9-4750-b505-85acff620906','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','''ऋत'' की अवधारणा आधुनिक विज्ञान के किस सिद्धांत के निकट प्रतीत होती है?','[{"id":"A","text":"विकासवाद (Evolution)","text_en":"विकासवाद (Evolution)"},{"id":"B","text":"प्राकृतिक नियम / एकरूपता (Natural Laws / Uniformity of Nature)","text_en":"प्राकृतिक नियम / एकरूपता (Natural Laws / Uniformity of Nature)"},{"id":"C","text":"सापेक्षता (Relativity)","text_en":"सापेक्षता (Relativity)"},{"id":"D","text":"क्वांटम यांत्रिकी (Quantum Mechanics)","text_en":"क्वांटम यांत्रिकी (Quantum Mechanics)"}]','1',replace('**✅ Correct Logic:** ऋत का अर्थ है कि ब्रह्मांड यादृच्छिक (Random) नहीं है, बल्कि निश्चित नियमों (Laws of Nature) से चलता है। यह विज्ञान के ''Uniformity of Nature'' के सिद्धांत के समान है।\n\n**💡 Exam Fact:** यह दिखाता है कि वैदिक ऋषि वैज्ञानिक सोच रखते थे।\n\n**🧠 Memory Tip:** Sun always rises in East = Rule = Rit.\n\n**🚫 Scam Alert:** यह एक वैचारिक तुलना है।','\n',char(10)),2,0,9,NULL,'The concept of ''Ṛta'' seems close to which principle of modern science?',replace('**✅ Correct Logic:** Ṛta means the universe is not Random, but functions by definite Laws of Nature. This is similar to the scientific principle of ''Uniformity of Nature''.\n\n**💡 Exam Fact:** This shows Vedic sages had scientific thinking.\n\n**🧠 Memory Tip:** Sun always rises in East = Rule = Rit.\n\n**🚫 Scam Alert:** This is a conceptual comparison.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('f7982209-8d60-441c-a8bb-ccbef71a30d0','0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e','ऋत के कितने स्तर (Levels) माने गए हैं?','[{"id":"A","text":"2 (सत्य और धर्म)","text_en":"2 (सत्य और धर्म)"},{"id":"B","text":"3 (गति, संहिता, धर्म)","text_en":"3 (गति, संहिता, धर्म)"},{"id":"C","text":"3 (प्राकृतिक, नैतिक, धार्मिक)","text_en":"3 (प्राकृतिक, नैतिक, धार्मिक)"},{"id":"D","text":"4 (धर्म, अर्थ, काम, मोक्ष)","text_en":"4 (धर्म, अर्थ, काम, मोक्ष)"}]','2',replace('**✅ Correct Logic:** ऋत त्रिस्तरीय है: 1. **प्राकृतिक** (ग्रहों की गति), 2. **नैतिक** (मनुष्य का आचरण), 3. **धार्मिक** (यज्ञ/कर्मकांड)।\n\n**💡 Exam Fact:** यह त्रिविध विभाजन वैदिक विश्वदृष्टि का आधार है।\n\n**🧠 Memory Tip:** Nature + Rituals + Morals = 3 Levels.\n\n**🚫 Scam Alert:** पुरुषार्थ (4) अलग हैं।','\n',char(10)),2,0,10,NULL,'How many levels of Ṛta are considered?',replace('**✅ Correct Logic:** Ṛta is three-level: 1. **Natural** (Planetary motion), 2. **Moral** (Human conduct), 3. **Religious** (Rituals).\n\n**💡 Exam Fact:** This threefold division is the basis of Vedic worldview.\n\n**🧠 Memory Tip:** Nature + Rituals + Morals = 3 Levels.\n\n**🚫 Scam Alert:** Purusharthas (4) are different.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('f2ed3a8c-71ed-4069-b610-e69b58c50423','86893312-7cbb-4e59-872a-ec210b0b282e','अथर्ववेद में ''सभा'' और ''समिति'' को किसकी दो ''पुत्रियाँ'' कहा गया है?','[{"id":"A","text":"इन्द्र (Indra)","text_en":"इन्द्र (Indra)"},{"id":"B","text":"प्रजापति (Prajapati)","text_en":"प्रजापति (Prajapati)"},{"id":"C","text":"अग्नि (Agni)","text_en":"अग्नि (Agni)"},{"id":"D","text":"वरुण (Varuna)","text_en":"वरुण (Varuna)"}]','1',replace('**✅ Correct Logic:** अथर्ववेद (7.12.1) में कहा गया है: "सभा च मा समितिश्चावतां प्रजापतेर्दुहितरौ संविदाने।" (प्रजापति की दो पुत्रियाँ, सभा और समिति, मेरी रक्षा करें)। यह उनकी महत्ता को दर्शाता है।\n\n**💡 Exam Fact:** इससे पता चलता है कि राजा की शक्ति इन संस्थाओं पर निर्भर थी।\n\n**🧠 Memory Tip:** Praja (People) -> Prajapati -> Daughters (Assemblies of People).\n\n**🚫 Scam Alert:** यह सबसे कॉमन प्रश्न है, प्रजापति सही उत्तर है।','\n',char(10)),2,0,1,NULL,'In Atharvaveda, ''Sabha'' and ''Samiti'' are called the two ''daughters'' of whom?',replace('**✅ Correct Logic:** Atharvaveda (7.12.1) states: "Sabha cha ma Samitis chavatam Prajapater duhitarau samvidane." (May the two daughters of Prajapati, Sabha and Samiti, protect me). This shows their importance.\n\n**💡 Exam Fact:** It indicates the King''s power depended on these institutions.\n\n**🧠 Memory Tip:** Praja (People) -> Prajapati -> Daughters (Assemblies of People).\n\n**🚫 Scam Alert:** This is the most common question, Prajapati is the answer.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('8e5ac60c-b6f5-4cfc-bb85-314f786622f9','86893312-7cbb-4e59-872a-ec210b0b282e','''सभा'' (Sabha) मुख्य रूप से किस प्रकार के लोगों की संस्था थी?','[{"id":"A","text":"आम जनता (General Public)","text_en":"आम जनता (General Public)"},{"id":"B","text":"कुलीन और वृद्ध जन (Elite and Elders)","text_en":"कुलीन और वृद्ध जन (Elite and Elders)"},{"id":"C","text":"केवल सैनिक (Only Soldiers)","text_en":"केवल सैनिक (Only Soldiers)"},{"id":"D","text":"केवल महिलाएं (Only Women)","text_en":"केवल महिलाएं (Only Women)"}]','1',replace('**✅ Correct Logic:** ''सभा'' कुलीन, श्रेष्ठ और वृद्ध लोगों (Elders/Elite) की छोटी संस्था थी जो न्यायिक कार्य (Judicial functions) भी करती थी। ''सुजात'' (Well-born) लोग इसमें होते थे।\n\n**💡 Exam Fact:** ऋग्वेद में सभा का उल्लेख 8 बार हुआ है।\n\n**🧠 Memory Tip:** Sabha = **S**ophisticated people (Elite).\n\n**🚫 Scam Alert:** ''समिति'' आम जनता की बड़ी संस्था थी। सभा छोटी और विशिष्ट थी।','\n',char(10)),2,0,2,NULL,'''Sabha'' was primarily an assembly of what kind of people?',replace('**✅ Correct Logic:** ''Sabha'' was a small assembly of Elite, Noble, and Elder people which also performed judicial functions. ''Sujata'' (Well-born) people were part of it.\n\n**💡 Exam Fact:** Sabha is mentioned 8 times in Rigveda.\n\n**🧠 Memory Tip:** Sabha = **S**ophisticated people (Elite).\n\n**🚫 Scam Alert:** ''Samiti'' was the large assembly of general public. Sabha was small and exclusive.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('2880c579-ccfb-4a14-8044-e0a9698b72f4','86893312-7cbb-4e59-872a-ec210b0b282e','ऋग्वैदिक काल में ''समिति'' (Samiti) का अध्यक्ष क्या कहलाता था?','[{"id":"A","text":"सभापति (Sabhapati)","text_en":"सभापति (Sabhapati)"},{"id":"B","text":"ईशान (Ishan)","text_en":"ईशान (Ishan)"},{"id":"C","text":"ग्रामणी (Gramani)","text_en":"ग्रामणी (Gramani)"},{"id":"D","text":"पुरोहित (Purohit)","text_en":"पुरोहित (Purohit)"}]','1',replace('**✅ Correct Logic:** समिति के अध्यक्ष को ''ईशान'' (Ishan) कहा जाता था। समिति में राजा का चुनाव/निर्वाचन होता था और राजा को समिति में उपस्थित होना अनिवार्य था।\n\n**💡 Exam Fact:** ऋग्वेद में समिति का उल्लेख 9 बार हुआ है।\n\n**🧠 Memory Tip:** Samiti is Big -> Ishan (Lord/Head).\n\n**🚫 Scam Alert:** सभा का अध्यक्ष ''सभापति'' था। समिति का अध्यक्ष ''ईशान'' था।','\n',char(10)),2,0,3,NULL,'What was the President of the ''Samiti'' called in the Rigvedic period?',replace('**✅ Correct Logic:** The President of the Samiti was called ''Ishan''. The Samiti elected the King, and it was mandatory for the King to attend the Samiti.\n\n**💡 Exam Fact:** Samiti is mentioned 9 times in Rigveda.\n\n**🧠 Memory Tip:** Samiti is Big -> Ishan (Lord/Head).\n\n**🚫 Scam Alert:** Head of Sabha was ''Sabhapati''. Head of Samiti was ''Ishan''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('bed276c5-5c53-4e83-900a-1fdeacf26c61','86893312-7cbb-4e59-872a-ec210b0b282e',replace('कथन (A): ऋग्वैदिक काल में महिलाएं ''सभा'' और ''विदय'' में भाग लेती थीं।\nकारण (R): उत्तर वैदिक काल में महिलाओं का सभा में प्रवेश वर्जित हो गया।\nसही विकल्प चुनें:','\n',char(10)),'[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है। (Both A and R are true...)","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है। (Both A and R are true...)"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है। (Both A and R are true but R is not correct explanation...)","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है। (Both A and R are true but R is not correct explanation...)"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]','1',replace('**✅ Correct Logic:** ऋग्वेद में महिलाओं को ''सभावती'' कहा गया है, जो उनके भाग लेने का प्रमाण है। मैत्रायणी संहिता (उत्तर वैदिक) में महिला को पासा और सुरा के साथ बुराई माना गया और सभा में उनका प्रवेश बंद हो गया।\n\n**💡 Exam Fact:** ''विदथ'' (Vidatha) सबसे प्राचीन संस्था थी।\n\n**🧠 Memory Tip:** Vedic Women = Free. Later Vedic Women = Restricted.\n\n**🚫 Scam Alert:** दोनों कथन सत्य हैं। R, A की व्याख्या नहीं करता बल्कि एक ऐतिहासिक परिवर्तन (Change) बताता है।','\n',char(10)),2,0,4,NULL,replace('Assertion (A): In Rigvedic period, women participated in ''Sabha'' and ''Vidatha''.\nReason (R): In Later Vedic period, entry of women in Sabha was prohibited.\nSelect the correct option:','\n',char(10)),replace('**✅ Correct Logic:** In Rigveda, women are called ''Sabhavati'', proving their participation. In Maitrayani Samhita (Later Vedic), women were classed with dice and wine as evils, and their entry was banned.\n\n**💡 Exam Fact:** ''Vidatha'' was the oldest institution.\n\n**🧠 Memory Tip:** Vedic Women = Free. Later Vedic Women = Restricted.\n\n**🚫 Scam Alert:** Both are true. R does not explain A, but states a historical change.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('9693cbb3-0f83-4ef1-acb0-e657bbc124f6','86893312-7cbb-4e59-872a-ec210b0b282e','वैदिक संस्थाओं और उनकी विशेषताओं को सुमेलित करें (Match the Vedic institutions with their features):','[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)","text_en":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)"},{"id":"D","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"}]','0',replace('**✅ Correct Logic:**\n* **सभा:** ''नरिष्टा'' (जिसका निर्णय टाला न जा सके) - न्यायिक।\n* **समिति:** केंद्रीय राजनीतिक संस्था।\n* **विदथ:** आर्यों की प्राचीनतम संस्था, उपज/लूट का बंटवारा।\n* **गण:** छोटी इकाई।\n\n**💡 Exam Fact:** ऋग्वेद में विदथ का उल्लेख सर्वाधिक (122 बार) हुआ है।\n\n**🧠 Memory Tip:** **V**idatha = **V**riddha (Oldest). Samiti = Mass. Sabha = Select.\n\n**🚫 Scam Alert:** विदथ सबसे पुरानी है, इसे याद रखें।','\n',char(10)),2,0,5,NULL,'Match the Vedic institutions with their features:',replace('**✅ Correct Logic:**\n* **Sabha:** ''Narishtha'' (Inviolable decision) - Judicial.\n* **Samiti:** Central political body.\n* **Vidatha:** Oldest institution, distribution of booty/produce.\n* **Gana:** Small unit.\n\n**💡 Exam Fact:** Vidatha is mentioned most times (122) in Rigveda.\n\n**🧠 Memory Tip:** **V**idatha = **V**riddha (Oldest). Samiti = Mass. Sabha = Select.\n\n**🚫 Scam Alert:** Vidatha is the oldest, remember this.','\n',char(10)),60,'matching','[{"id":"(1)","label":"सभा (Sabha)","match":"न्यायिक कार्य और कुलीन संस्था (Judicial work and Elite body)","matchId":"(c)"},{"id":"(2)","label":"समिति (Samiti)","match":"राजा का चुनाव करने वाली आम सभा (General assembly electing the King)","matchId":"(a)"},{"id":"(3)","label":"विदथ (Vidatha)","match":"लूट का बंटवारा और प्राचीनतम जनसभा (Distribution of booty and Oldest assembly)","matchId":"(d)"},{"id":"(4)","label":"गण (Gana)","match":"सैनिक टुकड़ी या कुलीन तंत्र (Troop or Oligarchy)","matchId":"(b)"}]',NULL);
INSERT INTO questions VALUES('4560e5e3-be20-4925-b233-0a2e15ae25b4','86893312-7cbb-4e59-872a-ec210b0b282e','अथर्ववेद में सभा के लिए ''नरिष्टा'' (Narishtha) शब्द का प्रयोग हुआ है। इसका अर्थ क्या है?','[{"id":"A","text":"महिलाओं की सभा (Assembly of Women)","text_en":"महिलाओं की सभा (Assembly of Women)"},{"id":"B","text":"जिसका निर्णय टाला/उल्लंघन न किया जा सके (Whose decision cannot be violated/overturned)","text_en":"जिसका निर्णय टाला/उल्लंघन न किया जा सके (Whose decision cannot be violated/overturned)"},{"id":"C","text":"राजा का महल (King''s Palace)","text_en":"राजा का महल (King''s Palace)"},{"id":"D","text":"सैनिकों का समूह (Group of Soldiers)","text_en":"सैनिकों का समूह (Group of Soldiers)"}]','1',replace('**✅ Correct Logic:** ''नरिष्टा'' का अर्थ है सामूहिक वाद-विवाद के बाद लिया गया निर्णय जो ''अलंघनीय'' (Inviolable) हो। यह सभा की न्यायिक शक्ति (Judicial Power) को दर्शाता है।\n\n**💡 Exam Fact:** सयुंक्त निर्णय से बंधे होने की भावना लोकतंत्र की जड़ थी।\n\n**🧠 Memory Tip:** Na-Rishta (Not to be broken).\n\n**🚫 Scam Alert:** ''नारी'' शब्द देखकर ''महिलाओं की सभा'' न सोचें।','\n',char(10)),2,0,6,NULL,'The word ''Narishtha'' is used for Sabha in Atharvaveda. What does it mean?',replace('**✅ Correct Logic:** ''Narishtha'' means a decision taken after collective debate which is ''Inviolable''. It shows the Judicial Power of the Sabha.\n\n**💡 Exam Fact:** The spirit of being bound by collective decision was the root of democracy.\n\n**🧠 Memory Tip:** Na-Rishta (Not to be broken).\n\n**🚫 Scam Alert:** Don''t confuse ''Nari'' with ''Women''s Assembly''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('091c91ce-329c-49cf-9a7b-88855803fb3d','86893312-7cbb-4e59-872a-ec210b0b282e','उत्तर वैदिक काल में सभा और समिति के महत्व में गिरावट का मुख्य कारण क्या था?','[{"id":"A","text":"राजा की शक्ति में वृद्धि और बड़े राज्यों (जनपदों) का उदय (Increase in King''s power and rise of large states/Janapadas)","text_en":"राजा की शक्ति में वृद्धि और बड़े राज्यों (जनपदों) का उदय (Increase in King''s power and rise of large states/Janapadas)"},{"id":"B","text":"विदेशी आक्रमण (Foreign Invasions)","text_en":"विदेशी आक्रमण (Foreign Invasions)"},{"id":"C","text":"जनसंख्या में कमी (Decrease in Population)","text_en":"जनसंख्या में कमी (Decrease in Population)"},{"id":"D","text":"वैदिक धर्म का पतन (Decline of Vedic Religion)","text_en":"वैदिक धर्म का पतन (Decline of Vedic Religion)"}]','0',replace('**✅ Correct Logic:** जैसे-जैसे ''जन'' (Tribes) मिलकर ''जनपद'' (Territorial States) बने, क्षेत्र बड़ा हो गया। दूर-दराज के लोगों का समिति की बैठकों में आना मुश्किल हो गया। साथ ही, राजा की शक्ति (दैवीय सिद्धांत) बढ़ने से जनसभाएं कमजोर हो गईं।\n\n**💡 Exam Fact:** ब्राह्मणों और अमीरों का प्रभुत्व सभा में बढ़ गया।\n\n**🧠 Memory Tip:** Big Kingdom = King becomes Boss = Public Assembly ignored.\n\n**🚫 Scam Alert:** विदेशी आक्रमण बहुत बाद में हुए। मुख्य कारण आंतरिक राजनीतिक परिवर्तन था।','\n',char(10)),2,0,7,NULL,'What was the main reason for the decline in importance of Sabha and Samiti in the Later Vedic period?',replace('**✅ Correct Logic:** As ''Janas'' (Tribes) merged into ''Janapadas'' (Territorial States), the area became large. It became difficult for distant people to attend meetings. Also, King''s power (Divine Theory) increased, weakening assemblies.\n\n**💡 Exam Fact:** Domination of Brahmins and Nobles increased in Sabha.\n\n**🧠 Memory Tip:** Big Kingdom = King becomes Boss = Public Assembly ignored.\n\n**🚫 Scam Alert:** Foreign invasions happened much later. Main reason was internal political change.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('8c5dae8c-2dbf-469f-b3bb-74a135001a02','86893312-7cbb-4e59-872a-ec210b0b282e','''रत्निन'' (Ratnin) कौन थे जो राजा के चुनाव या राज्याभिषेक में महत्वपूर्ण भूमिका निभाते थे?','[{"id":"A","text":"राज्य के उच्च पदाधिकारी (High officials of the state)","text_en":"राज्य के उच्च पदाधिकारी (High officials of the state)"},{"id":"B","text":"राजा के पुत्र (Sons of the King)","text_en":"राजा के पुत्र (Sons of the King)"},{"id":"C","text":"विदेशी राजदूत (Foreign Ambassadors)","text_en":"विदेशी राजदूत (Foreign Ambassadors)"},{"id":"D","text":"धार्मिक गुरु (Religious Gurus)","text_en":"धार्मिक गुरु (Religious Gurus)"}]','0',replace('**✅ Correct Logic:** उत्तर वैदिक काल में 12 ''रत्निन'' (Jewels/Officials) होते थे (जैसे सेनानी, पुरोहित, ग्रामणी, सूत)। राजा को राज्याभिषेक के समय इनके घर जाकर ''रत्नहवि'' यज्ञ करना पड़ता था, जो यह दिखाता है कि राजा को उनके समर्थन की आवश्यकता थी।\n\n**💡 Exam Fact:** ''पालागल'' (विदूषक/संदेशवाहक) भी रत्निनों में शामिल था।\n\n**🧠 Memory Tip:** Ratnin = Jewels of the State Cabinet.\n\n**🚫 Scam Alert:** ये केवल मंत्री नहीं थे, बल्कि ''King Makers'' थे।','\n',char(10)),2,0,8,NULL,'Who were the ''Ratnins'' who played an important role in the King''s election or coronation?',replace('**✅ Correct Logic:** In Later Vedic period, there were 12 ''Ratnins'' (High Officials like Senani, Purohit, Gramani). The King had to perform ''Ratnahavi'' sacrifice at their homes, showing he needed their support.\n\n**💡 Exam Fact:** ''Palagala'' (Messenger/Jester) was also a Ratnin.\n\n**🧠 Memory Tip:** Ratnin = Jewels of the State Cabinet.\n\n**🚫 Scam Alert:** They were not just ministers, but ''King Makers''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('7f8b91d5-a812-45d1-ad39-ccf3be6c3070','86893312-7cbb-4e59-872a-ec210b0b282e','ऋग्वेद में ''विदथ'' (Vidatha) के बारे में कौन सा तथ्य सही है?','[{"id":"A","text":"यह सबसे नवीन संस्था थी (It was the newest institution)","text_en":"यह सबसे नवीन संस्था थी (It was the newest institution)"},{"id":"B","text":"इसका कोई राजनीतिक महत्व नहीं था (It had no political importance)","text_en":"इसका कोई राजनीतिक महत्व नहीं था (It had no political importance)"},{"id":"C","text":"यह धार्मिक, सैनिक और आर्थिक (लूट का बंटवारा) कार्य करती थी (It performed religious, military, and economic/booty distribution functions)","text_en":"यह धार्मिक, सैनिक और आर्थिक (लूट का बंटवारा) कार्य करती थी (It performed religious, military, and economic/booty distribution functions)"},{"id":"D","text":"इसमें केवल ब्राह्मण भाग लेते थे (Only Brahmins participated)","text_en":"इसमें केवल ब्राह्मण भाग लेते थे (Only Brahmins participated)"}]','2',replace('**✅ Correct Logic:** विदथ एक बहुउद्देशीय (Multi-purpose) संस्था थी। इसमें युद्ध में जीती गई लूट का सामूहिक बंटवारा होता था। यह कबीलाई साम्यवाद (Tribal Communism) का उदाहरण है।\n\n**💡 Exam Fact:** आर.एस. शर्मा के अनुसार विदथ प्राचीनतम है।\n\n**🧠 Memory Tip:** Vidatha = **Vi**vidh (Various) functions.\n\n**🚫 Scam Alert:** विदथ केवल धार्मिक नहीं थी, आर्थिक (बंटवारा) पहलू महत्वपूर्ण था।','\n',char(10)),2,0,9,NULL,'Which fact is correct about ''Vidatha'' in Rigveda?',replace('**✅ Correct Logic:** Vidatha was a multi-purpose institution. Collective distribution of war booty happened here. Example of Tribal Communism.\n\n**💡 Exam Fact:** According to R.S. Sharma, it is the oldest.\n\n**🧠 Memory Tip:** Vidatha = **Vi**vidh (Various) functions.\n\n**🚫 Scam Alert:** Vidatha was not just religious; economic (distribution) aspect was key.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ef1513d2-eac6-4197-b7da-50a8a53f572a','86893312-7cbb-4e59-872a-ec210b0b282e','निम्नलिखित में से कौन ''समिति'' के सत्रों में भाग ले सकता था?','[{"id":"A","text":"केवल राजा के मंत्री (Only King''s Ministers)","text_en":"केवल राजा के मंत्री (Only King''s Ministers)"},{"id":"B","text":"जनपद के सभी स्वतंत्र नागरिक/विश (All free citizens/Vish of the Janapada)","text_en":"जनपद के सभी स्वतंत्र नागरिक/विश (All free citizens/Vish of the Janapada)"},{"id":"C","text":"केवल क्षत्रिय (Only Kshatriyas)","text_en":"केवल क्षत्रिय (Only Kshatriyas)"},{"id":"D","text":"केवल पुरोहित (Only Priests)","text_en":"केवल पुरोहित (Only Priests)"}]','1',replace('**✅ Correct Logic:** समिति ''विश'' (जनता) की प्रतिनिधि संस्था थी। इसमें कबीले के सभी वयस्क स्वतंत्र नागरिक भाग ले सकते थे और अपनी राय (Voting) दे सकते थे।\n\n**💡 Exam Fact:** समिति में वाद-विवाद जीतने वाले को महत्व मिलता था।\n\n**🧠 Memory Tip:** Samiti = **Sam**uh (Crowd/Public).\n\n**🚫 Scam Alert:** सभा विशिष्ट थी, समिति आम थी।','\n',char(10)),2,0,10,NULL,'Who among the following could participate in the sessions of ''Samiti''?',replace('**✅ Correct Logic:** Samiti was the representative body of ''Vish'' (People). All adult free citizens could participate and vote.\n\n**💡 Exam Fact:** One who won debates in Samiti was respected.\n\n**🧠 Memory Tip:** Samiti = **Sam**uh (Crowd/Public).\n\n**🚫 Scam Alert:** Sabha was elite, Samiti was common.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('49df1692-c938-4591-a99b-b7379b05b4b4','15a46e2a-ac67-4384-b7e1-864f61398a70','बुद्ध काल में विश्व का सबसे बड़ा और शक्तिशाली ''गणतंत्र'' (Republic) कौन सा था?','[{"id":"A","text":"शाक्य (Shakya)","text_en":"शाक्य (Shakya)"},{"id":"B","text":"लिच्छवि/वज्जि संघ (Lichchhavi/Vajji Sangha)","text_en":"लिच्छवि/वज्जि संघ (Lichchhavi/Vajji Sangha)"},{"id":"C","text":"मल्ल (Malla)","text_en":"मल्ल (Malla)"},{"id":"D","text":"कोलिय (Koliya)","text_en":"कोलिय (Koliya)"}]','1',replace('**✅ Correct Logic:** ''वज्जि संघ'' (8 कुलों का समूह) जिसमें ''लिच्छवि'' प्रमुख थे, दुनिया का प्राचीनतम और शक्तिशाली गणतंत्र माना जाता है। इसकी राजधानी वैशाली थी।\n\n**💡 Exam Fact:** कौटिल्य ने लिच्छवियों को ''राजशब्दोपजीवी'' (Title of Raja) संघ कहा है।\n\n**🧠 Memory Tip:** **L**ichchhavi = **L**argest Republic.\n\n**🚫 Scam Alert:** शाक्य (बुद्ध का कुल) छोटा था, वज्जि महाजनपद स्तर का विशाल संघ था।','\n',char(10)),2,0,1,NULL,'Which was the largest and most powerful ''Republic'' (Gantantra) in the world during the Buddha period?',replace('**✅ Correct Logic:** ''Vajji Sangha'' (Confederacy of 8 clans), led by ''Lichchhavis'', is considered the world''s oldest and powerful republic. Its capital was Vaishali.\n\n**💡 Exam Fact:** Kautilya called Lichchhavis ''Rajashabdopajivi'' (Living by the title of Raja).\n\n**🧠 Memory Tip:** **L**ichchhavi = **L**argest Republic.\n\n**🚫 Scam Alert:** Shakya (Buddha''s clan) was small; Vajji was a massive Mahajanapada level confederacy.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('7f6053cf-2ea4-4577-bb2f-9b0dcb4eb831','15a46e2a-ac67-4384-b7e1-864f61398a70','प्राचीन गणराज्यों में मतदान (Voting) के लिए किस शब्द का प्रयोग होता था?','[{"id":"A","text":"शलाका (Salaka)","text_en":"शलाका (Salaka)"},{"id":"B","text":"गुटिका (Gutika)","text_en":"गुटिका (Gutika)"},{"id":"C","text":"पत्रक (Patraka)","text_en":"पत्रक (Patraka)"},{"id":"D","text":"मुद्रा (Mudra)","text_en":"मुद्रा (Mudra)"}]','0',replace('**✅ Correct Logic:** गणराज्यों की संथागार (Assembly Hall) में निर्णय बहुमत से होते थे। रंगीन लकड़ी की छड़ियों का प्रयोग वोटिंग के लिए होता था, जिसे ''शलाका'' कहते थे।\n\n**💡 Exam Fact:** ''शलाका-ग्राहपक'' (Salaka-Grahapaka) वह अधिकारी था जो वोट एकत्र करता था (Election Commissioner)।\n\n**🧠 Memory Tip:** Salaka = Stick = Voting Stick.\n\n**🚫 Scam Alert:** गुटिका या मुद्रा बाद के शब्द हैं, बौद्ध ग्रंथों में ''शलाका'' शब्द है।','\n',char(10)),2,0,2,NULL,'Which term was used for ''Voting'' in ancient Republics?',replace('**✅ Correct Logic:** In the Santhagara (Assembly Hall), decisions were taken by majority. Colored wooden sticks were used for voting, called ''Salaka''.\n\n**💡 Exam Fact:** ''Salaka-Grahapaka'' was the officer who collected votes.\n\n**🧠 Memory Tip:** Salaka = Stick = Voting Stick.\n\n**🚫 Scam Alert:** Gutika/Mudra are later terms; Buddhist texts use ''Salaka''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('6a6ed58d-72ee-4bf3-b330-64f4df4a16fd','15a46e2a-ac67-4384-b7e1-864f61398a70','गणराज्यों की केंद्रीय विधानसभा या बैठक स्थल को क्या कहा जाता था?','[{"id":"A","text":"सभागार (Sabhagara)","text_en":"सभागार (Sabhagara)"},{"id":"B","text":"संथागार (Santhagara)","text_en":"संथागार (Santhagara)"},{"id":"C","text":"चैत्य (Chaitya)","text_en":"चैत्य (Chaitya)"},{"id":"D","text":"दुर्ग (Durga)","text_en":"दुर्ग (Durga)"}]','1',replace('**✅ Correct Logic:** गणराज्यों की बैठकों के लिए एक विशाल भवन होता था जिसे ''संथागार'' (Santhagara) कहते थे। यहीं पर राजा, उपराजा, सेनापति आदि मिलकर राज्य के निर्णय लेते थे।\n\n**💡 Exam Fact:** बुद्ध ने भी अपने संघ की कार्यप्रणाली गणराज्यों के ''संथागार'' की तर्ज पर बनाई थी।\n\n**🧠 Memory Tip:** Santha = Organization/Joint -> Santhagara.\n\n**🚫 Scam Alert:** ''सभागार'' आधुनिक शब्द है, तकनीकी ऐतिहासिक शब्द ''संथागार'' है।','\n',char(10)),2,0,3,NULL,'What was the Central Assembly or Meeting place of the Republics called?',replace('**✅ Correct Logic:** Republics had a large building for meetings called ''Santhagara''. Here Raja, Uparaja, Senapati etc. met to take state decisions.\n\n**💡 Exam Fact:** Buddha modeled the functioning of his Sangha on the ''Santhagara'' of republics.\n\n**🧠 Memory Tip:** Santha = Organization/Joint -> Santhagara.\n\n**🚫 Scam Alert:** ''Sabhagara'' is modern; the technical historical term is ''Santhagara''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('f5bb61e1-88cd-46ef-9efb-093e0d6e51f8','15a46e2a-ac67-4384-b7e1-864f61398a70','प्रमुख गणराज्य और उनकी राजधानियों को सुमेलित करें (Match the major Republics with their Capitals):','[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]','0',replace('**✅ Correct Logic:**\n* **शाक्य:** कपिलवस्तु (बुद्ध का घर)।\n* **मल्ल:** कुशीनारा (जहाँ बुद्ध का महापरिनिर्वाण हुआ)।\n* **विदेह:** मिथिला (जनक)।\n* **कोलिय:** रामग्राम (रोहिणी नदी विवाद शाक्यों के साथ)।\n\n**💡 Exam Fact:** मल्ल गणराज्य दो भागों में बंटा था - कुशीनारा और पावा।\n\n**🧠 Memory Tip:** **M**alla = **M**uscle/Wrestler = Strong capital (Kushinara).\n\n**🚫 Scam Alert:** विदेह पहले राजतंत्र था (जनक के समय), बाद में गणतंत्र (संघ) बना।','\n',char(10)),2,0,5,NULL,'Match the major Republics with their Capitals:',replace('**✅ Correct Logic:**\n* **Shakya:** Kapilavastu.\n* **Malla:** Kushinara (Buddha''s death).\n* **Videha:** Mithila.\n* **Koliya:** Ramagrama.\n\n**💡 Exam Fact:** Malla republic was divided into two parts - Kushinara and Pava.\n\n**🧠 Memory Tip:** **M**alla = **M**uscle/Wrestler = Strong capital (Kushinara).\n\n**🚫 Scam Alert:** Videha was Monarchy earlier (Janaka), later became Republic.','\n',char(10)),60,'matching','[{"id":"(1)","label":"शाक्य (Shakya)","match":"कपिलवस्तु (Kapilavastu)","matchId":"(c)"},{"id":"(2)","label":"मल्ल (Malla)","match":"कुशीनारा और पावा (Kushinara and Pava)","matchId":"(a)"},{"id":"(3)","label":"विदेह (Videha)","match":"मिथिला (Mithila)","matchId":"(d)"},{"id":"(4)","label":"कोलिय (Koliya)","match":"रामग्राम (Ramagrama)","matchId":"(b)"}]',NULL);
INSERT INTO questions VALUES('483b4e1a-d62c-4721-993c-1f57c387a2db','15a46e2a-ac67-4384-b7e1-864f61398a70',replace('कथन (A): प्राचीन गणराज्यों का पतन मगध साम्राज्य के उदय के साथ हुआ।\nकारण (R): गणराज्यों में एकता का अभाव था और निर्णय लेने में देरी होती थी।\nसही विकल्प चुनें:','\n',char(10)),'[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]','0',replace('**✅ Correct Logic:** अजातशत्रु (मगध) ने वज्जि संघ में फूट डलवाकर उसे नष्ट किया (मंत्री वस्सकार की मदद से)। गणराज्यों की कमजोरी उनकी आंतरिक कलह और गुप्त मंत्रणा का अभाव (Open Assembly) थी, जबकि राजतंत्र (मगध) में त्वरित निर्णय होते थे।\n\n**💡 Exam Fact:** अजातशत्रु ने ''रथमुसल'' और ''महाशिलाकंटक'' हथियारों का प्रयोग किया।\n\n**🧠 Memory Tip:** Democracy implies delay; Dictatorship (Monarchy) implies speed. Speed won.\n\n**🚫 Scam Alert:** दोनों सही हैं और कारण (कमजोरी) ही पतन (परिणाम) की व्याख्या है।','\n',char(10)),2,0,4,NULL,replace('Assertion (A): Ancient Republics declined with the rise of Magadha Empire.\nReason (R): Republics lacked unity and there was delay in decision making.\nSelect the correct option:','\n',char(10)),replace('**✅ Correct Logic:** Ajatashatru (Magadha) sowed discord in Vajji Sangha and destroyed it. Weakness of Republics was internal strife and lack of secrecy (Open Assembly), while Monarchy took quick decisions.\n\n**💡 Exam Fact:** Ajatashatru used ''Rathamusala'' and ''Mahashilakantaka'' weapons.\n\n**🧠 Memory Tip:** Democracy implies delay; Dictatorship (Monarchy) implies speed. Speed won.\n\n**🚫 Scam Alert:** Both are true and Reason explains the Decline.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('543c81b2-1053-4d6b-af49-d02bfc040a2d','15a46e2a-ac67-4384-b7e1-864f61398a70','पाणिनि ने ''अष्टाध्यायी'' में किन गणराज्यों को ''आयुधजीवी संघ'' (Ayudhajivi Sangha) कहा है?','[{"id":"A","text":"जो कृषि और व्यापार पर निर्भर थे (Dependent on Agriculture and Trade)","text_en":"जो कृषि और व्यापार पर निर्भर थे (Dependent on Agriculture and Trade)"},{"id":"B","text":"जो शस्त्रों/युद्ध के पेशे से जीते थे (Living by profession of Arms/War)","text_en":"जो शस्त्रों/युद्ध के पेशे से जीते थे (Living by profession of Arms/War)"},{"id":"C","text":"जो केवल ब्राह्मणों द्वारा शासित थे (Ruled only by Brahmins)","text_en":"जो केवल ब्राह्मणों द्वारा शासित थे (Ruled only by Brahmins)"},{"id":"D","text":"जो दास प्रथा पर आधारित थे (Based on Slavery)","text_en":"जो दास प्रथा पर आधारित थे (Based on Slavery)"}]','1',replace('**✅ Correct Logic:** ''आयुध'' का अर्थ है हथियार। ''आयुधजीवी'' वे गणराज्य थे (जैसे यौधेय, मालव) जिनके नागरिक शांतिकाल में किसान और युद्धकाल में सैनिक होते थे। ये अपनी वीरता के लिए प्रसिद्ध थे।\n\n**💡 Exam Fact:** सिकंदर को भारत में सबसे कड़ी टक्कर इन्हीं गणराज्यों (मालव/क्षुद्रक) ने दी थी।\n\n**🧠 Memory Tip:** Ayudh = Weapon. Jivi = Living. Living by Weapons.\n\n**🚫 Scam Alert:** ये केवल ''सैनिक'' नहीं थे, बल्कि पूरा समाज योद्धा प्रवृत्ति का था।','\n',char(10)),2,0,6,NULL,'Which Republics did Panini call ''Ayudhajivi Sangha'' in ''Ashtadhyayi''?',replace('**✅ Correct Logic:** ''Ayudha'' means Weapon. ''Ayudhajivi'' were republics (like Yaudheya, Malava) whose citizens were farmers in peace and soldiers in war. Famous for bravery.\n\n**💡 Exam Fact:** Alexander faced the toughest resistance from these republics (Malava/Kshudraka).\n\n**🧠 Memory Tip:** Ayudh = Weapon. Jivi = Living. Living by Weapons.\n\n**🚫 Scam Alert:** Not just ''soldiers'', but the whole society was martial.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('1e10c0c8-38ba-4d57-9cc4-228685acbf1f','15a46e2a-ac67-4384-b7e1-864f61398a70','वैशाली के लिच्छवि गणराज्य में न्याय व्यवस्था (Judicial System) कितने चरणों (Stages) में थी?','[{"id":"A","text":"3","text_en":"3"},{"id":"B","text":"5","text_en":"5"},{"id":"C","text":"7","text_en":"7"},{"id":"D","text":"8","text_en":"8"}]','3',replace('**✅ Correct Logic:** ''अट्ठकथा'' के अनुसार, वज्जि संघ में अपराधी को दंड देने से पहले 7 या 8 न्यायालयों (Stages) से गुजरना पड़ता था (विनिश्चय महामात्र -> व्यावहारिक -> सूत्रधार... -> राजा)। यदि कोई भी उसे निर्दोष पाता, तो वह मुक्त हो जाता।\n\n**💡 Exam Fact:** यह मानवाधिकारों की रक्षा का बेहतरीन उदाहरण था - "निर्दोष को सजा नहीं मिलनी चाहिए।"\n\n**🧠 Memory Tip:** Lichchhavi Liberty = 8 Layers of Justice.\n\n**🚫 Scam Alert:** यह बहुत विशिष्ट प्रश्न है। 8 चरण (Steps) थे, राजा अंतिम न्यायाधीश था।','\n',char(10)),2,0,7,NULL,'The Judicial System in the Lichchhavi Republic of Vaishali had how many Stages?',replace('**✅ Correct Logic:** According to ''Atthakatha'', a criminal had to pass through 7 or 8 courts (Stages) before punishment. If any court found him innocent, he was acquitted.\n\n**💡 Exam Fact:** Great example of Human Rights - "Innocent should not be punished."\n\n**🧠 Memory Tip:** Lichchhavi Liberty = 8 Layers of Justice.\n\n**🚫 Scam Alert:** Very specific question. There were 8 steps, King was final.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ac43854c-711a-4a37-a232-bbd400ff406c','15a46e2a-ac67-4384-b7e1-864f61398a70','गणराज्यों में कार्यपालिका शक्ति (Executive Power) किसके हाथों में होती थी?','[{"id":"A","text":"एकल राजा (Single King)","text_en":"एकल राजा (Single King)"},{"id":"B","text":"राजाओं का एक समूह (A group of Rajas/Chiefs)","text_en":"राजाओं का एक समूह (A group of Rajas/Chiefs)"},{"id":"C","text":"पुरोहित (Priest)","text_en":"पुरोहित (Priest)"},{"id":"D","text":"दास (Slaves)","text_en":"दास (Slaves)"}]','1',replace('**✅ Correct Logic:** गणराज्यों में ''राजा'' कोई एक व्यक्ति नहीं होता था, बल्कि कुलीन परिवारों के प्रमुख (Heads of Clans) सामूहिक रूप से शासन करते थे। लिच्छवि में 7707 राजा थे।\n\n**💡 Exam Fact:** इसे ''कुलीनतंत्र'' (Oligarchy) कहा जाता है।\n\n**🧠 Memory Tip:** Republic = Public (Group) Rule.\n\n**🚫 Scam Alert:** ''राजा'' शब्द का प्रयोग होता था, लेकिन उसका अर्थ ''Monarch'' नहीं, बल्कि ''Representative'' था।','\n',char(10)),2,0,8,NULL,'In whose hands was the Executive Power in the Republics?',replace('**✅ Correct Logic:** In Republics, ''Raja'' was not a single person, but Heads of Clans ruled collectively. Lichchhavis had 7707 Rajas.\n\n**💡 Exam Fact:** This is called ''Oligarchy''.\n\n**🧠 Memory Tip:** Republic = Public (Group) Rule.\n\n**🚫 Scam Alert:** The word ''Raja'' was used, but it meant ''Representative'', not ''Monarch''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('d2a03194-7ae7-4d5c-9172-9e42c2ce5f82','15a46e2a-ac67-4384-b7e1-864f61398a70','''अजातशत्रु और वज्जि संघ'' के बीच संघर्ष का वर्णन किस बौद्ध ग्रंथ में विस्तार से मिलता है?','[{"id":"A","text":"महापरिनिब्बान सुत्त (Mahaparinibbana Sutta)","text_en":"महापरिनिब्बान सुत्त (Mahaparinibbana Sutta)"},{"id":"B","text":"दीपवंश (Dipavamsa)","text_en":"दीपवंश (Dipavamsa)"},{"id":"C","text":"जातक कथाएं (Jataka Tales)","text_en":"जातक कथाएं (Jataka Tales)"},{"id":"D","text":"मिलिन्दपन्हो (Milindapanho)","text_en":"मिलिन्दपन्हो (Milindapanho)"}]','0',replace('**✅ Correct Logic:** ''दीघ निकाय'' के ''महापरिनिब्बान सुत्त'' में वर्णन है कि अजातशत्रु ने बुद्ध से पूछा कि वज्जि को कैसे हराया जाए। बुद्ध ने ''सप्त अपरिहाणिय धम्म'' (7 conditions of welfare) बताए थे।\n\n**💡 Exam Fact:** बुद्ध ने कहा था: "जब तक वज्जि एकजुट रहेंगे, उन्हें कोई नहीं हरा सकता।"\n\n**🧠 Memory Tip:** Big War described in Big Sutta (**Maha**parinibbana).\n\n**🚫 Scam Alert:** जातक कथाओं में कहानियाँ हैं, लेकिन राजनीतिक इतिहास ''सुत्त'' में है।','\n',char(10)),2,0,9,NULL,'In which Buddhist text is the conflict between ''Ajatashatru and Vajji Sangha'' described in detail?',replace('**✅ Correct Logic:** ''Mahaparinibbana Sutta'' of Digha Nikaya describes Ajatashatru asking Buddha how to defeat Vajji. Buddha gave ''7 conditions of welfare''.\n\n**💡 Exam Fact:** Buddha said: "As long as Vajjis remain united, no one can defeat them."\n\n**🧠 Memory Tip:** Big War described in Big Sutta (**Maha**parinibbana).\n\n**🚫 Scam Alert:** Jatakas have stories, but political history is in ''Sutta''.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('1231143b-f63a-4064-b118-3ef1dd01d454','15a46e2a-ac67-4384-b7e1-864f61398a70','किस प्राचीन भारतीय गणराज्य ने सिकंदर (Alexander) के आक्रमण के समय अपनी स्त्रियों को भी युद्ध में उतारा था?','[{"id":"A","text":"अश्वक/अस्साकेनोल (Ashvaka/Assakenoi)","text_en":"अश्वक/अस्साकेनोल (Ashvaka/Assakenoi)"},{"id":"B","text":"मालव (Malava)","text_en":"मालव (Malava)"},{"id":"C","text":"कठ (Katha)","text_en":"कठ (Katha)"},{"id":"D","text":"शिवि (Shivi)","text_en":"शिवि (Shivi)"}]','0',replace('**✅ Correct Logic:** ''अश्वक'' (Ashvaka) गणराज्य (स्वात घाटी) के पुरुषों के मारे जाने के बाद, उनकी रानियों और स्त्रियों ने शस्त्र उठा लिए थे और सिकंदर से लोहा लिया।\n\n**💡 Exam Fact:** ग्रीक लेखकों ने इसे ''Massaga'' का घेरा कहा है।\n\n**🧠 Memory Tip:** Ashvaka = **A**mazonian women (Warriors).\n\n**🚫 Scam Alert:** मालव ने भी युद्ध किया, लेकिन महिलाओं की भागीदारी के लिए ''अश्वक'' प्रसिद्ध है।','\n',char(10)),2,0,10,NULL,'Which ancient Indian Republic fielded even its women in war during Alexander''s invasion?',replace('**✅ Correct Logic:** After men of ''Ashvaka'' republic (Swat valley) were killed, their women took up arms and fought Alexander.\n\n**💡 Exam Fact:** Greek writers call this the siege of ''Massaga''.\n\n**🧠 Memory Tip:** Ashvaka = **A**mazonian women (Warriors).\n\n**🚫 Scam Alert:** Malavas also fought, but Ashvaka is famous for women''s participation.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('22925218-fdba-41e6-b949-37ccedc37003','98a7ad87-46ed-4f91-832b-c2038cdddbb0','प्राचीन काल के दौरान, राजा महिष्मत ने ''महिष्मती'' शहर की स्थापना की थी। वह किस वंश से संबंधित थे?','[{"id":"A","text":"पौख्वार वंश (Paokwar)","text_en":"पौख्वार वंश (Paokwar)"},{"id":"B","text":"हैहय वंश (Haihaya)","text_en":"हैहय वंश (Haihaya)"},{"id":"C","text":"कारुश वंश (Karusha)","text_en":"कारुश वंश (Karusha)"},{"id":"D","text":"चंद्र वंश (Chandravansh)","text_en":"चंद्र वंश (Chandravansh)"}]','1',replace('✅ **Correct Logic**: राजा महिष्मत हैहय वंश के यदुवंशी शासक थे। उन्होंने नर्मदा के तट पर महिष्मती (महेश्वर) की स्थापना की।\n💡 **Exam Fact**: यह महिष्मती साम्राज्य अवंती की दक्षिणी राजधानी थी।\n🧠 **Memory Tip**: ''H'' for Haihaya and ''H'' for Heswar (Maheshwar).\n🚫 **Scam Alert**: कारुश वंश बघेलखंड क्षेत्र से संबंधित था, न कि निमाड़/महेश्वर से।','\n',char(10)),2,0,1,NULL,'During ancient times, King Mahishmat founded the city of ''Mahishmati''. To which dynasty did he belong?',replace('✅ **Correct Logic**: King Mahishmat was a Yaduvanshi ruler of the Haihaya dynasty. He established Mahishmati (modern Maheshwar) on the banks of Narmada.\n💡 **Exam Fact**: Mahishmati served as the southern capital of the Avanti Mahajanapada.\n🧠 **Memory Tip**: ''H'' for Haihaya and ''H'' for Heswar (Maheshwar).\n🚫 **Scam Alert**: Karusha dynasty was related to the Baghelkhand region, not Nimar/Maheshwar.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('61a139a8-cb17-4be6-8992-69cc9870dbdc','98a7ad87-46ed-4f91-832b-c2038cdddbb0',replace('भोपाल रियासत के संबंध में निम्नलिखित कथनों पर विचार करें:\n1. इसकी स्थापना दोस्त मोहम्मद खान ने 1723-24 में की थी।\n2. इस्लाम नगर इसकी प्रारंभिक राजधानी थी।\n3. दोस्त मोहम्मद खान ने अंतिम हिंदू शासिका रानी कमलापति की सहायता की थी।\n\nसही कथन चुनें:','\n',char(10)),'[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"केवल 1 और 3","text_en":"केवल 1 और 3"},{"id":"D","text":"1, 2 और 3","text_en":"1, 2 और 3"}]','3',replace('✅ **Correct Logic**: तीनों कथन सही हैं। दोस्त मोहम्मद खान ने रानी कमलापति की मदद के बदले में भोपाल का एक हिस्सा प्राप्त किया था।\n💡 **Exam Fact**: इस्लाम नगर का पुराना नाम ''जगदीशपुर'' था जिसे दोस्त मोहम्मद खान ने बदला था।\n🧠 **Memory Tip**: DIC - Dost, Islamnagar, Capital.\n🚫 **Scam Alert**: भ्रमित न हों, भोपाल का विलय भारत संघ में 1 जून 1949 को हुआ था, स्थापना 1720 के दशक में हुई थी।','\n',char(10)),2,0,2,NULL,replace('Consider the following statements regarding Bhopal State:\n1. It was founded by Dost Mohammad Khan in 1723-24.\n2. Islam Nagar was its initial capital.\n3. Dost Mohammad Khan helped the last Hindu ruler Rani Kamlapati.\n\nChoose the correct statements:','\n',char(10)),replace('✅ **Correct Logic**: All statements are correct. Dost Mohammad Khan received a part of Bhopal in exchange for helping Rani Kamlapati.\n💡 **Exam Fact**: The old name of Islam Nagar was ''Jagdishpur'' before it was renamed by Dost Mohammad Khan.\n🧠 **Memory Tip**: DIC - Dost, Islamnagar, Capital.\n🚫 **Scam Alert**: Don''t confuse the founding date with the merger date (1st June 1949).','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('dca655a8-2c27-486b-84db-225d702b766c','98a7ad87-46ed-4f91-832b-c2038cdddbb0','कल्चुरी वंश की ''त्रिपुरी'' शाखा का वास्तविक संस्थापक किसे माना जाता है?','[{"id":"A","text":"कोक्कल I (Kokkala I)","text_en":"कोक्कल I (Kokkala I)"},{"id":"B","text":"गांगेय देव (Gangeya Deva)","text_en":"गांगेय देव (Gangeya Deva)"},{"id":"C","text":"लक्ष्मी कर्ण (Laxmi Karna)","text_en":"लक्ष्मी कर्ण (Laxmi Karna)"},{"id":"D","text":"युवराज देव (Yuvraj Deva)","text_en":"युवराज देव (Yuvraj Deva)"}]','0',replace('✅ **Correct Logic**: कोक्कल प्रथम (845-885 AD) त्रिपुरी के कल्चुरी वंश का वास्तविक संस्थापक था।\n💡 **Exam Fact**: गांगेय देव ने ''विक्रमादित्य'' की उपाधि धारण की थी और स्वर्ण सिक्के चलाए थे।\n🧠 **Memory Tip**: K-T (Kokkala-Tripuri).\n🚫 **Scam Alert**: लक्ष्मी कर्ण को ''हिंद का नेपोलियन'' कहा जाता है, लेकिन वह संस्थापक नहीं था।','\n',char(10)),2,0,3,NULL,'Who is considered the real founder of the ''Tripuri'' branch of the Kalachuri dynasty?',replace('✅ **Correct Logic**: Kokkala I (845-885 AD) was the real founder of the Kalachuri dynasty of Tripuri.\n💡 **Exam Fact**: Gangeya Deva assumed the title ''Vikramaditya'' and issued gold coins.\n🧠 **Memory Tip**: K-T (Kokkala-Tripuri).\n🚫 **Scam Alert**: Laxmi Karna is known as the ''Napoleon of Hind'', but he wasn''t the founder.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('925e7efc-d25d-4b2b-8b84-c524560b061f','98a7ad87-46ed-4f91-832b-c2038cdddbb0','भरहुत स्तूप (सतना) का निर्माण मौर्य काल में हुआ था, लेकिन इसकी वेष्टनी (Railing) का निर्माण किस वंश के दौरान कराया गया था?','[{"id":"A","text":"गुप्त वंश","text_en":"गुप्त वंश"},{"id":"B","text":"शुंग वंश","text_en":"शुंग वंश"},{"id":"C","text":"सातवाहन वंश","text_en":"सातवाहन वंश"},{"id":"D","text":"पाण्डु वंश","text_en":"पाण्डु वंश"}]','1',replace('✅ **Correct Logic**: पुष्यमित्र शुंग के शासनकाल के दौरान भरहुत स्तूप की लकड़ी की रेलिंग को पत्थर की रेलिंग (वेष्टनी) से बदला गया था।\n💡 **Exam Fact**: इसकी खोज 1873 में अलेक्जेंडर कनिंघम ने की थी।\n🧠 **Memory Tip**: BS (Bharhut-Shunga).\n🚫 **Scam Alert**: सांची के स्तूप के तोरण द्वार सातवाहनों ने बनवाए थे, भरहुत की रेलिंग शुंगों ने।','\n',char(10)),2,0,4,NULL,'The Bharhut Stupa (Satna) was built during the Maurya period, but during which dynasty was its railing (Vedika) constructed?',replace('✅ **Correct Logic**: During the reign of Pushyamitra Shunga, the wooden railing of Bharhut Stupa was replaced with stone railing.\n💡 **Exam Fact**: It was discovered by Alexander Cunningham in 1873.\n🧠 **Memory Tip**: BS (Bharhut-Shunga).\n🚫 **Scam Alert**: Gateways of Sanchi were built by Satvahanas, while Bharhut''s railing was by Shungas.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('9719d694-c7d9-46a5-ba3a-5d5286f2f04c','98a7ad87-46ed-4f91-832b-c2038cdddbb0','निम्नलिखित मध्यकालीन शासकों और उनके क्षेत्रों को सुमेलित करें:','[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]','0',replace('✅ **Correct Logic**: मानसिंह तोमर ग्वालियर के प्रसिद्ध शासक थे। बाजीराव प्रथम की समाधि रावेरखेड़ी (खरगोन) में है। सिद्दीकी हसन खान भोपाल रियासत से थे और राजा भोज की राजधानी धार थी।\n💡 **Exam Fact**: राजा मानसिंह तोमर ने ''मानकौतूहल'' संगीत ग्रंथ की रचना की थी।\n🧠 **Memory Tip**: Bhoj-Dhar, Man-Gwalior.\n🚫 **Scam Alert**: बाजीराव प्रथम पेशवा थे, उनका मुख्य कार्यक्षेत्र महाराष्ट्र था लेकिन मृत्यु MP में हुई।','\n',char(10)),2,0,5,NULL,'Match the following medieval rulers and their regions:',replace('✅ **Correct Logic**: Man Singh Tomar was the ruler of Gwalior. Bajirao I''s samadhi is in Raverkhedi. Siddiq Hasan Khan was from Bhopal, and Raja Bhoj''s capital was Dhar.\n💡 **Exam Fact**: Raja Man Singh Tomar composed the music treatise ''Mankautuhal''.\n🧠 **Memory Tip**: Bhoj-Dhar, Man-Gwalior.\n🚫 **Scam Alert**: Bajirao I was a Peshwa; though active in MP, his roots were from Maharashtra.','\n',char(10)),60,'matching','[{"id":"(1)","label":"राजा मानसिंह तोमर","match":"ग्वालियर","matchId":"(a)"},{"id":"(2)","label":"बाजीराव प्रथम","match":"मल्हारगढ़/रावेरखेड़ी","matchId":"(b)"},{"id":"(3)","label":"नवाब सिद्दीकी हसन खान","match":"भोपाल","matchId":"(c)"},{"id":"(4)","label":"राजा भोज","match":"धार","matchId":"(d)"}]',NULL);
INSERT INTO questions VALUES('66af0344-0bc8-4d32-b842-20ace62140d0','98a7ad87-46ed-4f91-832b-c2038cdddbb0','ओरछा के बुंदेला वंश के किस शासक ने जहांगीर के कहने पर अबुल फजल की हत्या की थी?','[{"id":"A","text":"मधुकर शाह","text_en":"मधुकर शाह"},{"id":"B","text":"वीर सिंह देव बुंदेला","text_en":"वीर सिंह देव बुंदेला"},{"id":"C","text":"जुझार सिंह","text_en":"जुझार सिंह"},{"id":"D","text":"राम शाह","text_en":"राम शाह"}]','1',replace('✅ **Correct Logic**: वीर सिंह देव बुंदेला ने 1602 में अंतरी (ग्वालियर के पास) में अबुल फजल की हत्या कर दी थी।\n💡 **Exam Fact**: जहांगीर ने प्रसन्न होकर वीर सिंह को ओरछा का शासक बना दिया था।\n🧠 **Memory Tip**: V-A (Veer murdered Abul).\n🚫 **Scam Alert**: मधुकर शाह अकबर के समकालीन थे लेकिन उन्होंने विद्रोह किया था, हत्या नहीं।','\n',char(10)),2,0,6,NULL,'Which ruler of the Bundela dynasty of Orchha murdered Abul Fazl at the behest of Jahangir?',replace('✅ **Correct Logic**: Veer Singh Dev Bundela murdered Abul Fazl in 1602 at Antari (near Gwalior).\n💡 **Exam Fact**: Pleased with this, Jahangir made Veer Singh the ruler of Orchha.\n🧠 **Memory Tip**: V-A (Veer murdered Abul).\n🚫 **Scam Alert**: Madhukar Shah was a contemporary of Akbar but led a rebellion, not the murder.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('8c975b98-d1dd-41aa-8d6e-9ee5d809e1a3','98a7ad87-46ed-4f91-832b-c2038cdddbb0','1857 के विद्रोह के दौरान ''गढ़ा मण्डला'' से विद्रोह का नेतृत्व किसने किया था?','[{"id":"A","text":"शंकर शाह और रघुनाथ शाह","text_en":"शंकर शाह और रघुनाथ शाह"},{"id":"B","text":"भीमा नायक","text_en":"भीमा नायक"},{"id":"C","text":"शहादत खान","text_en":"शहादत खान"},{"id":"D","text":"रानी अवंती बाई","text_en":"रानी अवंती बाई"}]','0',replace('✅ **Correct Logic**: गोंड राजा शंकर शाह और उनके पुत्र रघुनाथ शाह ने मण्डला/जबलपुर क्षेत्र से विद्रोह का नेतृत्व किया। उन्हें अंग्रेजों ने तोप से उड़ा दिया था।\n💡 **Exam Fact**: इनका बलिदान दिवस 18 सितंबर को मनाया जाता है।\n🧠 **Memory Tip**: MS (Mandla - Shankar).\n🚫 **Scam Alert**: शहादत खान ने महू (इंदौर) से विद्रोह का नेतृत्व किया था।','\n',char(10)),2,0,7,NULL,'Who led the revolt from ''Garha Mandla'' during the 1857 uprising?',replace('✅ **Correct Logic**: Gond King Shankar Shah and his son Raghunath Shah led the revolt from Mandla/Jabalpur region. They were executed by being blown from guns.\n💡 **Exam Fact**: Their martyrdom day is observed on 18th September.\n🧠 **Memory Tip**: MS (Mandla - Shankar).\n🚫 **Scam Alert**: Saadat Khan led the revolt from Mhow (Indore).','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('abe0f051-ebef-4658-9c06-8ea02eb188d7','98a7ad87-46ed-4f91-832b-c2038cdddbb0','परमार वंश के किस शासक ने धार में ''सरस्वती कंठाभरण'' नामक संस्कृत विद्यालय की स्थापना की थी?','[{"id":"A","text":"सीयक II","text_en":"सीयक II"},{"id":"B","text":"मुंज","text_en":"मुंज"},{"id":"C","text":"राजा भोज","text_en":"राजा भोज"},{"id":"D","text":"सिंधुराज","text_en":"सिंधुराज"}]','2',replace('✅ **Correct Logic**: राजा भोज एक महान विद्वान थे, उन्होंने धार में सरस्वती मंदिर और संस्कृत पाठशाला बनवाई थी।\n💡 **Exam Fact**: इसे वर्तमान में ''भोजशाला'' के नाम से जाना जाता है।\n🧠 **Memory Tip**: Bhoj = Book/Knowledge.\n🚫 **Scam Alert**: सीयक द्वितीय परमार वंश के वास्तविक संस्थापक थे, लेकिन सांस्कृतिक कार्य भोज ने किए।','\n',char(10)),2,0,8,NULL,'Which ruler of the Paramara dynasty established a Sanskrit school named ''Saraswati Kanthabharana'' in Dhar?',replace('✅ **Correct Logic**: Raja Bhoj was a great scholar; he built the Saraswati temple and Sanskrit school in Dhar.\n💡 **Exam Fact**: It is currently known as ''Bhojshala''.\n🧠 **Memory Tip**: Bhoj = Book/Knowledge.\n🚫 **Scam Alert**: Siyaka II was the real founder, but cultural achievements are synonymous with Bhoj.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('057faa1e-6b48-46e2-ad89-580aef93709d','98a7ad87-46ed-4f91-832b-c2038cdddbb0','चंदेल वंश के किस शासक ने महमूद गजनवी का सफलतापूर्वक प्रतिरोध किया था?','[{"id":"A","text":"यशोवर्मन","text_en":"यशोवर्मन"},{"id":"B","text":"धंग देव","text_en":"धंग देव"},{"id":"C","text":"विद्याधर","text_en":"विद्याधर"},{"id":"D","text":"परमर्दिदेव","text_en":"परमर्दिदेव"}]','2',replace('✅ **Correct Logic**: विद्याधर एकमात्र भारतीय शासक थे जिन्होंने महमूद गजनवी की अधीनता स्वीकार नहीं की और उसका कड़ा विरोध किया।\n💡 **Exam Fact**: विद्याधर ने ही कंदरिया महादेव मंदिर का निर्माण करवाया था।\n🧠 **Memory Tip**: Vidya (Knowledge) vs Ghaznavi.\n🚫 **Scam Alert**: धंग देव ने गजनवी के पिता सुबुक्तगीन के विरुद्ध संघ में भाग लिया था, लेकिन गजनवी से विद्याधर लड़ा।','\n',char(10)),2,0,9,NULL,'Which ruler of the Chandela dynasty successfully resisted Mahmud Ghaznavi?',replace('✅ **Correct Logic**: Vidyadhara was the only Indian ruler who did not submit to Mahmud Ghaznavi and offered stiff resistance.\n💡 **Exam Fact**: Vidyadhara also built the Kandariya Mahadev Temple.\n🧠 **Memory Tip**: Vidya (Knowledge) vs Ghaznavi.\n🚫 **Scam Alert**: Dhanga Deva participated in a confederacy against Subuktigin (Ghaznavi''s father).','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('09d0591a-9d09-45ee-9c08-d2c6a325798c','98a7ad87-46ed-4f91-832b-c2038cdddbb0','ग्वालियर के सिंधिया वंश के संस्थापक कौन थे?','[{"id":"A","text":"राणाजी सिंधिया","text_en":"राणाजी सिंधिया"},{"id":"B","text":"महादजी सिंधिया","text_en":"महादजी सिंधिया"},{"id":"C","text":"दौलतराव सिंधिया","text_en":"दौलतराव सिंधिया"},{"id":"D","text":"जीवाजीराव सिंधिया","text_en":"जीवाजीराव सिंधिया"}]','0',replace('✅ **Correct Logic**: राणोजी सिंधिया ने 1731 में सिंधिया वंश की स्थापना की थी। प्रारंभ में इनकी राजधानी उज्जैन थी।\n💡 **Exam Fact**: दौलतराव सिंधिया ने 1810 में राजधानी उज्जैन से ग्वालियर स्थानांतरित की थी।\n🧠 **Memory Tip**: R for Root/Ranoji.\n🚫 **Scam Alert**: महादजी सिंधिया सबसे शक्तिशाली शासक थे, लेकिन संस्थापक राणोजी थे।','\n',char(10)),2,0,10,NULL,'Who was the founder of the Scindia dynasty of Gwalior?',replace('✅ **Correct Logic**: Ranoji Scindia founded the Scindia dynasty in 1731. Initially, the capital was Ujjain.\n💡 **Exam Fact**: Daulat Rao Scindia shifted the capital from Ujjain to Gwalior in 1810.\n🧠 **Memory Tip**: R for Root/Ranoji.\n🚫 **Scam Alert**: Mahadji Scindia was the most powerful ruler, but Ranoji was the founder.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('6fcc23ee-9673-4257-9f74-c8d682ede480','ff20f456-3f09-4b99-948a-c8130f9616cf','प्राचीन जनपद ''वत्स'' की राजधानी क्या थी और इसका विस्तार वर्तमान मध्यप्रदेश के किस क्षेत्र में था?','[{"id":"A","text":"कौशाम्बी; ग्वालियर क्षेत्र","text_en":"कौशाम्बी; ग्वालियर क्षेत्र"},{"id":"B","text":"शुक्तिमती; बुंदेलखंड क्षेत्र","text_en":"शुक्तिमती; बुंदेलखंड क्षेत्र"},{"id":"C","text":"माहिष्मती; निमाड़ क्षेत्र","text_en":"माहिष्मती; निमाड़ क्षेत्र"},{"id":"D","text":"विदिसा; मालवा क्षेत्र","text_en":"विदिसा; मालवा क्षेत्र"}]','0',replace('✅ **Correct Logic**: प्राचीन 16 महाजनपदों में से ''वत्स'' की राजधानी कौशाम्बी थी और इसका कुछ विस्तार वर्तमान ग्वालियर क्षेत्र में भी था।\n💡 **Exam Fact**: चेदि महाजनपद की राजधानी शुक्तिमती थी जो बुंदेलखंड में स्थित थी।\n🧠 **Memory Tip**: V-K (Vatsa-Kaushambi).\n🚫 **Scam Alert**: भ्रमित न हों, ग्वालियर ''वत्स'' का हिस्सा था, जबकि ''अवंती'' के अंतर्गत उज्जैन और महिष्मती आते थे।','\n',char(10)),2,0,1,NULL,'What was the capital of the ancient Janapada ''Vatsa'' and in which region of present-day MP was it extended?',replace('✅ **Correct Logic**: Among the 16 Mahajanapadas, the capital of ''Vatsa'' was Kaushambi, and its influence extended to the modern-day Gwalior region.\n💡 **Exam Fact**: Chedi Mahajanapada''s capital was Shuktimati, located in Bundelkhand.\n🧠 **Memory Tip**: V-K (Vatsa-Kaushambi).\n🚫 **Scam Alert**: Don''t be confused; Gwalior was part of Vatsa, whereas Ujjain and Mahishmati were under Avanti.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('65cb6b13-67c7-4ad6-86ef-a84f93de9d41','ff20f456-3f09-4b99-948a-c8130f9616cf','राजा भोज के शासनकाल के दौरान परमारों की राजधानी ''धार'' स्थानांतरित होने से पहले क्या थी?','[{"id":"A","text":"विदिसा (Vidisha)","text_en":"विदिसा (Vidisha)"},{"id":"B","text":"उज्जैन (Ujjain)","text_en":"उज्जैन (Ujjain)"},{"id":"C","text":"ओंकारेश्वर (Omkareshwar)","text_en":"ओंकारेश्वर (Omkareshwar)"},{"id":"D","text":"मांडू (Mandu)","text_en":"मांडू (Mandu)"}]','1',replace('✅ **Correct Logic**: परमार वंश की प्रारंभिक राजधानी उज्जैन थी। राजा भोज ने इसे बाद में धार स्थानांतरित किया था।\n💡 **Exam Fact**: राजा भोज ने धार में एक विशाल संस्कृत पाठशाला ''भोजशाला'' बनवाई थी।\n🧠 **Memory Tip**: P-U-D (Paramara - Ujjain to Dhar).\n🚫 **Scam Alert**: मांडू को ''शादियाबाद'' कहा जाता था और यह परमारों के बाद सुल्तानों का केंद्र बना।','\n',char(10)),2,0,2,NULL,'What was the capital of the Paramaras before it was shifted to ''Dhar'' during Raja Bhoj''s reign?',replace('✅ **Correct Logic**: The early capital of the Paramara dynasty was Ujjain. Raja Bhoj later shifted it to Dhar.\n💡 **Exam Fact**: Raja Bhoj built a massive Sanskrit school called ''Bhojshala'' in Dhar.\n🧠 **Memory Tip**: P-U-D (Paramara - Ujjain to Dhar).\n🚫 **Scam Alert**: Mandu was called ''Shadiyabad'' and became a major center for Sultans after the Paramaras.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('3485796c-4c56-4c43-942b-0ae399529c2d','ff20f456-3f09-4b99-948a-c8130f9616cf',replace('निम्नलिखित कथनों पर विचार करें:\n1. ओलिवर वंश की राजधानी ''दशपुर'' (मंदसौर) थी।\n2. राजा यशोधर्मन इस वंश के सबसे प्रतापी शासक थे।\n3. उन्होंने हूण शासक मिहिरकुल को पराजित किया था।\n\nसही कथन चुनें:','\n',char(10)),'[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 3","text_en":"केवल 3"}]','2',replace('✅ **Correct Logic**: तीनों कथन सत्य हैं। ओलिवर (औलिकर) वंश ने मालवा में शासन किया और यशोधर्मन ने हूणों को खदेड़ा था।\n💡 **Exam Fact**: मंदसौर प्रशस्ति (Mandsaur Inscription) में यशोधर्मन की विजयों का वर्णन है।\n🧠 **Memory Tip**: AD-MY (Aulikara Dashpur - Mihirakula Yashodharman).\n🚫 **Scam Alert**: हूण शासक तोरमाण था, लेकिन यशोधर्मन ने उसके पुत्र मिहिरकुल को हराया था।','\n',char(10)),2,0,3,NULL,replace('Consider the following statements:\n1. The capital of the Aulikara dynasty was ''Dashpur'' (Mandsaur).\n2. King Yashodharman was the most illustrious ruler of this dynasty.\n3. He defeated the Huna ruler Mihirakula.\n\nChoose the correct statement:','\n',char(10)),replace('✅ **Correct Logic**: All three statements are true. The Aulikara dynasty ruled in Malwa, and Yashodharman drove out the Hunas.\n💡 **Exam Fact**: The Mandsaur Inscription describes the victories of Yashodharman.\n🧠 **Memory Tip**: AD-MY (Aulikara Dashpur - Mihirakula Yashodharman).\n🚫 **Scam Alert**: Toramana was the initial Huna ruler, but Yashodharman specifically defeated his son Mihirakula.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('5e1d6e55-9537-4a06-8608-848b9d8c84fa','ff20f456-3f09-4b99-948a-c8130f9616cf','बुंदेला राजाओं ने अपनी राजधानी ओरछा की स्थापना किस वर्ष की थी?','[{"id":"A","text":"1501 AD","text_en":"1501 AD"},{"id":"B","text":"1531 AD","text_en":"1531 AD"},{"id":"C","text":"1526 AD","text_en":"1526 AD"},{"id":"D","text":"1545 AD","text_en":"1545 AD"}]','1',replace('✅ **Correct Logic**: रुद्र प्रताप सिंह बुंदेला ने 1531 ई. में ओरछा शहर की स्थापना की और इसे अपनी राजधानी बनाया।\n💡 **Exam Fact**: ओरछा बेतवा नदी के तट पर स्थित है।\n🧠 **Memory Tip**: 15-31 (Bundela is ''One'' with ''5'' fingers and ''31'' soldiers).\n🚫 **Scam Alert**: 1501 गलत है; 1526 में पानीपत का युद्ध हुआ था, बुंदेला रियासत का उत्कर्ष उसके थोड़ा बाद हुआ।','\n',char(10)),2,0,4,NULL,'In which year did the Bundela kings establish their capital, Orchha?',replace('✅ **Correct Logic**: Rudra Pratap Singh Bundela founded the city of Orchha in 1531 AD and made it his capital.\n💡 **Exam Fact**: Orchha is situated on the banks of the Betwa river.\n🧠 **Memory Tip**: 15-31 (Bundela is ''One'' with ''5'' fingers and ''31'' soldiers).\n🚫 **Scam Alert**: 1501 is incorrect; 1526 was the Battle of Panipat, the rise of Orchha happened shortly after.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('a8fc98a4-4777-48cf-afc1-8650230af436','ff20f456-3f09-4b99-948a-c8130f9616cf','राजवंश और उनकी राजधानियों को सुमेलित करें:','[{"id":"A","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]','0',replace('✅ **Correct Logic**: पाण्डु वंश मैकल (अमरकंटक) में था। परिव्राजक वंश की राजधानी खोह थी और उच्चकल्प की राजधानी नागौद के पास उच्चकल्प थी। मघ वंश बघेलखंड (बांधवगढ़) में था।\n💡 **Exam Fact**: परिव्राजक शासक हस्तिन का ''खोह ताम्रपत्र'' प्रसिद्ध है।\n🧠 **Memory Tip**: Magh-Bandhavgarh (M-B).\n🚫 **Scam Alert**: परिव्राजक और उच्चकल्प दोनों समकालीन थे, उनकी राजधानियाँ पास-पास (सतना क्षेत्र) थीं।','\n',char(10)),2,0,5,NULL,'Match the dynasties and their capitals:',replace('✅ **Correct Logic**: Pandu dynasty was in Maikal (Amarkantak). Parivrajaka capital was Khoh, and Uchchhakalpa was near Nagod. Magha dynasty ruled in Baghelkhand (Bandhavgarh).\n💡 **Exam Fact**: The ''Khoh Copper Plate'' of Parivrajaka ruler Hastin is famous.\n🧠 **Memory Tip**: Magh-Bandhavgarh (M-B).\n🚫 **Scam Alert**: Parivrajaka and Uchchhakalpa were contemporaries; their capitals were close to each other in the Satna region.','\n',char(10)),60,'matching','[{"id":"(1)","label":"पाण्डु वंश","match":"अमरकंटक/मैकल","matchId":"(a)"},{"id":"(2)","label":"परिव्राजक वंश","match":"उच्चकल्प (नागौद)","matchId":"(b)"},{"id":"(3)","label":"उच्चकल्प वंश","match":"खोह","matchId":"(c)"},{"id":"(4)","label":"मघ वंश","match":"बांधवगढ़","matchId":"(d)"}]',NULL);
INSERT INTO questions VALUES('8a50e721-8904-41c3-bc63-2ad30cd81459','ff20f456-3f09-4b99-948a-c8130f9616cf','गोंडवाना साम्राज्य के किस शासक ने अपनी राजधानी ''सिंगौरगढ़'' से ''चौरागढ़'' स्थानांतरित की थी?','[{"id":"A","text":"संग्राम शाह","text_en":"संग्राम शाह"},{"id":"B","text":"दलपत शाह","text_en":"दलपत शाह"},{"id":"C","text":"रानी दुर्गावती","text_en":"रानी दुर्गावती"},{"id":"D","text":"चंद्र शाह","text_en":"चंद्र शाह"}]','0',replace('✅ **Correct Logic**: संग्राम शाह ने सुरक्षा की दृष्टि से अपनी राजधानी सिंगौरगढ़ (दमोह) से चौरागढ़ (नरसिंहपुर) स्थानांतरित की थी।\n💡 **Exam Fact**: संग्राम शाह को ''बावन गढ़ों'' का विजेता कहा जाता है।\n🧠 **Memory Tip**: Sangram (War) needs a Fort (Chauragarh).\n🚫 **Scam Alert**: दलपत शाह रानी दुर्गावती के पति थे, लेकिन राजधानी का प्रमुख विस्तार संग्राम शाह ने किया था।','\n',char(10)),2,0,6,NULL,'Which ruler of the Gondwana kingdom shifted the capital from ''Singaurgarh'' to ''Chauragarh''?',replace('✅ **Correct Logic**: Sangram Shah shifted the capital from Singaurgarh (Damoh) to Chauragarh (Narsinghpur) for better security.\n💡 **Exam Fact**: Sangram Shah is known as the conqueror of ''52 Garhs''.\n🧠 **Memory Tip**: Sangram (War) needs a Fort (Chauragarh).\n🚫 **Scam Alert**: Dalpat Shah was the husband of Rani Durgavati, but the major capital expansion was done by Sangram Shah.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('932a3d07-2679-4594-b33e-61efbd983d82','ff20f456-3f09-4b99-948a-c8130f9616cf','मालवा के खिलजी सुल्तान महमूद खिलजी ने ''मांडू'' का नाम बदलकर क्या रखा था?','[{"id":"A","text":"इस्लामपुर","text_en":"इस्लामपुर"},{"id":"B","text":"शादियाबाद","text_en":"शादियाबाद"},{"id":"C","text":"महमूदाबाद","text_en":"महमूदाबाद"},{"id":"D","text":"धार","text_en":"धार"}]','1',replace('✅ **Correct Logic**: मांडू को ''शादियाबाद'' (City of Joy) के नाम से जाना जाता था।\n💡 **Exam Fact**: होशंग शाह ने मांडू को अपनी राजधानी बनाया था।\n🧠 **Memory Tip**: Mandu-Shadi (Joy).\n🚫 **Scam Alert**: महमूदाबाद गुजरात के सुल्तानों से संबंधित है, मांडू से नहीं।','\n',char(10)),2,0,7,NULL,'What did the Khilji Sultan of Malwa, Mahmud Khilji, rename ''Mandu''?',replace('✅ **Correct Logic**: Mandu was renamed ''Shadiyabad'' (City of Joy).\n💡 **Exam Fact**: Hoshang Shah was the one who initially made Mandu his capital.\n🧠 **Memory Tip**: Mandu-Shadi (Joy).\n🚫 **Scam Alert**: Mahmudabad is related to the Sultans of Gujarat, not Mandu.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('c7411939-9369-491f-9f19-e7915be57ee0','ff20f456-3f09-4b99-948a-c8130f9616cf','अहिल्याबाई होलकर ने होलकर वंश की राजधानी इंदौर से कहाँ स्थानांतरित की थी?','[{"id":"A","text":"उज्जैन","text_en":"उज्जैन"},{"id":"B","text":"खरगोन","text_en":"खरगोन"},{"id":"C","text":"महेश्वर","text_en":"महेश्वर"},{"id":"D","text":"बड़वानी","text_en":"बड़वानी"}]','2',replace('✅ **Correct Logic**: 1767 में देवी अहिल्याबाई होलकर ने नर्मदा के तट पर स्थित ''महेश्वर'' को अपनी राजधानी बनाया।\n💡 **Exam Fact**: उन्होंने महेश्वर में रेशमी साड़ियों (Maheshwari Sarees) के उद्योग को बढ़ावा दिया।\n🧠 **Memory Tip**: Ahilya - Narmada - Maheshwar.\n🚫 **Scam Alert**: उज्जैन सिंधियाओं की प्रारंभिक राजधानी थी, होलकरों की नहीं।','\n',char(10)),2,0,8,NULL,'Where did Ahilyabai Holkar shift the capital of the Holkar dynasty from Indore?',replace('✅ **Correct Logic**: In 1767, Devi Ahilyabai Holkar made ''Maheshwar'', situated on the Narmada, her capital.\n💡 **Exam Fact**: She promoted the silk saree industry (Maheshwari Sarees) in Maheshwar.\n🧠 **Memory Tip**: Ahilya - Narmada - Maheshwar.\n🚫 **Scam Alert**: Ujjain was the early capital of Scindias, not Holkars.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('bf7d4fe7-59f8-4446-98d5-6b9fcc2d9493','ff20f456-3f09-4b99-948a-c8130f9616cf','जीवाजीराव सिंधिया के समय ग्वालियर रियासत की ''ग्रीष्मकालीन राजधानी'' क्या थी?','[{"id":"A","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"B","text":"शिवपुरी","text_en":"शिवपुरी"},{"id":"C","text":"उज्जैन","text_en":"उज्जैन"},{"id":"D","text":"दतिया","text_en":"दतिया"}]','1',replace('✅ **Correct Logic**: सिंधिया शासक गर्मियों के दौरान शिवपुरी को अपनी राजधानी के रूप में उपयोग करते थे।\n💡 **Exam Fact**: शिवपुरी में माधव नेशनल पार्क और सिंधिया छतरियाँ स्थित हैं।\n🧠 **Memory Tip**: Shivpuri is cool (Summer retreat).\n🚫 **Scam Alert**: ग्वालियर मुख्य राजधानी थी, लेकिन गर्मियों में प्रशासन शिवपुरी चला जाता था।','\n',char(10)),2,0,9,NULL,'What was the ''Summer Capital'' of the Gwalior State during the time of Jiwajirao Scindia?',replace('✅ **Correct Logic**: The Scindia rulers used Shivpuri as their summer capital.\n💡 **Exam Fact**: Shivpuri houses the Madhav National Park and the Scindia Chhatris (cenotaphs).\n🧠 **Memory Tip**: Shivpuri is cool (Summer retreat).\n🚫 **Scam Alert**: Gwalior was the primary capital, but the administration moved to Shivpuri during summers.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('4b257df7-20d9-4399-ad82-411aca714c63','ff20f456-3f09-4b99-948a-c8130f9616cf','मध्य भारत (1948-1956) की राजधानी के संबंध में कौन सा कथन गलत है?','[{"id":"A","text":"ग्वालियर 6.5 महीने के लिए राजधानी थी।","text_en":"ग्वालियर 6.5 महीने के लिए राजधानी थी।"},{"id":"B","text":"इंदौर 5.5 महीने के लिए राजधानी थी।","text_en":"इंदौर 5.5 महीने के लिए राजधानी थी।"},{"id":"C","text":"नागपुर इसकी एकमात्र राजधानी थी।","text_en":"नागपुर इसकी एकमात्र राजधानी थी।"},{"id":"D","text":"यह दो राजधानियों वाला राज्य था।","text_en":"यह दो राजधानियों वाला राज्य था।"}]','2',replace('✅ **Correct Logic**: मध्य भारत की दो राजधानियाँ थीं (ग्वालियर और इंदौर)। नागपुर ''CP & Berar'' की राजधानी थी।\n💡 **Exam Fact**: मध्य भारत के पहले मुख्यमंत्री लीलाधर जोशी थे।\n🧠 **Memory Tip**: MB = GI (Madhya Bharat = Gwalior + Indore).\n🚫 **Scam Alert**: अक्सर छात्र नागपुर और ग्वालियर में भ्रमित हो जाते हैं; नागपुर Part-A राज्य की राजधानी थी।','\n',char(10)),2,0,10,NULL,'Which statement is incorrect regarding the capital of Madhya Bharat (1948-1956)?',replace('✅ **Correct Logic**: Madhya Bharat had two capitals (Gwalior and Indore). Nagpur was the capital of ''CP & Berar''.\n💡 **Exam Fact**: The first CM of Madhya Bharat was Liladhar Joshi.\n🧠 **Memory Tip**: MB = GI (Madhya Bharat = Gwalior + Indore).\n🚫 **Scam Alert**: Students often confuse Nagpur with Gwalior; Nagpur was the capital of Part-A state.','\n',char(10)),60,'standard',NULL,NULL);
INSERT INTO questions VALUES('AwclEcpImXMV-dnggur4e','3bIu3iTfpozIvU5_YWpTk','पारस्परिक कौशल (Interpersonal Skills) में ''सहानुभूति'' (Empathy) का क्या अर्थ है?','"[\"दूसरे के लिए बुरा महसूस करना / Feeling bad for others\",\"दूसरे के नजरिए से चीजों को देखना / Seeing things from another''s perspective\",\"दूसरे की समस्या को नजरअंदाज करना / Ignoring another''s problem\",\"दूसरे की आलोचना करना / Criticizing others\"]"','1.0','सहानुभूति का अर्थ है खुद को दूसरे की जगह रखकर उसकी भावनाओं को समझना।',2,0,1,'Communication','What is the meaning of ''Empathy'' in Interpersonal Skills?','Empathy is the ability to understand and share the feelings of another.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('QtWjhYElb2hmWaFVQPVGG','3bIu3iTfpozIvU5_YWpTk','संचार अवरोधों (Barriers) को उनके प्रकार से सुमेलित करें:','"[\"(1)-(c), (2)-(b), (3)-(a), (4)-(d)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(b), (2)-(a), (3)-(d), (4)-(c)\",\"(1)-(d), (2)-(c), (3)-(b), (4)-(a)\"]"','0.0','Language is Semantic; Distrust is Psychological; Hearing loss is Physiological; Status is Organizational.',2,0,2,'Communication','Match Communication Barriers with their types:','Language is Semantic; Distrust is Psychological; Hearing loss is Physiological; Status is Organizational.',60,'matching','[{"id":"(1)","label":"Language barrier","match":"Physiological","matchId":"(a)"},{"id":"(2)","label":"Distrust of source","match":"Psychological","matchId":"(b)"},{"id":"(3)","label":"Hearing impairment","match":"Semantic","matchId":"(c)"},{"id":"(4)","label":"Hierarchy/Status","match":"Organizational","matchId":"(d)"}]',NULL);
INSERT INTO questions VALUES('v5x6kyUnLZP-3T9Bi335P','3bIu3iTfpozIvU5_YWpTk','संचार में ''फिल्टरिंग'' (Filtering) का क्या तात्पर्य है?','"[\"संदेश को पूरी तरह से रोकना / Blocking the message completely\",\"प्रेषक द्वारा जानकारी को हेरफेर करना ताकि वह अनुकूल लगे / Manipulating information by sender to seem favorable\",\"शोर को हटाना / Removing noise\",\"डिकोडिंग प्रक्रिया / Decoding process\"]"','1.0','फिल्टरिंग तब होती है जब प्रेषक जानबूझकर जानकारी को छिपाता या बदलता है ताकि रिसीवर खुश हो।',2,0,3,'Communication','What does ''Filtering'' imply in communication?','Filtering is deliberate manipulation of info to make it appear more favorable to the receiver.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('Vv2M8l_1OgaaA8dxnGO3V','3bIu3iTfpozIvU5_YWpTk','यदि ''ZEBRA'' को ''2652181'' लिखा जाता है, तो ''COBRA'' को कैसे लिखा जाएगा?','"[\"3152181\",\"302181\",\"3182215\",\"3152118\"]"','0.0','प्रत्यक्ष संख्या कोडिंग: Z=26, E=5, B=2, R=18, A=1. COBRA: C=3, O=15, B=2, R=18, A=1 -> 3152181.',2,0,4,'Reasoning','If ''ZEBRA'' is written as ''2652181'', how will ''COBRA'' be written?','Direct letter position coding.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('84OthqeDhAn11GVxPzqHD','3bIu3iTfpozIvU5_YWpTk','सुबह सूर्योदय के बाद, राम एक पोल की ओर मुंह करके खड़ा था। पोल की छाया उसके ठीक दाईं ओर गिर रही थी। राम किस दिशा की ओर मुंह करके खड़ा था?','"[\"North\",\"South\",\"East\",\"West\"]"','1.0','सुबह सूर्य पूर्व में होता है, छाया पश्चिम में पड़ती है। यदि पश्चिम (छाया) राम के दाईं ओर है, तो वह दक्षिण की ओर देख रहा है।',2,0,5,'Reasoning','One morning after sunrise, Ram was facing a pole. The shadow of the pole fell exactly to his right. Which direction was Ram facing?','Sun in East, Shadow in West. If West is Right, Face is South.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('zQkJKA6nnNZWJQWph_qQy','3bIu3iTfpozIvU5_YWpTk','श्रृंखला पूरी करें: 4, 9, 25, 49, 121, ?','"[\"144\",\"169\",\"196\",\"225\"]"','1.0','अभाज्य संख्याओं के वर्ग: 2², 3², 5², 7², 11²। अगला अभाज्य 13 है, 13² = 169।',2,0,6,'Reasoning','Complete the series: 4, 9, 25, 49, 121, ?','Squares of Prime Numbers: 2, 3, 5, 7, 11, next is 13.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('dX0_heGeaT7EAWaifvxIe','3bIu3iTfpozIvU5_YWpTk','कथन: कुछ फल आम हैं। कुछ आम लाल हैं। निष्कर्ष: (I) सभी फल लाल हैं। (II) कुछ लाल फल हैं।','"[\"केवल I अनुसरण करता है\",\"केवल II अनुसरण करता है\",\"दोनों अनुसरण करते हैं\",\"कोई अनुसरण नहीं करता\"]"','3.0','फल और लाल के बीच कोई सीधा संबंध नहीं दिया गया है। ''कुछ'' के मामले में अनिश्चितता होती है।',2,0,7,'Reasoning','Statements: Some fruits are mangoes. Some mangoes are red. Conclusions: (I) All fruits are red. (II) Some red are fruits.','No direct link between Fruits and Red. Neither follows definitely.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('gVeOi02e0-zMA1qDPJZ76','3bIu3iTfpozIvU5_YWpTk','एक क्रिकेट मैच में पहले 10 ओवर में रन रेट 3.2 था। शेष 40 ओवरों में 282 रन के लक्ष्य तक पहुंचने के लिए रन रेट क्या होना चाहिए?','"[\"6.25\",\"6.5\",\"6.75\",\"7.0\"]"','0.0','पहले 10 ओवर में रन = 10 * 3.2 = 32. शेष रन = 282 - 32 = 250. आवश्यक रन रेट = 250 / 40 = 6.25.',2,0,8,'Quantitative Aptitude','In the first 10 overs of a cricket game, the run rate was 3.2. What should be the run rate in the remaining 40 overs to reach the target of 282 runs?','Runs needed = 250. Overs = 40. Rate = 250/40 = 6.25.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('TLKGvyaKAu4qAsALB9UCz','3bIu3iTfpozIvU5_YWpTk','दो संख्याओं का म.स. (HCF) 16 है और उनका गुणनफल 6400 है। उनका ल.स. (LCM) क्या है?','"[\"400\",\"64\",\"40\",\"1600\"]"','0.0','HCF * LCM = Product. 16 * LCM = 6400. LCM = 400.',2,0,9,'Quantitative Aptitude','HCF of two numbers is 16 and their product is 6400. What is their LCM?','Product of numbers = HCF * LCM.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('1Ftz0n2imPURQ1PYDTWG0','3bIu3iTfpozIvU5_YWpTk','असंगत ज्ञात करें: 125, 64, 216, 100','"[\"125\",\"64\",\"216\",\"100\"]"','3.0','100 एक वर्ग (10²) है, बाकी सभी घन हैं (5³, 4³, 6³)।',2,0,10,'Reasoning','Find the odd one: 125, 64, 216, 100','100 is a square, others are perfect cubes.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('a7SYxw5quRbU9FzeN1-Pr','3bIu3iTfpozIvU5_YWpTk','एक तस्वीर की ओर इशारा करते हुए, एक आदमी ने कहा, ''मेरा कोई भाई या बहन नहीं है, लेकिन उस आदमी का पिता मेरे पिता का बेटा है।'' तस्वीर किसकी है?','"[\"उसका बेटा / His son\",\"उसका पिता / His father\",\"वह स्वयं / Himself\",\"उसका भतीजा / His nephew\"]"','0.0','''मेरे पिता का बेटा'' (चूंकि उसका कोई भाई-बहन नहीं है) = वह स्वयं। कथन: ''उस आदमी का पिता मैं स्वयं हूँ।'' अत: तस्वीर उसके बेटे की है।',2,0,11,'Reasoning','Pointing to a photograph, a man said, ''I have no brother or sister, but that man''s father is my father''s son.'' Whose photograph is it?','''My father''s son'' is the speaker himself. So, ''That man''s father is ME''. Photo is of his son.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('fLWj9K-AQ3u8ZdBM2BxxP','3bIu3iTfpozIvU5_YWpTk','यदि 5 जनवरी 2011 को गुरुवार था, तो 15 अगस्त 2011 को कौन सा दिन था?','"[\"Monday\",\"Tuesday\",\"Wednesday\",\"Sunday\"]"','0.0','दिन शेष: Jan(26)+Feb(28)+Mar(31)+Apr(30)+May(31)+Jun(30)+Jul(31)+Aug(15) = 222 दिन। 222/7 = 5 शेष। गुरुवार + 5 = मंगलवार। (Correction: 222/7 -> 31 weeks, 5 rem. Thursday+5 = Tuesday).',2,0,12,'Reasoning','If 5th Jan 2011 was Thursday, what day was 15th Aug 2011?','Remaining days sum calculation. (Correction needed in mental math if any. Let''s recheck: Jan 26, Feb 28, Mar 31, Apr 30, May 31, Jun 30, Jul 31, Aug 15. Total = 222. 222%7 = 5. Thu + 5 = Tue). Answer is Tuesday.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('CbRnOWqnGsAjXINeDQfOp','3bIu3iTfpozIvU5_YWpTk','यदि ''×'' का अर्थ ''-'', ''+'' का अर्थ ''÷'', ''-'' का अर्थ ''×'', और ''÷'' का अर्थ ''+'' है, तो: 15 - 2 ÷ 900 + 90 × 100 = ?','"[\"60\",\"-60\",\"0\",\"10\"]"','1.0','परिवर्तन: 15 × 2 + 900 ÷ 90 - 100. BODMAS: 30 + 10 - 100 = 40 - 100 = -60.',2,0,13,'Reasoning','If ''×'' means ''-'', ''+'' means ''÷'', ''-'' means ''×'', and ''÷'' means ''+'', then: 15 - 2 ÷ 900 + 90 × 100 = ?','Apply BODMAS after sign change: 15*2 + 10 - 100 = -60.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('hdziKazqkh8x3VfkEwTvO','3bIu3iTfpozIvU5_YWpTk','पासे की तीन स्थितियां दी गई हैं। ''1'' के विपरीत फलक पर कौन सी संख्या है? (I: 1,2,3; II: 1,3,5; III: 4,5,6)','"[\"4\",\"6\",\"5\",\"4 or 6\"]"','0.0','1 के साथ 2, 3, 5 जुड़े हैं। तो विपरीत 4 या 6 हो सकता है। चित्र III में 4, 5, 6 हैं। 5 दोनों (II और III) में है। 5 से घड़ी की दिशा: 5-1-3 और 5-6-4। अतः 1 के विपरीत 6 है। (Re-check: I: 1,2,3. II: 1,3,5. 1 and 3 common -> 2 opposite 5. From II & III: 5 is common. Clockwise II: 5-1-3. Clockwise III: 5-6-4. So 1 opposite 6, 3 opposite 4. Correct answer is 6).',2,0,14,'Reasoning','Three positions of dice given. Which number is opposite ''1''? (I: 1,2,3; II: 1,3,5; III: 4,5,6)','From II and III, 5 is common. Rotating: 5-1-3 and 5-6-4. So 1 is opposite 6.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('-5ir0b4V5ePrqGV0atnFk','3bIu3iTfpozIvU5_YWpTk','सही वेन आरेख चुनें: स्तनधारी, गाय, कौआ','"[\"Two disjoint circles inside a large circle\",\"One circle inside another, third separate\",\"Three intersecting circles\",\"Three separate circles\"]"','1.0','गाय एक स्तनधारी है (अंदर), कौआ पक्षी है (अलग)।',2,0,15,'Reasoning','Choose correct Venn diagram: Mammals, Cow, Crow','Cow is Mammal (Inside), Crow is Bird (Separate).',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('yb-hV7VsjfY3n053401zb','3bIu3iTfpozIvU5_YWpTk','निर्णय लेना: आप एक साक्षात्कार बोर्ड के सदस्य हैं। एक उम्मीदवार आपका करीबी रिश्तेदार है। आप क्या करेंगे?','"[\"उसे अधिकतम अंक देंगे / Give him max marks\",\"पैनल को सूचित करेंगे और उस विशिष्ट साक्षात्कार से खुद को अलग कर लेंगे / Inform panel and recuse yourself from that specific interview\",\"उसे कठिन प्रश्न पूछेंगे / Ask him tough questions\",\"चुप रहेंगे / Remain silent\"]"','1.0','हितों के टकराव (Conflict of Interest) से बचने के लिए खुद को अलग करना नैतिक है।',2,0,16,'Decision Making','Decision Making: You are on an interview board. A candidate is your close relative. What will you do?','Recuse to avoid Conflict of Interest.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('9zfPGjQDa3bqiLIEqD3-o','3bIu3iTfpozIvU5_YWpTk','एक संख्या को जब 119 से विभाजित किया जाता है, तो शेषफल 19 बचता है। यदि उसी संख्या को 17 से विभाजित किया जाए, तो शेषफल क्या होगा?','"[\"19\",\"2\",\"3\",\"7\"]"','1.0','19 को 17 से विभाजित करें। शेषफल = 2। (क्योंकि 119, 17 से पूर्णतः विभाज्य है)।',2,0,17,'Quantitative Aptitude','A number when divided by 119 leaves remainder 19. If divided by 17, remainder will be?','Divide the remainder 19 by 17. Remainder is 2.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('vOktdXwW_rsIQOc6lEqt_','3bIu3iTfpozIvU5_YWpTk','A और B की आयु का अनुपात 3:5 है। 10 वर्ष बाद, अनुपात 5:7 होगा। A की वर्तमान आयु क्या है?','"[\"15\",\"30\",\"20\",\"25\"]"','0.0','(3x+10)/(5x+10) = 5/7. 21x+70 = 25x+50. 4x=20, x=5. A = 3*5 = 15.',2,0,18,'Quantitative Aptitude','Ratio of ages of A and B is 3:5. After 10 years, ratio will be 5:7. What is A''s present age?','Solve linear equation for x. Age is 15.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('5jZCRnLy8cTLhuMrMZ-YO','3bIu3iTfpozIvU5_YWpTk','एक फल विक्रेता के पास कुछ सेब थे। उसने 40% सेब बेचे और अभी भी उसके पास 420 सेब हैं। मूल रूप से उसके पास कितने सेब थे?','"[\"600\",\"700\",\"800\",\"588\"]"','1.0','शेष 60% = 420. कुल = (420/60)*100 = 700.',2,0,19,'Quantitative Aptitude','A fruit seller had some apples. He sells 40% and still has 420 apples. Originally, he had?','60% of Total = 420. Total = 700.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('3aDjmvRCe1EOvCGHhUXie','3bIu3iTfpozIvU5_YWpTk','यदि P का 50% = Q का 25% है, तो P = Q का x% है। x का मान क्या है?','"[\"50\",\"25\",\"100\",\"200\"]"','0.0','0.5P = 0.25Q => P/Q = 1/2. P, Q का 50% है।',2,0,20,'Quantitative Aptitude','If 50% of P = 25% of Q, then P = x% of Q. Find x.','P is half of Q, so 50%.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('tPJV6Je2TbD1NyVl1Glrv','3bIu3iTfpozIvU5_YWpTk','45 लीटर मिश्रण में दूध और पानी का अनुपात 4:1 है। इसमें कितना पानी और मिलाया जाए कि अनुपात 3:2 हो जाए?','"[\"10 L\",\"15 L\",\"20 L\",\"5 L\"]"','1.0','दूध = 36L, पानी = 9L। नया अनुपात 3:2। दूध स्थिर है (36L)। 3 इकाई = 36, तो 2 इकाई = 24L। पानी होना चाहिए 24L। अभी 9L है। मिलाना है: 24-9 = 15L।',2,0,21,'Quantitative Aptitude','In 45L mixture, milk:water is 4:1. How much water to add to make ratio 3:2?','Milk 36, Water 9. New Water needed for 3:2 with fixed milk: 24L. Add 15L.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('cip7DzBsLuHQ3SGv_ACkP','3bIu3iTfpozIvU5_YWpTk','एक त्रिभुज की भुजाएं 3 सेमी, 4 सेमी और 5 सेमी हैं। इसका क्षेत्रफल क्या है?','"[\"6 cm²\",\"12 cm²\",\"10 cm²\",\"15 cm²\"]"','0.0','यह एक समकोण त्रिभुज है (पाइथागोरस)। क्षेत्रफल = 1/2 * आधार * ऊंचाई = 1/2 * 3 * 4 = 6।',2,0,22,'Quantitative Aptitude','Sides of a triangle are 3cm, 4cm, 5cm. Area is?','Right angled triangle. 1/2 * 3 * 4 = 6.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('gP5jhHk2VvDqcxfd2JG7e','3bIu3iTfpozIvU5_YWpTk','यदि x% का y, 100 है और y% का z, 200 है, तो x और z के बीच संबंध ज्ञात करें।','"[\"z = x\",\"z = 2x\",\"x = 2z\",\"z = 4x\"]"','1.0','(xy/100)=100 => xy=10000. (yz/100)=200 => yz=20000. अनुपात: xy/yz = 10000/20000 => x/z = 1/2 => z=2x.',2,0,23,'Quantitative Aptitude','If x% of y is 100 and y% of z is 200, find relation between x and z.','Divide the two equations. z = 2x.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('vSHHYjWXOmtDv7GG6D38l','3bIu3iTfpozIvU5_YWpTk','शब्द ''MISSISSIPPI'' के अक्षरों को कितनी तरह से व्यवस्थित किया जा सकता है?','"[\"34650\",\"44650\",\"34560\",\"11!\"]"','0.0','कुल 11 अक्षर। M=1, I=4, S=4, P=2। सूत्र: 11! / (4! 4! 2!) = 39916800 / (24*24*2) = 34650।',2,0,24,'Quantitative Aptitude','In how many ways can letters of ''MISSISSIPPI'' be arranged?','Permutation with repetition formula.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('Ca6xHSczqD74z7aZBdDB2','3bIu3iTfpozIvU5_YWpTk','320 का 125% + 250 का 12% = ?','"[\"430\",\"420\",\"400\",\"450\"]"','0.0','(5/4)*320 + (30) = 400 + 30 = 430।',2,0,25,'Quantitative Aptitude','125% of 320 + 12% of 250 = ?','400 + 30 = 430.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('gypKRt-H6Dr3H6Ssn1YTn','3bIu3iTfpozIvU5_YWpTk','A, B और C की औसत आयु 25 वर्ष है। यदि A और B की औसत आयु 28 वर्ष है, तो C की आयु क्या है?','"[\"21\",\"24\",\"19\",\"29\"]"','2.0','कुल योग (A+B+C) = 75। (A+B) = 56। C = 75 - 56 = 19।',2,0,26,'Quantitative Aptitude','Average age of A, B, C is 25. If average of A and B is 28, what is C''s age?','Total 75 - Sum(A,B) 56 = 19.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('hJyrQxowWdj1tR70H459f','3bIu3iTfpozIvU5_YWpTk','एक घड़ी जो लगातार तेज हो रही है, रविवार सुबह 8 बजे 5 मिनट पीछे थी। अगली रविवार सुबह 8 बजे यह 5 मिनट और 48 सेकंड आगे थी। उसने सही समय कब दिखाया?','"[\"Wednesday 2 PM\",\"Wednesday 7:20 PM\",\"Tuesday 2 PM\",\"Thursday 7:20 AM\"]"','1.0','कुल लाभ = 5 + 5(4/5) = 54/5 मिनट। कुल समय = 168 घंटे। 5 मिनट के लाभ के लिए: (5 / (54/5)) * 168 = (25/54)*168 = 77 घंटे 46 मिनट। रविवार 8 AM + 77h 46m = बुधवार 7:20 PM। (Approx calculation 77.7 hours).',2,0,27,'Reasoning','A clock gaining uniformly was 5 min slow on Sun 8 AM. Next Sun 8 AM it was 5 min 48 sec fast. When was it correct?','Unitary method on time gained. 77.77 hours from Sun 8 AM is Wed evening.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('MI2c54nqEpFgmvbtyK0QJ','3bIu3iTfpozIvU5_YWpTk','लुप्त पद ज्ञात करें: 2, 3, 5, 7, 11, ?, 17','"[\"12\",\"13\",\"14\",\"15\"]"','1.0','लगातार अभाज्य संख्याएं (Prime Numbers)।',2,0,28,'Reasoning','Find missing term: 2, 3, 5, 7, 11, ?, 17','Consecutive prime numbers.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('vFKndOANCqyPpgfuxN79H','3bIu3iTfpozIvU5_YWpTk','यदि ''जल'' को ''नीला'', ''नीला'' को ''लाल'', ''लाल'' को ''सफेद'', ''सफेद'' को ''आकाश'' कहा जाए, तो दूध का रंग क्या है?','"[\"Sky\",\"White\",\"Red\",\"Blue\"]"','0.0','दूध सफेद होता है, और ''सफेद'' को ''आकाश'' कहा गया है।',2,0,29,'Reasoning','If ''Water'' is ''Blue'', ''Blue'' is ''Red'', ''Red'' is ''White'', ''White'' is ''Sky'', what is color of milk?','Milk is white, White is called Sky.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('zdfiQswMdfvacaEdW9Y_6','3bIu3iTfpozIvU5_YWpTk','6 से 50 के बीच कितनी संख्याएं 3 से विभाज्य हैं लेकिन 4 से नहीं?','"[\"12\",\"10\",\"11\",\"9\"]"','2.0','3 के गुणज (6 से 50): 6,9,12,15,18,21,24,27,30,33,36,39,42,45,48 (कुल 15)। 4 से विभाज्य हटाएं (12, 24, 36, 48)। 15 - 4 = 11।',2,0,30,'Quantitative Aptitude','How many numbers between 6 and 50 are divisible by 3 but not by 4?','Multiples of 3 minus multiples of 12. 15 - 4 = 11.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('VMGGNSPQBjYRpbMKHAmjw','3bIu3iTfpozIvU5_YWpTk','250 मीटर लंबी ट्रेन एक खंभे को 15 सेकंड में पार करती है। ट्रेन की गति किमी/घंटा में क्या है?','"[\"60\",\"40\",\"50\",\"72\"]"','0.0','गति m/s = 250/15 = 50/3. किमी/घंटा = (50/3) * (18/5) = 10 * 6 = 60.',2,0,31,'Quantitative Aptitude','A 250m train crosses a pole in 15 sec. Speed in km/hr?','Convert m/s to km/hr by multiplying 18/5.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('gnDwlamdX7SYWu35_uf6l','3bIu3iTfpozIvU5_YWpTk','यदि a:b = 2:3 और b:c = 4:5, तो a:b:c ज्ञात करें।','"[\"8:12:15\",\"2:3:5\",\"8:15:12\",\"6:12:15\"]"','0.0','a:b = 8:12 (4 से गुणा), b:c = 12:15 (3 से गुणा)। a:b:c = 8:12:15।',2,0,32,'Quantitative Aptitude','If a:b = 2:3 and b:c = 4:5, find a:b:c.','Equate b term. 8:12:15.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('kFmUdAD-TfBqW0Ik7d2uD','3bIu3iTfpozIvU5_YWpTk','दी गई आकृति में त्रिभुजों की संख्या ज्ञात करें (तारा आकृति - पेंटाग्राम)।','"[\"10\",\"5\",\"8\",\"12\"]"','0.0','5 छोटे बाहरी त्रिभुज + 5 बड़े त्रिभुज (हर शीर्ष से)। कुल 10।',2,0,33,'Reasoning','Count triangles in the given figure (Standard Pentagram Star).','Standard pentagram has 10 triangles.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('cLXmOMlOXF9feF9Jka5BE','3bIu3iTfpozIvU5_YWpTk','पाई चार्ट व्याख्या: यदि ''किराये'' पर व्यय 72° है और ''बचत'' 60° है, तो बचत और किराये का अनुपात क्या है?','"[\"6:5\",\"5:6\",\"4:5\",\"1:2\"]"','1.0','अनुपात 60:72 = 5:6।',2,0,34,'Quantitative Aptitude','Pie Chart: If Rent is 72° and Savings is 60°, what is ratio of Savings to Rent?','60/72 simplifies to 5/6.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ULMXMeD7yWuGweX_uEyuT','3bIu3iTfpozIvU5_YWpTk','एक आयत की लंबाई चौड़ाई से 5 सेमी अधिक है। यदि परिधि 50 सेमी है, तो क्षेत्रफल क्या है?','"[\"150 cm²\",\"100 cm²\",\"200 cm²\",\"125 cm²\"]"','0.0','2(b + b+5) = 50. 2b+5 = 25. 2b=20, b=10, l=15. क्षेत्रफल = 150।',2,0,35,'Quantitative Aptitude','Length of rectangle is 5cm more than breadth. Perimeter is 50cm. Area?','Find dimensions l=15, b=10. Area 150.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('VA1_eMKpK-k0i3Nx5KQ8C','3bIu3iTfpozIvU5_YWpTk','कथन: सभी पेन कप हैं। सभी कप कांच हैं। निष्कर्ष: (I) कुछ पेन कांच हैं। (II) कुछ कांच कप हैं।','"[\"केवल I\",\"केवल II\",\"दोनों I और II\",\"कोई नहीं\"]"','2.0','चूंकि सभी पेन कांच हैं, तो ''कुछ'' भी सत्य है। ''सभी'' से ''कुछ'' का निहितार्थ सही होता है। (All implies Some).',2,0,36,'Reasoning','Statements: All pens are cups. All cups are glasses. Conclusions: (I) Some pens are glasses. (II) Some glasses are cups.','Nested circles. All implications valid.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('oY9FSCM7T0mrJhtFNXPts','3bIu3iTfpozIvU5_YWpTk','1000 का 33.33% का 0.15% = ?','"[\"0.5\",\"0.05\",\"0.495\",\"5\"]"','0.0','33.33% = 1/3. 1000/3 = 333.33. इसका 0.15% = 333.33 * 0.0015 = 0.5।',2,0,37,'Quantitative Aptitude','0.15% of 33.33% of 1000 = ?','Calculation yields approx 0.5.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('0AfvwK-FvJOnajKcbHV9j','3bIu3iTfpozIvU5_YWpTk','सरल ब्याज पर एक राशि 10 वर्षों में दोगुनी हो जाती है। ब्याज दर क्या है?','"[\"10%\",\"5%\",\"20%\",\"8%\"]"','0.0','R = (100 * (n-1)) / T. R = 100 * 1 / 10 = 10%.',2,0,38,'Quantitative Aptitude','A sum doubles in 10 years at Simple Interest. Rate percent?','Formula R = 100/T for doubling.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('XV65RR_scyF93nZkrRd1o','3bIu3iTfpozIvU5_YWpTk','सही गणना: 33. विकल्प में 33 चुनें।','"[\"32\",\"33\",\"34\",\"30\"]"','1.0','C, A से 5 नीचे है (रैंक 11)। C और B के बीच भी 5 का अंतर होगा। C(11) + 5 = B का रैंक ऊपर से (16)। कुल = ऊपर + नीचे - 1 = 16 + 18 - 1 = 33? (Let''s recheck logic). A(6). C is 5 below A -> C is 11th. C is middle of A & B. Gap A-C is 4 students. Gap C-B is 4 students. B is 11+5=16th from top. Total = 16 (Top) + 18 (Bottom) - 1 = 33. Correct option logic: Wait. If C is 5 ranks below A, gap is 5. Rank difference is 5. So B is 5 below C. Top rank of B = 6+5+5 = 16. Total = 16+18-1 = 33. Let''s adjust options or pick close one if specific logic varies. Answer 33.',2,0,39,'Reasoning','Rank of A is 6th from top, B is 18th from bottom. C is 5 ranks below A and exactly between A and B. Total students?','A(6) -> C(11) -> B(16 from top). Total = 16+18-1 = 33.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('SYReJvZbXuFLzIMbb54qZ','3bIu3iTfpozIvU5_YWpTk','दो सिक्कों को उछालने पर, अधिकतम एक ''Head'' आने की प्रायिकता क्या है?','"[\"3/4\",\"1/2\",\"1/4\",\"1\"]"','0.0','अनुकूल परिणाम: TT, HT, TH (HH को छोड़कर सब)। 3/4।',2,0,40,'Quantitative Aptitude','Tossing 2 coins, probability of getting AT MOST one Head?','Cases: TT, TH, HT. (3 cases). Total 4.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('PsfawNcxtnU9R9JvAP0e2','3bIu3iTfpozIvU5_YWpTk','समानता (Analogy): मोतियाबिंद : आंख :: निमोनिया : ?','"[\"मस्तिष्क / Brain\",\"फेफड़े / Lungs\",\"कान / Ear\",\"तंत्रिका / Nerves\"]"','1.0','मोतियाबिंद आंख का रोग है, निमोनिया फेफड़ों का।',2,0,41,'Reasoning','Analogy: Cataract : Eye :: Pneumonia : ?','Disease and organ affected.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('ZxUbwI05ncotyEd7UqkXP','3bIu3iTfpozIvU5_YWpTk','श्रृंखला: 2, 5, 11, 23, 47, ?','"[\"95\",\"94\",\"97\",\"80\"]"','0.0','पैटर्न: (x * 2) + 1. 47*2+1 = 95.',2,0,42,'Reasoning','Series: 2, 5, 11, 23, 47, ?','x2 + 1 logic.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('3lWezB3onf2PyKiyUGSZx','3bIu3iTfpozIvU5_YWpTk','''मौन'' (Silence) संचार का कौन सा रूप है?','"[\"शाब्दिक / Verbal\",\"अशाब्दिक / Non-Verbal\",\"लिखित / Written\",\"औपचारिक / Formal\"]"','1.0','मौन एक शक्तिशाली अशाब्दिक संकेत है।',2,0,43,'Communication','What form of communication is ''Silence''?','Silence is non-verbal communication.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('DxLZDxaV75d-5ZwnZQy5H','3bIu3iTfpozIvU5_YWpTk','प्रभावी संचार के लिए, प्रेषक को क्या प्राथमिकता देनी चाहिए?','"[\"जटिल शब्द / Complex words\",\"लंबे वाक्य / Long sentences\",\"श्रोता विश्लेषण / Audience Analysis\",\"तेज गति / High speed\"]"','2.0','श्रोता को समझना संदेश को प्रभावी बनाने की कुंजी है।',2,0,44,'Communication','For effective communication, what should the sender prioritize?','Knowing the audience is key.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('_PFf_3SBiX-11wvQSon5t','3bIu3iTfpozIvU5_YWpTk','संचार नेटवर्क को सुमेलित करें:','"[\"(1)-(c), (2)-(d), (3)-(a), (4)-(b)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(b), (2)-(c), (3)-(d), (4)-(a)\",\"(1)-(d), (2)-(a), (3)-(b), (4)-(c)\"]"','0.0','Wheel has a center leader. Chain is linear. All Channel is open/equal.',2,0,45,'Communication','Match Communication Networks:','Wheel-Centralized; Chain-Linear; All Channel-Equal.',60,'matching','[{"id":"(1)","label":"Wheel Network","match":"Equal participation","matchId":"(a)"},{"id":"(2)","label":"Chain Network","match":"No centralized control","matchId":"(b)"},{"id":"(3)","label":"All Channel","match":"Centralized leader","matchId":"(c)"},{"id":"(4)","label":"Circle Network","match":"Linear flow","matchId":"(d)"}]',NULL);
INSERT INTO questions VALUES('uWyBeGol3Sqay78Iid_FG','3bIu3iTfpozIvU5_YWpTk','सांस्कृतिक भिन्नताओं के कारण होने वाली गलतफहमी किस प्रकार की बाधा है?','"[\"शारीरिक / Physical\",\"सिमेंटिक / Semantic\",\"सामाजिक-मनोवैज्ञानिक / Socio-Psychological\",\"संगठनात्मक / Organizational\"]"','2.0','संस्कृति सामाजिक और मनोवैज्ञानिक पृष्ठभूमि का हिस्सा है।',2,0,46,'Communication','Misunderstanding due to cultural differences is which type of barrier?','Cultural barriers fall under Socio-Psychological.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('dJZBfZVoeTusmaX8fjoYX','3bIu3iTfpozIvU5_YWpTk','''काइनेसिक्स'' में ''Oculesics'' का संबंध किससे है?','"[\"गंध / Smell\",\"आंखों का व्यवहार / Eye behavior\",\"आवाज / Voice\",\"स्पर्श / Touch\"]"','1.0','Oculesics आंखों के संपर्क और गतिविधियों का अध्ययन है।',2,0,47,'Communication','In Kinesics, ''Oculesics'' relates to?','Study of eye movement and contact.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('oCmqNDgihf-tOsReTan8X','3bIu3iTfpozIvU5_YWpTk','5 संख्याओं का औसत 27 है। यदि एक संख्या हटा दी जाए, तो औसत 25 हो जाता है। हटाई गई संख्या क्या है?','"[\"35\",\"25\",\"27\",\"30\"]"','0.0','योग अंतर: (5*27) - (4*25) = 135 - 100 = 35।',2,0,48,'Quantitative Aptitude','Average of 5 numbers is 27. If one is excluded, average becomes 25. Excluded number?','Sum difference: 135 - 100 = 35.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('GStMCe-7LSWBZZDtH-hZ_','3bIu3iTfpozIvU5_YWpTk','शतरंज के बोर्ड में कितने वर्ग होते हैं (सभी आकारों के)?','"[\"64\",\"204\",\"100\",\"256\"]"','1.0','सूत्र: 1² + 2² + ... + 8² = 204।',2,0,49,'Quantitative Aptitude','How many squares are there on a chessboard (of all sizes)?','Sum of squares from 1 to 8.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('dHHz0vS72-b_MlOMn3bvp','3bIu3iTfpozIvU5_YWpTk','यदि ''A'' + ''A'' = 2, ''B'' + ''B'' = 4, तो ''A'' + ''B'' = ?','"[\"3\",\"6\",\"5\",\"2\"]"','0.0','A=1, B=2. 1+2=3.',2,0,50,'Reasoning','If ''A''+''A''=2, ''B''+''B''=4, then ''A''+''B''=?','Values of A and B.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('yjhlRpznhny43-ffIKkdC','3bIu3iTfpozIvU5_YWpTk','लेन-देन विश्लेषण (Transactional Analysis) में ''माता-पिता अहंकार अवस्था'' (Parent Ego State) क्या दर्शाती है?','"[\"तार्किक सोच / Logical thinking\",\"सिखाए गए व्यवहार और नियम / Taught behaviors and rules\",\"बचकाना व्यवहार / Childish behavior\",\"रचनात्मकता / Creativity\"]"','1.0','पैरेंट ईगो स्टेट में अधिकार, नियम और सीखे गए पूर्वाग्रह शामिल होते हैं।',2,0,51,'Communication','In Transactional Analysis, what does ''Parent Ego State'' represent?','Represents authority, rules, and learned values.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('PFY42YxPG0s6gAuDpDhrX','3bIu3iTfpozIvU5_YWpTk','संचार में ''प्रतिपुष्टि'' (Feedback) कब पूरी होती है?','"[\"जब संदेश भेजा जाता है / When message is sent\",\"जब रिसीवर संदेश को समझकर प्रतिक्रिया देता है / When receiver understands and responds\",\"जब शोर होता है / When there is noise\",\"जब चैनल चुना जाता है / When channel is selected\"]"','1.0','प्रतिक्रिया लूप रिसीवर के जवाब के साथ बंद होता है।',2,0,52,'Communication','When is ''Feedback'' complete in communication?','Cycle closes with response.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('syrsL-pjyyamGvinfGr8D','3bIu3iTfpozIvU5_YWpTk','एक संख्या का 3/5 भाग उसके 40% से 40 अधिक है। संख्या क्या है?','"[\"100\",\"150\",\"200\",\"400\"]"','2.0','3/5 = 60%. 60%x - 40%x = 40. 20%x = 40. x = 200.',2,0,53,'Quantitative Aptitude','3/5 of a number is 40 more than its 40%. The number is?','20% difference equals 40. Total 200.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('P52wXW8OegbF9OYFgPwuU','3bIu3iTfpozIvU5_YWpTk','यदि x + 1/x = 2, तो x¹⁰⁰ + 1/x¹⁰⁰ = ?','"[\"2\",\"0\",\"1\",\"100\"]"','0.0','यदि x + 1/x = 2, तो x = 1 संतुष्ट करता है। 1 + 1 = 2.',2,0,54,'Quantitative Aptitude','If x + 1/x = 2, then x¹⁰⁰ + 1/x¹⁰⁰ = ?','x=1 satisfies the condition.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('HMAmYOvUhWLzDcs13w8hh','3bIu3iTfpozIvU5_YWpTk','प्रथम 20 विषम संख्याओं का औसत क्या है?','"[\"19\",\"20\",\"21\",\"400\"]"','1.0','प्रथम n विषम संख्याओं का औसत n होता है। (योग n², औसत n²/n = n)।',2,0,55,'Quantitative Aptitude','What is the average of first 20 odd numbers?','Average of first n odd numbers is n.',60,'standard',NULL,NULL);
INSERT INTO questions VALUES('CLbu_U2gD4a9haCDjPLO-','3bIu3iTfpozIvU5_YWpTk',replace('**निर्देश: गद्यांश पढ़ें:**\nसौर ऊर्जा नवीकरणीय ऊर्जा का एक प्रमुख स्रोत है। यह पर्यावरण के अनुकूल है और कार्बन उत्सर्जन को कम करता है। भारत में सौर ऊर्जा की अपार संभावनाएँ हैं। सरकार इसे बढ़ावा देने के लिए सब्सिडी प्रदान कर रही है।\n\n----------------------------\n**प्रश्न:** सौर ऊर्जा कैसा स्रोत है?','\n',char(10)),'"[\"अनवीकरणीय / Non-renewable\",\"नवीकरणीय / Renewable\",\"खतरनाक / Dangerous\",\"महंगा / Expensive\"]"','1.0',NULL,2,0,56,'Reading Comprehension',replace('**Direction: Read passage:**\nSolar energy is a major source of renewable energy. It is eco-friendly and reduces carbon emissions. India has immense potential for solar energy. The government is providing subsidies to promote it.\n\n----------------------------\n**Question:** What kind of source is solar energy?','\n',char(10)),NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('GxNpHHE9RNTFskGz20mFh','3bIu3iTfpozIvU5_YWpTk',replace('**निर्देश: गद्यांश पढ़ें:**\nसौर ऊर्जा नवीकरणीय ऊर्जा का एक प्रमुख स्रोत है। यह पर्यावरण के अनुकूल है और कार्बन उत्सर्जन को कम करता है। भारत में सौर ऊर्जा की अपार संभावनाएँ हैं। सरकार इसे बढ़ावा देने के लिए सब्सिडी प्रदान कर रही है।\n\n----------------------------\n**प्रश्न:** सौर ऊर्जा किसे कम करता है?','\n',char(10)),'"[\"बिजली / Electricity\",\"कार्बन उत्सर्जन / Carbon Emissions\",\"पानी / Water\",\"रोजगार / Employment\"]"','1.0',NULL,2,0,57,'Reading Comprehension',replace('**Direction: Read passage:**\nSolar energy is a major source of renewable energy. It is eco-friendly and reduces carbon emissions. India has immense potential for solar energy. The government is providing subsidies to promote it.\n\n----------------------------\n**Question:** What does solar energy reduce?','\n',char(10)),NULL,60,'standard',NULL,NULL);
