INSERT INTO questions VALUES('DVUFWaSG6i5fl7TK4juzm','3bIu3iTfpozIvU5_YWpTk','''चक्रपाणि'' में समास है:','"[\"बहुव्रीहि\",\"द्विगु\",\"तत्पुरुष\",\"कर्मधारय\"]"','0.0','चक्र है हाथ (पाणि) में जिसके (विष्णु) -> बहुव्रीहि।',2,0,87,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
