INSERT INTO questions VALUES('EZkNaXvb517pVAmCMmdSY','3bIu3iTfpozIvU5_YWpTk','''नाक रगड़ना'' मुहावरे का अर्थ:','"[\"खुजली करना\",\"दीनतापूर्वक प्रार्थना करना\",\"गुस्सा होना\",\"बीमार होना\"]"','1.0','माफी मांगना या विनती करना।',2,0,91,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
