INSERT INTO questions VALUES('DMNc6TVZVLcK5v1TFne3G','-chUrwczP5DdYXa_jZP2M','''यद्यपि'' का संधि विच्छेद है:','"[\"यदि + अपि\",\"यद + अपि\",\"यदा + अपि\",\"यदी + अपि\"]"','0.0','यण संधि।',2,0,81,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
