INSERT INTO questions VALUES('bDgoQezKuhaimDBq3GcR-','-chUrwczP5DdYXa_jZP2M','अशुद्ध वाक्य छाँटें:','"[\"राम ने रावण को मारा।\",\"मेरे को घर जाना है।\",\"सीता किताब पढ़ रही है।\",\"वे लोग जा रहे हैं।\"]"','1.0','''मुझे घर जाना है'' सही है। ''मेरे को'' गलत है।',2,0,89,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
