INSERT INTO questions VALUES('QYpPe2FwTABAwYx-UPKga','-chUrwczP5DdYXa_jZP2M','''घी के दिए जलाना'' मुहावरे का अर्थ:','"[\"रोशनी करना\",\"खुशी मनाना\",\"पूजा करना\",\"गरीबी आना\"]"','1.0','अत्यधिक खुशी मनाना।',2,0,91,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
