INSERT INTO questions VALUES('7gDrDjWZgx2HSnH7_1G7b','-chUrwczP5DdYXa_jZP2M','''चरण कमल बन्दौ हरिराई'' में अलंकार:','"[\"उपमा\",\"रूपक\",\"उत्प्रेक्षा\",\"श्लेष\"]"','1.0','रूपक अलंकार (चरणों को कमल माना गया है)।',2,0,93,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('e7uz-RRtL1Ek7gr1gqqzQ','-chUrwczP5DdYXa_jZP2M','''खोदा पहाड़ निकली चुहिया'' का अर्थ:','"[\"पहाड़ खोदना\",\"अधिक परिश्रम कम लाभ\",\"चूहा पकड़ना\",\"नुकसान होना\"]"','1.0','अधिक परिश्रम, फल कम।',2,0,94,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('m5TKebtSwU07oXRh2il5L','-chUrwczP5DdYXa_jZP2M','''नयन'' का संधि विच्छेद:','"[\"ने + अन\",\"न + यन\",\"नै + अन\",\"नय + न\"]"','0.0','अयादि संधि (ने + अन = नयन)।',2,0,95,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('izQm8WqQR8GDx3F1cFPuO','-chUrwczP5DdYXa_jZP2M','प्रश्नवाचक चिह्न कौन सा है?','"[\"।\",\",\",\"?\",\"!\"]"','2.0','?',2,0,96,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('BwIMI1tc-LVhxyRxaVM-J','-chUrwczP5DdYXa_jZP2M','''हवा से बातें करना'' का अर्थ:','"[\"पागल होना\",\"बहुत तेज दौड़ना\",\"धीरे चलना\",\"सपने देखना\"]"','1.0','बहुत तेज गति से चलना/दौड़ना।',2,0,97,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('1mxIj8dWwOVsN2bNbIdWV','-chUrwczP5DdYXa_jZP2M','''पानी'' शब्द का वचन:','"[\"एकवचन\",\"बहुवचन\",\"द्विवचन\",\"इनमें से कोई नहीं\"]"','0.0','पानी सदैव एकवचन में प्रयुक्त होता है (द्रव्यवाचक संज्ञा)।',2,0,98,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
INSERT INTO questions VALUES('BCPEYMv6AaMplnEEjZiAM','-chUrwczP5DdYXa_jZP2M','दोहा छंद में कितनी मात्राएं होती हैं?','"[\"24 (13-11)\",\"26\",\"28\",\"16\"]"','0.0','पहले और तीसरे चरण में 13, दूसरे और चौथे में 11। कुल 24।',2,0,99,'Hindi Grammar','N/A',NULL,60,'standard',NULL,NULL);
