INSERT INTO questions VALUES('DLrAylcf07DPPyVwFdFhC','qps5_uf8HUURKTzaRtYp1','अनुच्छेद 338 किस आयोग से संबंधित है?','"[\"महिला आयोग\",\"अल्पसंख्यक आयोग\",\"मानवाधिकार आयोग\",\"अनुसूचित जाति आयोग\"]"','3.0',NULL,2,0,32,'Polity','Article 338 relates to which commission?',NULL,60,'standard',NULL,NULL);
