PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS `attempt_answers` (
	`id` text PRIMARY KEY NOT NULL,
	`attempt_id` text NOT NULL,
	`question_id` text NOT NULL,
	`user_answer` text,
	`is_correct` integer,
	`time_taken_seconds` integer,
	FOREIGN KEY (`attempt_id`) REFERENCES `user_attempts`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`question_id`) REFERENCES `questions`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE IF NOT EXISTS `questions` (
	`id` text PRIMARY KEY NOT NULL,
	`test_id` text NOT NULL,
	`question_text` text NOT NULL,
	`options` text NOT NULL,
	`correct_answer` text NOT NULL,
	`explanation` text,
	`marks` integer NOT NULL,
	"negative_marks" real DEFAULT 1,
	`order` integer NOT NULL, `subject` text, `question_text_en` text, `explanation_en` text, `ideal_time` integer DEFAULT 60, `type` text DEFAULT 'standard', `match_pairs` text, `deleted_at` integer,
	FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE IF NOT EXISTS `tests` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`slug` text NOT NULL,
	`duration_minutes` integer NOT NULL,
	`total_marks` integer NOT NULL,
	`type` text NOT NULL,
	`is_pro` integer DEFAULT false,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `unit_id` text, `tags` text, `max_retries` integer, `total_questions` integer DEFAULT 0, `topic_id` text, `display_order` integer DEFAULT 0, `deleted_at` integer, `title_en` text, `is_free_access` integer DEFAULT false, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true, `is_hidden` integer DEFAULT false);
CREATE TABLE IF NOT EXISTS `mppsc_users` (
	`id` text PRIMARY KEY NOT NULL,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`email` text NOT NULL,
	`password` text NOT NULL,
	`name` text,
	`is_subscribed` integer DEFAULT false
, `role` text DEFAULT 'guest', `plan_tier` text DEFAULT 'free', `admin_secret` text, `deleted_at` integer, `access_expires_at` integer, `phone` text, `metadata` text, `previous_user_id` text, `is_active` integer DEFAULT true);
CREATE TABLE IF NOT EXISTS `syllabus_topics` (
	`id` text PRIMARY KEY NOT NULL,
	`unit_id` text NOT NULL,
	`title` text NOT NULL,
	`title_en` text,
	`content` text NOT NULL,
	`content_en` text,
	`order` integer NOT NULL,
	`is_free` integer DEFAULT false,
	`img_url` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, `ai_content` text, `ai_content_en` text, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true);
CREATE TABLE IF NOT EXISTS `content_blogs` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`content` text NOT NULL,
	`category` text NOT NULL,
	`image_url` text,
	`reading_time` integer,
	`is_published` integer DEFAULT false,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `content_type` text DEFAULT 'blog' NOT NULL, `unit_id` text, `topic_id` text, `is_premium` integer DEFAULT true, `is_free_access` integer DEFAULT false, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true, `is_hidden` integer DEFAULT false);
CREATE TABLE IF NOT EXISTS `support_tickets` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`name` text NOT NULL,
	`email` text NOT NULL,
	`phone` text,
	`category` text DEFAULT 'general',
	`message` text NOT NULL,
	`status` text DEFAULT 'open',
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS `payment_exit_reasons` (
	`id` text PRIMARY KEY NOT NULL,
	`reason` text NOT NULL,
	`custom_reason` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS "__drizzle_migrations" (
			id SERIAL PRIMARY KEY,
			hash text NOT NULL,
			created_at numeric
		);
CREATE TABLE IF NOT EXISTS `test_leaderboard` (
	`id` text PRIMARY KEY NOT NULL,
	`test_id` text NOT NULL,
	`user_id` text,
	`display_name` text NOT NULL,
	`score` real NOT NULL,
	`percentage` real,
	`time_taken_seconds` integer,
	`rank` integer,
	`is_fake` integer DEFAULT 0,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS `feedbacks` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`name` text NOT NULL,
	`email` text,
	`phone` text,
	`message` text NOT NULL,
	`rating` integer NOT NULL,
	`category` text DEFAULT 'other',
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, `role` text, `location` text);
CREATE TABLE IF NOT EXISTS `guests` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`email` text,
	`mobile` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS `pricing_config` (
	`id` text PRIMARY KEY DEFAULT 'default' NOT NULL,
	`lite_price` integer DEFAULT 99,
	`lite_original_price` integer DEFAULT 299,
	`lite_validity_text` text DEFAULT 'Valid till MPPSC 2026 Prelims',
	`lite_months` integer DEFAULT 8,
	`pro_price` integer DEFAULT 299,
	`pro_original_price` integer DEFAULT 999,
	`pro_validity_text` text DEFAULT 'Valid till MPPSC 2026 Mains',
	`pro_months` integer DEFAULT 12,
	`upgrade_price` integer DEFAULT 199,
	`upgrade_original_price` integer DEFAULT 299,
	`urgency_text` text DEFAULT 'Special pricing for first 100 students',
	`urgency_text_hi` text DEFAULT 'पहले 100 छात्रों के लिए विशेष मूल्य',
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `students_bought` integer DEFAULT 23, `coupon_discount_lite` integer DEFAULT 9, `coupon_discount_pro` integer DEFAULT 50);
CREATE TABLE IF NOT EXISTS `verification_tokens` (
	`identifier` text NOT NULL,
	`token` text NOT NULL,
	`expires` integer NOT NULL,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS `test_attempt_limits` (
	`test_type` text PRIMARY KEY NOT NULL,
	`max_attempts` integer
);
CREATE TABLE IF NOT EXISTS `mppsc_user_activities` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`user_email` text NOT NULL,
	`user_name` text,
	`admin_id` text,
	`action` text NOT NULL,
	`details` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE IF NOT EXISTS "user_attempts" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`test_id` text NOT NULL,
	`start_time` integer NOT NULL,
	`end_time` integer,
	`score` real,
	`is_completed` integer DEFAULT false,
	`deleted_at` integer,
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE IF NOT EXISTS "topic_revisions" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`topic_id` text NOT NULL,
	`unit_id` text NOT NULL,
	`revision_count` integer DEFAULT 0,
	`last_revised_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE IF NOT EXISTS "payments" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`order_id` text NOT NULL,
	`payment_id` text,
	`signature` text,
	`amount` integer NOT NULL,
	`plan_tier` text,
	`status` text DEFAULT 'created' NOT NULL,
	`currency` text DEFAULT 'INR' NOT NULL,
	`receipt` text,
	`notes` text,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE IF NOT EXISTS `referral_coupons` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`owner_user_id` text NOT NULL,
	`discount_lite` integer DEFAULT 9,
	`discount_pro` integer DEFAULT 50,
	`redeemed_by_user_id` text,
	`redeemed_at` integer,
	`is_active` integer DEFAULT true,
	`source` text DEFAULT 'auto',
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`owner_user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE UNIQUE INDEX `mppsc_users_email_unique` ON `mppsc_users` (`email`);
CREATE UNIQUE INDEX `tests_slug_unique` ON `tests` (`slug`);
CREATE UNIQUE INDEX `content_blogs_slug_unique` ON `content_blogs` (`slug`);
CREATE INDEX `test_score_idx` ON `test_leaderboard` (`test_id`,`score`);
CREATE INDEX `attempt_id_idx` ON `attempt_answers` (`attempt_id`);
CREATE INDEX `question_id_idx` ON `attempt_answers` (`question_id`);
CREATE INDEX `unit_order_idx` ON `syllabus_topics` (`unit_id`,`order`);
CREATE INDEX `idx_attempt_question` ON `attempt_answers` (`attempt_id`,`question_id`);
CREATE INDEX `idx_questions_subject` ON `questions` (`test_id`,`subject`);
CREATE INDEX `idx_leaderboard_ranking` ON `test_leaderboard` (`test_id`,`score`,`time_taken_seconds`);
CREATE INDEX `idx_tests_slug` ON `tests` (`slug`);
CREATE INDEX `idx_tests_type_ispro` ON `tests` (`type`,`is_pro`);
CREATE INDEX `idx_users_email` ON `mppsc_users` (`email`);
CREATE INDEX `idx_feedbacks_created_at` ON `feedbacks` (`created_at`);
CREATE INDEX `idx_feedbacks_category` ON `feedbacks` (`category`);
CREATE INDEX `idx_guests_email` ON `guests` (`email`);
CREATE INDEX `idx_guests_mobile` ON `guests` (`mobile`);
CREATE INDEX `idx_feedbacks_role` ON `feedbacks` (`role`);
CREATE INDEX `idx_verification_tokens_identifier` ON `verification_tokens` (`identifier`);
CREATE INDEX `idx_verification_tokens_token` ON `verification_tokens` (`token`);
CREATE INDEX `idx_activities_user_id` ON `mppsc_user_activities` (`user_id`);
CREATE INDEX `idx_activities_action` ON `mppsc_user_activities` (`action`);
CREATE INDEX `idx_activities_created_at` ON `mppsc_user_activities` (`created_at`);
CREATE INDEX `user_id_idx` ON `user_attempts` (`user_id`);
CREATE INDEX `test_id_idx` ON `user_attempts` (`test_id`);
CREATE INDEX `user_test_idx` ON `user_attempts` (`user_id`,`test_id`);
CREATE INDEX `completed_idx` ON `user_attempts` (`is_completed`,`end_time`);
CREATE INDEX `idx_user_test_completed` ON `user_attempts` (`user_id`,`test_id`,`is_completed`,`end_time`);
CREATE INDEX `idx_attempts_by_date` ON `user_attempts` (`user_id`,`end_time`);
CREATE INDEX `idx_user_attempts_completion_score` ON `user_attempts` (`user_id`,`is_completed`,`score`);
CREATE UNIQUE INDEX `payments_payment_id_unique` ON `payments` (`payment_id`);
CREATE INDEX `idx_payments_order_id` ON `payments` (`order_id`);
CREATE INDEX `idx_payments_user_id` ON `payments` (`user_id`);
CREATE INDEX `idx_payments_status` ON `payments` (`status`);
CREATE INDEX `idx_payments_payment_id` ON `payments` (`payment_id`);
CREATE UNIQUE INDEX `referral_coupons_code_unique` ON `referral_coupons` (`code`);
CREATE INDEX `idx_coupons_code` ON `referral_coupons` (`code`);
CREATE INDEX `idx_coupons_owner` ON `referral_coupons` (`owner_user_id`);
COMMIT;
